INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C1','soc',6,2,'u2',1,'시장과 시장경제 — 시장은 물건이나 서비스의 거래가 이루어지는 곳(장소와 상관없이 온라인 쇼핑도 시장), 가계는 살림을 꾸려 가는 생활 공동체, 기업은 이윤을 목적으로 생산·판매하는 조직(이윤 = 수입 − 비용) · 가격은 사람들이 필요로 하는 양과 기업이 제공하는 양을 함께 견주어 정해지고, 시장에서 가계와 기업이 자유롭게 경쟁하며 경제활동을 하는 방식이 시장경제 — 자유로운 경쟁으로 더 좋은 품질의 물건을 살 수 있음',ARRAY['[6사11-01] 시장경제에서 가계와 기업의 역할을 이해하고, 근로자의 권리와 기업의 자유 및 사회적 책임을 탐색한다.']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C2','soc',6,2,'u2',2,'가계와 기업의 역할과 관계 — 가계는 기업의 생산 활동에 참여해 소득을 얻고 그 소득으로 소비하며 적은 비용으로 가장 큰 만족을 얻는 합리적 선택(기준을 정해 비교)을 하려 하고, 기업은 일자리를 제공하고 물건·서비스를 생산·판매해 이윤을 얻으며 급여 지급·연구·세금 납부를 함 · 가계와 기업은 시장에서 만나 서로 도움을 주고받아 어느 한쪽이 역할을 못하면 다른 쪽도 어려워짐 · 기업의 성장 노력은 품질 좋고 값싼 상품·일자리·나라 경제 발전으로 이어짐',ARRAY['[6사11-01] 시장경제에서 가계와 기업의 역할을 이해하고, 근로자의 권리와 기업의 자유 및 사회적 책임을 탐색한다.']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C3','soc',6,2,'u2',3,'근로자의 권리 보호 — 가계는 노동력을 제공하는 근로자로서 경제활동에 참여하고, 휴가·휴식 같은 권리가 지켜지지 않으면 근로자·기업·소비자 모두 어려워짐 · 근로자는 단체를 만들거나 가입하고, 근로 조건을 기업과 협의하고, 함께 단체로 행동할 수 있으며, 나라는 법과 제도(최저 임금 제도·육아 휴직 제도 등)로 이를 보호 — 노동력은 경제활동에서 중요하고 근로자와 기업은 서로 의존하기 때문',ARRAY['[6사11-01] 시장경제에서 가계와 기업의 역할을 이해하고, 근로자의 권리와 기업의 자유 및 사회적 책임을 탐색한다.']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C4','soc',6,2,'u2',4,'기업의 자유와 사회적 책임 — 헌법이 보장하는 기업의 자유로 기업을 세워 자유롭게 경쟁하고 무엇을 얼마나 생산할지 합리적으로 결정하며, 새 제품·일자리·나라 경제 발전으로 이어짐 · 지나친 경쟁은 환경 오염·담합(약속해 가격 올리기)·잘못된 정보·사업 방해를 낳으므로 정부가 바로잡고, 기업은 사회에 큰 영향을 미치므로 환경·사회·투명 경영 같은 사회적 책임을 다해야 함',ARRAY['[6사11-01] 시장경제에서 가계와 기업의 역할을 이해하고, 근로자의 권리와 기업의 자유 및 사회적 책임을 탐색한다.']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C5','soc',6,2,'u2',5,'경제성장의 뜻과 우리나라의 경제성장 과정 — 경제성장은 국가 전체의 생산 수준이나 국민 소득이 늘어 경제 규모가 커지는 것(1인당 국민 총소득 = 국민이 일정 기간 생산 활동으로 받은 소득의 합 ÷ 인구수) · 일제의 식민 통치와 6·25 전쟁으로 폐허가 된 뒤 가계·기업·정부가 함께 노력해 1960년대 경공업 제품 수출 → 1970년대 중화학 공업 발달 → 1988년 서울 올림픽 대회 → 반도체·자동차 등 첨단 산업과 문화 콘텐츠로 빠르게 성장(한강의 기적)',ARRAY['[6사11-02] 경제성장이 우리 생활에 미치는 영향을 파악하고, 빠른 경제성장으로 발생한 문제의 해결 방안을 탐색한다.']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C6','soc',6,2,'u2',5,'경제성장이 우리 생활에 미친 영향 — 첨단 기술 발전으로 생산 속도·생산량이 늘고 생활이 편리해짐, 새 일자리와 소득 증가로 생활이 풍족해져 문화 산업(콘텐츠 산업)이 발달하고 다시 경제를 키움, 교육의 질이 높아지고 수준 높은 의료 혜택으로 기대 수명이 늘어남 — 삶의 질이 높아짐',ARRAY['[6사11-02] 경제성장이 우리 생활에 미치는 영향을 파악하고, 빠른 경제성장으로 발생한 문제의 해결 방안을 탐색한다.']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C7','soc',6,2,'u2',7,'빠른 경제성장으로 생긴 문제 — 무분별한 개발·오염 물질·쓰레기 증가로 환경 문제, 소득 차이가 커지는 빈부 격차(상대적 빈곤율), 필요보다 많이 쓰는 과소비와 자원 낭비, 임금·복지를 둘러싼 근로자와 기업의 노사 갈등이 생김 — 그대로 두면 갈등·빚·자원 부족으로 경제성장도 어려워짐',ARRAY['[6사11-02] 경제성장이 우리 생활에 미치는 영향을 파악하고, 빠른 경제성장으로 발생한 문제의 해결 방안을 탐색한다.']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C8','soc',6,2,'u2',7,'경제성장 문제의 해결과 함께하는 노력 — 경제가 지속적으로 발전하려면 문제를 해결해야 함 · 해결 방안은 평가 기준(실천할 수 있나·효과가 큰가·비용이 적게 드나 등)을 세워 점수를 매겨 견주고 실천 계획을 세움, 기준이 바뀌면 고르는 방안도 바뀜 · 정부는 제도·정책, 기업과 근로자는 소통, 시민 단체·개인도 노력 · 공유지의 비극(함께 쓰는 자원을 자기 이익만 생각해 쓰면 공동체 전체가 피해)을 막으려면 규칙과 공동의 이익을 생각하는 태도가 함께 필요',ARRAY['[6사11-02] 경제성장이 우리 생활에 미치는 영향을 파악하고, 빠른 경제성장으로 발생한 문제의 해결 방안을 탐색한다.']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C9','soc',6,2,'u2',9,'무역의 뜻과 무역이 이루어지는 까닭 — 무역은 나라와 나라 사이에 물자나 서비스를 사고팔거나 교환하는 일, 사 오면 수입·팔면 수출(같은 거래도 어느 나라에서 보느냐에 따라 수입이자 수출), 고려 벽란도에서도 무역이 있었고 오늘날 드라마·예능 같은 서비스도 수출 · 나라마다 자연환경·자원·자본·기술이 달라 효율적으로 생산하는 것이 다르므로, 잘 만드는 것은 수출하고 구하기 어렵거나 더 좋고 값싼 것은 수입하면 두 나라 모두 이익(흑연 수입 → 배터리 수출)',ARRAY['[6사11-03] 사례를 통해 무역의 의미를 이해하고, 국가 간 무역이 발생하는 이유를 탐구한다.']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C10','soc',6,2,'u2',11,'무역이 이루어지는 다양한 모습 — 우리나라는 원유·천연가스·석탄 같은 천연자원을 주로 수입하고 발달한 기술로 반도체·자동차·석유 제품·무선 통신 기기를 만들어 수출(원유 ≠ 석유 제품) · 넓은 땅과 알맞은 기후의 나라는 농산물(쌀 등), 자원이 풍부한 나라는 자원(원유 등), 기술이 뛰어난 나라는 첨단 제품(백신·로봇)·문화 상품을 수출하고, 싱가포르처럼 항로 길목의 지리적 위치를 활용하기도 함 · 박람회에서 상품을 알리고 거래함',ARRAY['[6사11-03] 사례를 통해 무역의 의미를 이해하고, 국가 간 무역이 발생하는 이유를 탐구한다.']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C11','soc',6,2,'u2',12,'무역을 통한 상호 의존과 경쟁 — 여러 나라는 물자·기술을 주고받으며 서로 의존(여러 나라 부품으로 스마트폰, 광물 탐사 기술 협력)하고 첨단 기술 개발·다른 나라 시설 건설·더 나은 무역 환경(자동화 항만)을 두고 경쟁 · 수출이 늘면 산업 성장·일자리·소득 증가, 수입이 늘면 생활은 편리해지나 국내 기업이 어려워질 수 있어 관세(수입품에 매기는 세금)·수입 제한으로 국내 산업을 보호하기도 함 · 기업은 노동력·시장·관세 조건이 유리한 나라에서 생산하기도 하며, 값싸고 다양한 제품·일자리를 주지만 정당한 임금·환경 문제도 살펴야 함',ARRAY['[6사11-03] 사례를 통해 무역의 의미를 이해하고, 국가 간 무역이 발생하는 이유를 탐구한다.']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C12','soc',6,2,'u2',12,'기업 운영 계획 세우기 — 기업의 대표가 되어 대표 상품(물건이나 서비스)과 특징을 정하고, 상품이 필요할 만한 나라를 조사해 주요 수출국을 고르며, 사회적 책임을 다하는 목표와 근로자의 권리를 보호하는 노력(대화의 시간·성과급·휴가 보장)을 담아 기업 소개 잡지로 나타냄',ARRAY['[6사11-03] 사례를 통해 무역의 의미를 이해하고, 국가 간 무역이 발생하는 이유를 탐구한다.']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X01','soc',6,'u2',ARRAY['SO6-2-u2-C1']::text[],'시장은 물건을 사고파는 건물이 있는 곳만이라고 여겨 온라인 쇼핑·중고 거래 같은 곳은 시장이 아니라고 여긴다','거래가 이루어지면 장소와 상관없이 시장') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X02','soc',6,'u2',ARRAY['SO6-2-u2-C1']::text[],'가격이 한쪽(사려는 양이나 내놓은 양 하나, 또는 한 기업의 뜻)만으로 정해진다고 여긴다','사려는 양과 내놓은 양을 함께 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X03','soc',6,'u2',ARRAY['SO6-2-u2-C1','SO6-2-u2-C2']::text[],'가계와 기업이 하는 일·얻는 것을 바꾸어 안다(가계가 이윤을, 기업이 소득을 얻는다 등)','가계 → 소득·소비 · 기업 → 생산·이윤') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X04','soc',6,'u2',ARRAY['SO6-2-u2-C2']::text[],'가계와 기업이 서로 상관없이 따로 경제활동을 하거나, 한쪽이 역할을 못해도 다른 쪽은 괜찮다고 여긴다','고리 하나가 끊기면 흐름 전체가 멈춰요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X05','soc',6,'u2',ARRAY['SO6-2-u2-C2']::text[],'합리적 선택을 가장 비싼(또는 가장 싼) 것 고르기나 남 따라 하기로 여기고, 기준을 정해 비교하지 않는다','우리 가족의 기준 몇 가지로 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X06','soc',6,'u2',ARRAY['SO6-2-u2-C3']::text[],'근로자의 권리는 기업이 알아서 지켜 주므로 법과 제도가 필요 없다거나, 근로자는 기업과 협의하거나 단체로 행동할 수 없다고 여긴다','혼자 낸 목소리 vs 법이 보장한 권리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X07','soc',6,'u2',ARRAY['SO6-2-u2-C3','SO6-2-u2-C4','SO6-2-u2-C11']::text[],'근로자와 기업, 기업과 사회, 나라와 나라처럼 서로 의존하는 관계를 한쪽만의 일로 여긴다','한쪽이 어려우면 다른 쪽은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X08','soc',6,'u2',ARRAY['SO6-2-u2-C4']::text[],'기업의 자유를 무엇이든 해도 되는 것(담합·거짓 광고·사업 방해·환경 오염도 자유)으로 여겨 사회적 책임을 놓친다','돛(자유)과 키(책임)를 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X09','soc',6,'u2',ARRAY['SO6-2-u2-C4']::text[],'기업의 사회적 책임 활동의 갈래(환경·사회·투명 경영)나 정부의 바로잡기 노력을 헷갈린다','환경 — 에너지·폐기물 · 사회 — 인권·지역 · 투명 경영 — 공정·윤리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X10','soc',6,'u2',ARRAY['SO6-2-u2-C5']::text[],'경제성장을 인구가 늘어나는 것이나 한 기업의 이윤이 느는 것으로 여기거나, 1인당 국민 총소득의 뜻을 헷갈린다','나라 전체의 생산·소득 → 경제 규모') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X11','soc',6,'u2',ARRAY['SO6-2-u2-C5']::text[],'우리나라 경제성장 과정의 차례(경공업 → 중화학 공업 → 서울 올림픽 → 첨단·문화 산업)나 출발 조건(폐허·자원 부족)을 헷갈린다','가벼운 물건 → 무거운 공업 → 첨단') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X12','soc',6,'u2',ARRAY['SO6-2-u2-C5','SO6-2-u2-C6','SO6-2-u2-C7']::text[],'경제성장의 한쪽 영향만 보거나(좋은 점만·문제만), 성장이 누군가 혼자의 노력으로 저절로 이루어졌다고 여긴다','좋아진 모습과 경고등을 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X13','soc',6,'u2',ARRAY['SO6-2-u2-C6']::text[],'경제성장이 생활에 준 영향의 갈래(첨단 기술·문화 산업·교육·의료)를 바꾸어 짝짓는다','기대 수명 → 의료 · 콘텐츠 → 문화 산업') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X14','soc',6,'u2',ARRAY['SO6-2-u2-C7']::text[],'빠른 경제성장으로 생긴 문제의 갈래(환경·빈부 격차·과소비와 자원 낭비·노사 갈등)를 헷갈린다','무엇이 지나쳤나? 개발·소득 차이·씀씀이·임금') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X15','soc',6,'u2',ARRAY['SO6-2-u2-C8']::text[],'해결 방안을 평가 기준 없이 느낌·먼저 낸 순서로 고르거나, 문제 해결을 한 주체(정부만·개인만)의 일로 여긴다','기준 → 점수 → 견주기 · 정부·기업·근로자·시민') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X16','soc',6,'u2',ARRAY['SO6-2-u2-C8']::text[],'공유지의 비극을 모두가 아껴 써서 생기는 일로 알거나, 규칙만 있으면 태도는 필요 없다고 여긴다','함께 쓰는 자원을 나만 생각하며 쓰면?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X17','soc',6,'u2',ARRAY['SO6-2-u2-C9']::text[],'수입과 수출을 바꾸어 알거나, 같은 거래도 어느 나라에서 보느냐에 따라 수입·수출이 갈린다는 점을 놓친다','사 오면 수입 · 팔면 수출 — 누구 쪽에서?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X18','soc',6,'u2',ARRAY['SO6-2-u2-C9','SO6-2-u2-C10']::text[],'무역은 물건이 모자랄 때만 하거나 손에 잡히는 물건만 사고판다고 여겨, 나라마다 조건이 달라 잘 만드는 것을 바꾸어 서로 이익을 얻는 까닭을 놓친다','자연환경·자원·자본·기술의 차이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X19','soc',6,'u2',ARRAY['SO6-2-u2-C10']::text[],'나라의 조건과 무역의 모습을 맞지 않게 짝짓는다(우리나라가 원유를 수출한다, 원유와 석유 제품을 같은 것으로 안다 등)','우리나라 — 자원 수입 → 기술로 제품 수출') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X20','soc',6,'u2',ARRAY['SO6-2-u2-C11']::text[],'무역에서의 상호 의존과 경쟁을 헷갈리거나, 관세·수입 제한·해외 생산의 한쪽 영향만 본다','함께 만들기 = 의존 · 먼저 차지하기 = 경쟁') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X21','soc',6,'u2',ARRAY['SO6-2-u2-C12']::text[],'기업 운영 계획에서 이윤만 생각하고 수출국 조사·사회적 책임·근로자를 위한 노력을 빠뜨린다','상품 · 수출국 · 목표 · 노력 넷 다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X22','soc',6,'u2',ARRAY['SO6-2-u2-C9']::text[],'모든 상품을 더 잘 만드는 나라나 나라 안에서 구할 수 있는 물자는 무역(수입)할 필요가 없다고 여긴다(각 나라가 더 큰 이익을 얻는 상품에 집중하는 까닭, 더 좋고 값싼 물자를 수입하는 까닭을 놓친다)','㉮ 나라는 쌀과 옷을 모두 더 많이 만들 수 있는데도 옷을 수출해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X23','soc',6,'u2',ARRAY['SO6-2-u2-C11']::text[],'수입이 늘면 국내 산업의 피해가 줄어든다고 여기거나, 관세를 수출품에 매기는 세금으로 안다','관세 = 다른 나라에서 수입하는 상품에 매기는 세금') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X24','soc',6,'u2',ARRAY['SO6-2-u2-C5']::text[],'경제성장은 빠를수록 좋고 느리면 나쁘다고 여긴다(나라마다 성장 속도가 다르고, 빠른 성장에는 문제도 따른다)','성장 속도는 나라마다 달라요 — 빠르기보다 무엇이 달라졌는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X25','soc',6,'u2',ARRAY['SO6-2-u2-C4']::text[],'기업의 경쟁과 이윤 추구 자체를 나쁘다고 여겨, 과도한 경쟁으로 생기는 부작용과 구별하지 못한다','경쟁은 좋은 상품을 낳아요 — 문제는 남의 피해를 생각하지 않는 지나친 경쟁') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X26','soc',6,'u2',ARRAY['SO6-2-u2-C7']::text[],'선진국이 되거나 경제가 성장하면 빈부 격차는 저절로 사라진다고 여긴다','세계 10위 경제 대국이 되었어도 상대적 빈곤율은 높은 편이에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L01_basic#1','soc',6,2,'u2','L01','tb_g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',1,'mc','auto','61쪽 첫 문단에서 물건이나 서비스의 거래가 이루어지는 곳을 가리키는 낱말은 무엇인가요?',ARRAY['SO6-2-u2-X03','SO6-2-u2-X01']::text[],true,'{"seq":1,"concept":"SO6-2-u2-C1","difficulty":1,"kind":"mc","stem":"61쪽 첫 문단에서 물건이나 서비스의 거래가 이루어지는 곳을 가리키는 낱말은 무엇인가요?","options":[{"t":"시장","correct":true},{"t":"가계","mis":"SO6-2-u2-X03"},{"t":"기업","mis":"SO6-2-u2-X03"},{"t":"서비스","mis":"SO6-2-u2-X01"}],"explanation":["거래가 이루어지는 곳이에요.","물건도 서비스도 사고팔아요.","시장이에요."],"variant_rule":{"alt":[{"stem":"시장에서 경제활동을 함께하며 살림을 꾸려 가는 생활 공동체를 무엇이라고 하나요?","options":[{"t":"가계","correct":true},{"t":"기업","mis":"SO6-2-u2-X03"},{"t":"시장","mis":"SO6-2-u2-X01"},{"t":"이윤","mis":"SO6-2-u2-X03"}],"explanation":["살림을 꾸려 가요.","함께 사는 생활 공동체예요.","가계예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L01_basic#2','soc',6,2,'u2','L01','tb_g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',1,'ox','auto','중고 물품을 사고파는 온라인 쇼핑몰도 시장이에요.',ARRAY['SO6-2-u2-X01']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C1","difficulty":1,"kind":"ox","stem":"중고 물품을 사고파는 온라인 쇼핑몰도 시장이에요.","answer":"O","reason_options":[{"t":"장소와 상관없이 거래가 이루어지는 곳은 모두 시장이기 때문에","correct":true},{"t":"시장은 물건을 늘어놓은 건물이 있어야만 하기 때문에","mis":"SO6-2-u2-X01"}],"mis":"SO6-2-u2-X01","explanation":["온라인에서도 거래가 이루어져요.","장소와 상관없어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L01_basic#3','soc',6,2,'u2','L01','tb_g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',1,'sa','auto','시장에서 이윤을 목적으로 물건이나 서비스를 생산하거나 판매하는 조직을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u2-C1","difficulty":1,"kind":"sa","stem":"시장에서 이윤을 목적으로 물건이나 서비스를 생산하거나 판매하는 조직을 두 글자로 쓰세요.","answer":["기업"],"explanation":["이윤을 목적으로 해요.","생산하고 판매해요.","기업이에요."],"mis":"SO6-2-u2-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L01_basic#4','soc',6,2,'u2','L01','tb_g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',1,'blank','auto','물건이나 서비스를 판매하여 얻은 수입에서 생산에 들어간 비용을 뺀 금액을 (    )이라고 해요. 빈칸에 알맞은 말은?',ARRAY['SO6-2-u2-X03','SO6-2-u2-X02']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C1","difficulty":1,"kind":"blank","stem":"물건이나 서비스를 판매하여 얻은 수입에서 생산에 들어간 비용을 뺀 금액을 (    )이라고 해요. 빈칸에 알맞은 말은?","options":[{"t":"이윤","correct":true},{"t":"소득","mis":"SO6-2-u2-X03"},{"t":"가격","mis":"SO6-2-u2-X02"},{"t":"서비스","mis":"SO6-2-u2-X03"}],"explanation":["판매 수입에서 비용을 빼요.","기업이 얻으려는 것이에요.","이윤이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L01_basic#5','soc',6,2,'u2','L01','tb_g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',2,'mc','auto','사과 가격이 지난주와 달라진 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u2-X02','SO6-2-u2-X01']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"mc","stem":"사과 가격이 지난주와 달라진 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"사람들이 사려는 사과의 양에 비해 시장에 나온 사과의 양이 달라져서","correct":true},{"t":"가게 주인 한 사람이 기분에 따라 정해서","mis":"SO6-2-u2-X02"},{"t":"사과는 언제나 같은 값이어야 해서","mis":"SO6-2-u2-X02"},{"t":"사과를 파는 건물이 바뀌어서","mis":"SO6-2-u2-X01"}],"explanation":["사려는 양과 나온 양을 함께 봐요.","둘의 차이가 바뀌면 값도 바뀌어요.","사려는 양에 비해 나온 양이 달라져서예요."],"asset":{"type":"speech","turns":[{"who":"아이","text":"사과가 맛있게 생겼네. 사과를 사요, 아버지."},{"who":"아버지","text":"그런데 사과 가격이 내렸네."},{"who":"아이","text":"어? 사과 가격이 지난주와 달라졌어요."},{"who":"아이","text":"사과 가격은 왜 달라지는 거예요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L01_basic#6','soc',6,2,'u2','L01','tb_g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',2,'match','auto','61쪽 시장 사진을 보고, 시장과 그곳에서 경제활동을 한 경험을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"match","stem":"61쪽 시장 사진을 보고, 시장과 그곳에서 경제활동을 한 경험을 알맞게 이으세요.","pairs":[{"l":"문구점","r":"친구와 예쁜 연필을 산 일"},{"l":"전통 시장","r":"부모님과 저녁 반찬거리를 산 일"},{"l":"온라인 쇼핑","r":"누나가 집에 필요한 물건을 주문한 일"}],"mis":"SO6-2-u2-X01","explanation":["연필은 문구점이에요.","반찬거리는 전통 시장이에요.","주문은 온라인 쇼핑이에요."],"asset":{"type":"passage","lines":["사진 ① 전통 시장","사진 ② 대형 할인점","사진 ③ 문구점","사진 ④ 온라인 쇼핑"],"title":"『사회』 61쪽 — 시장의 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L01_basic#7','soc',6,2,'u2','L01','tb_g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',2,'mc','auto','시장경제의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u2-X02','SO6-2-u2-X03','SO6-2-u2-X01']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"mc","stem":"시장경제의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"시장에서 가계와 기업이 자유롭게 경쟁하며 경제활동을 하는 방식","correct":true},{"t":"나라가 모든 물건의 값과 양을 정해 주는 방식","mis":"SO6-2-u2-X02"},{"t":"가계와 기업이 서로 만나지 않고 따로 일하는 방식","mis":"SO6-2-u2-X03"},{"t":"큰 건물 안에서만 물건을 사고파는 방식","mis":"SO6-2-u2-X01"}],"explanation":["가계와 기업이 시장에서 만나요.","자유롭게 경쟁해요.","그것이 시장경제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L01_basic#8','soc',6,2,'u2','L01','tb_g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',2,'mc','auto','62쪽 그림에서 기업과 기업 사이의 경쟁을 나타낸 것은 무엇인가요?',ARRAY['SO6-2-u2-X03']::text[],true,'{"seq":8,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"mc","stem":"62쪽 그림에서 기업과 기업 사이의 경쟁을 나타낸 것은 무엇인가요?","options":[{"t":"다른 기업보다 더 좋은 물건을 만들려고 노력해요","correct":true},{"t":"일자리를 얻으려고 다른 사람들과 경쟁해요","mis":"SO6-2-u2-X03"},{"t":"원하는 물건을 사려고 다른 사람들과 경쟁해요","mis":"SO6-2-u2-X03"}],"explanation":["기업끼리의 경쟁이에요.","더 좋은 물건을 만들려 해요.","그 그림이에요."],"asset":{"type":"passage","lines":["그림 ㉮ 일자리를 얻으려고 다른 사람들과 경쟁합니다.","그림 ㉯ 원하는 물건을 사려고 다른 사람들과 경쟁합니다.","그림 ㉰ 다른 기업보다 더 많은 물건을 팔려고 경쟁합니다.","그림 ㉱ 다른 기업보다 더 좋은 물건을 만들려고 노력합니다."],"title":"『사회』 62쪽 — 시장에서 이루어지는 자유로운 경쟁"},"variant_rule":{"alt":[{"stem":"62쪽 그림에서 사람들이 일자리를 두고 하는 경쟁은 무엇인가요?","options":[{"t":"일자리를 얻으려고 다른 사람들과 경쟁해요","correct":true},{"t":"다른 기업보다 더 많은 물건을 팔려고 경쟁해요","mis":"SO6-2-u2-X03"},{"t":"다른 기업보다 더 좋은 물건을 만들려고 노력해요","mis":"SO6-2-u2-X03"}],"explanation":["사람들의 경쟁이에요.","일자리를 얻으려 해요.","그 그림이에요."],"asset":{"type":"passage","lines":["그림 ㉮ 일자리를 얻으려고 다른 사람들과 경쟁합니다.","그림 ㉯ 원하는 물건을 사려고 다른 사람들과 경쟁합니다.","그림 ㉰ 다른 기업보다 더 많은 물건을 팔려고 경쟁합니다.","그림 ㉱ 다른 기업보다 더 좋은 물건을 만들려고 노력합니다."],"title":"『사회』 62쪽 — 시장에서 이루어지는 자유로운 경쟁"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L01_basic#9','soc',6,2,'u2','L01','tb_g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',2,'sa','auto','꼭 기억해요: 시장에서 가계와 기업이 자유롭게 경쟁하며 경제활동을 하는 방식을 (ㅅㅈㄱㅈ)라고 해요. 낱말을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"sa","stem":"꼭 기억해요: 시장에서 가계와 기업이 자유롭게 경쟁하며 경제활동을 하는 방식을 (ㅅㅈㄱㅈ)라고 해요. 낱말을 쓰세요.","answer":["시장경제","시장 경제"],"explanation":["초성은 ㅅㅈㄱㅈ예요.","자유로운 경쟁이 바탕이에요.","시장경제예요."],"mis":"SO6-2-u2-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L01_basic#10','soc',6,2,'u2','L01','tb_g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',3,'essay','teacher','시장에서 이루어지는 자유로운 경쟁이 우리 생활에 주는 도움을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u2-C1","difficulty":3,"kind":"essay","stem":"시장에서 이루어지는 자유로운 경쟁이 우리 생활에 주는 도움을 두 가지 쓰세요.","answer_guide":{"answer":"예: 기업들이 경쟁해서 품질이 좋은 상품을 알맞은 가격에 살 수 있어요. 일자리를 얻으려고 경쟁하면서 내 능력을 발전시킬 수 있어요.","scoring_points":["경쟁하는 주체를 밝혔는가","생활에 주는 도움을 썼는가","두 가지를 썼는가"]},"explanation":["누가 경쟁하는지 봐요.","나에게 좋은 점을 찾아요.","두 가지를 써요."],"asset":{"type":"passage","lines":["그림 ㉮ 일자리를 얻으려고 다른 사람들과 경쟁합니다.","그림 ㉯ 원하는 물건을 사려고 다른 사람들과 경쟁합니다.","그림 ㉰ 다른 기업보다 더 많은 물건을 팔려고 경쟁합니다.","그림 ㉱ 다른 기업보다 더 좋은 물건을 만들려고 노력합니다."],"title":"『사회』 62쪽 — 시장에서 이루어지는 자유로운 경쟁"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L01_challenge#1','soc',6,2,'u2','L01','tb_g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',2,'error','auto','시장에 대한 설명 가운데 잘못된 것을 고르세요.',ARRAY['SO6-2-u2-X01']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"error","stem":"시장에 대한 설명 가운데 잘못된 것을 고르세요.","options":[{"t":"중고 물품 온라인 쇼핑몰은 건물이 없으니 시장이 아니에요","correct":true,"mis_target":"SO6-2-u2-X01"},{"t":"주식을 사고파는 거래소도 시장이에요","mis":"SO6-2-u2-X01"},{"t":"문구점도 물건을 사고파는 시장이에요","mis":"SO6-2-u2-X01"}],"explanation":["시장은 거래가 이루어지는 곳이에요.","건물이 없어도 시장이에요.","온라인 쇼핑몰이 시장이 아니라는 말이 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L01_challenge#2','soc',6,2,'u2','L01','tb_g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',2,'ox','auto','시장에서 상품의 가격은 사람들이 필요로 하는 양과 기업에서 제공하는 양에 따라 정해져요.',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"ox","stem":"시장에서 상품의 가격은 사람들이 필요로 하는 양과 기업에서 제공하는 양에 따라 정해져요.","answer":"O","reason_options":[{"t":"필요로 하는 양과 제공하는 양을 함께 견주어 가격이 정해지기 때문에","correct":true},{"t":"가격은 기업 한 곳이 원하는 대로만 정하기 때문에","mis":"SO6-2-u2-X02"}],"mis":"SO6-2-u2-X02","explanation":["양쪽을 함께 봐요.","62쪽 내용이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L01_challenge#3','soc',6,2,'u2','L01','tb_g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',3,'mc','auto','사과 가격이 지난주보다 내렸다면 어떤 까닭을 짐작할 수 있나요?',ARRAY['SO6-2-u2-X02','SO6-2-u2-X01']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C1","difficulty":3,"kind":"mc","stem":"사과 가격이 지난주보다 내렸다면 어떤 까닭을 짐작할 수 있나요?","options":[{"t":"사려는 사과의 양에 비해 시장에 나온 사과의 양이 많아졌어요","correct":true},{"t":"사려는 사람은 크게 늘고 나온 사과는 줄었어요","mis":"SO6-2-u2-X02"},{"t":"사과를 파는 시장 건물이 더 커졌어요","mis":"SO6-2-u2-X01"}],"explanation":["나온 양이 사려는 양보다 많아요.","팔려면 값을 낮춰요.","그래서 가격이 내려요."],"asset":{"type":"speech","turns":[{"who":"아이","text":"사과가 맛있게 생겼네. 사과를 사요, 아버지."},{"who":"아버지","text":"그런데 사과 가격이 내렸네."},{"who":"아이","text":"어? 사과 가격이 지난주와 달라졌어요."},{"who":"아이","text":"사과 가격은 왜 달라지는 거예요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L01_challenge#4','soc',6,2,'u2','L01','tb_g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',3,'match','auto','낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"SO6-2-u2-C1","difficulty":3,"kind":"match","stem":"낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"시장","r":"물건이나 서비스의 거래가 이루어지는 곳"},{"l":"가계","r":"경제활동을 함께하며 살림을 꾸려 가는 생활 공동체"},{"l":"기업","r":"이윤을 목적으로 물건이나 서비스를 생산하거나 판매하는 조직"}],"mis":"SO6-2-u2-X03","explanation":["시장은 거래하는 곳이에요.","가계는 살림을 꾸려요.","기업은 이윤을 목적으로 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L01_challenge#5','soc',6,2,'u2','L01','tb_g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',3,'mc','auto','부모님이 회사에서 일하고 받은 돈으로 저녁거리를 사는 우리 가족은 시장경제에서 무엇에 해당하나요?',ARRAY['SO6-2-u2-X03','SO6-2-u2-X01']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C1","difficulty":3,"kind":"mc","stem":"부모님이 회사에서 일하고 받은 돈으로 저녁거리를 사는 우리 가족은 시장경제에서 무엇에 해당하나요?","options":[{"t":"가계","correct":true},{"t":"기업","mis":"SO6-2-u2-X03"},{"t":"시장","mis":"SO6-2-u2-X01"}],"explanation":["살림을 꾸려 가요.","일한 대가로 소득을 얻어 소비해요.","가계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L01_challenge#6','soc',6,2,'u2','L01','tb_g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',3,'mc','auto','경제활동에서 자유와 경쟁이 보장되지 않는다면 어떤 문제가 생길 수 있을까요?',ARRAY['SO6-2-u2-X02','SO6-2-u2-X01']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C1","difficulty":3,"kind":"mc","stem":"경제활동에서 자유와 경쟁이 보장되지 않는다면 어떤 문제가 생길 수 있을까요?","options":[{"t":"좋은 물건을 만들려는 노력이 줄어 품질 좋은 상품을 고르기 어려워져요","correct":true},{"t":"가격이 사람들의 필요와 상관없이 늘 낮게 유지돼요","mis":"SO6-2-u2-X02"},{"t":"시장이 건물 안으로만 모여 장보기가 쉬워져요","mis":"SO6-2-u2-X01"}],"explanation":["경쟁이 없으면 노력도 줄어요.","좋은 상품이 덜 생겨요.","그래서 고르기 어려워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L01_challenge#7','soc',6,2,'u2','L01','tb_g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',3,'blank','auto','전통 시장, 대형 할인점, 문구점, 온라인 쇼핑의 공통점은 (    )이 이루어지는 곳이라는 거예요. 빈칸에 알맞은 말은?',ARRAY['SO6-2-u2-X01','SO6-2-u2-X02','SO6-2-u2-X03']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C1","difficulty":3,"kind":"blank","stem":"전통 시장, 대형 할인점, 문구점, 온라인 쇼핑의 공통점은 (    )이 이루어지는 곳이라는 거예요. 빈칸에 알맞은 말은?","options":[{"t":"물건이나 서비스의 거래","correct":true},{"t":"큰 건물 안의 판매","mis":"SO6-2-u2-X01"},{"t":"나라가 정한 가격의 판매","mis":"SO6-2-u2-X02"},{"t":"기업끼리만 하는 거래","mis":"SO6-2-u2-X03"}],"explanation":["네 곳 모두 사고팔아요.","건물은 상관없어요.","거래가 이루어지는 곳이에요."],"asset":{"type":"passage","lines":["사진 ① 전통 시장","사진 ② 대형 할인점","사진 ③ 문구점","사진 ④ 온라인 쇼핑"],"title":"『사회』 61쪽 — 시장의 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L01_challenge#8','soc',6,2,'u2','L01','tb_g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',4,'essay','teacher','활동지처럼 시장경제의 의미를 쓰고, 시장에서 볼 수 있는 자유로운 경쟁 모습을 두 가지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u2-C1","difficulty":4,"kind":"essay","stem":"활동지처럼 시장경제의 의미를 쓰고, 시장에서 볼 수 있는 자유로운 경쟁 모습을 두 가지 쓰세요.","answer_guide":{"answer":"의미: 시장에서 가계와 기업이 자유롭게 경쟁하며 경제활동을 하는 방식. 경쟁 모습: 원하는 물건을 사려고 다른 사람들과 경쟁해요. 다른 기업보다 더 많은 물건을 팔려고 경쟁해요.","scoring_points":["시장경제의 의미를 바르게 썼는가","경쟁 모습 두 가지를 썼는가","가계와 기업의 경쟁을 고루 살폈는가"]},"explanation":["의미를 먼저 써요.","그림 속 경쟁을 떠올려요.","두 가지를 써요."],"asset":{"type":"passage","lines":["그림 ㉮ 일자리를 얻으려고 다른 사람들과 경쟁합니다.","그림 ㉯ 원하는 물건을 사려고 다른 사람들과 경쟁합니다.","그림 ㉰ 다른 기업보다 더 많은 물건을 팔려고 경쟁합니다.","그림 ㉱ 다른 기업보다 더 좋은 물건을 만들려고 노력합니다."],"title":"『사회』 62쪽 — 시장에서 이루어지는 자유로운 경쟁"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L01_challenge#9','soc',6,2,'u2','L01','tb_g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',4,'essay','teacher','사과 가격이 지난주와 달라진 까닭을 「사람들이 필요로 하는 양」과 「시장에 나온 양」을 넣어 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u2-C1","difficulty":4,"kind":"essay","stem":"사과 가격이 지난주와 달라진 까닭을 「사람들이 필요로 하는 양」과 「시장에 나온 양」을 넣어 설명하세요.","answer_guide":{"answer":"예: 사람들이 필요로 하는 사과의 양에 비해 시장에 나온 사과의 양이 많아지면 가격이 내리고, 적어지면 가격이 올라요.","scoring_points":["필요로 하는 양을 썼는가","시장에 나온 양을 썼는가","두 양의 관계로 가격 변화를 설명했는가"]},"explanation":["두 양을 함께 봐요.","어느 쪽이 많은지 따져요.","가격이 어떻게 되는지 써요."],"asset":{"type":"speech","turns":[{"who":"아이","text":"사과가 맛있게 생겼네. 사과를 사요, 아버지."},{"who":"아버지","text":"그런데 사과 가격이 내렸네."},{"who":"아이","text":"어? 사과 가격이 지난주와 달라졌어요."},{"who":"아이","text":"사과 가격은 왜 달라지는 거예요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L01_challenge#10','soc',6,2,'u2','L01','tb_g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',4,'mc','auto','우리나라가 시장경제를 바탕으로 경제활동을 한다는 것을 가장 잘 보여 주는 모습은 무엇인가요?',ARRAY['SO6-2-u2-X02','SO6-2-u2-X03','SO6-2-u2-X01']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C1","difficulty":4,"kind":"mc","stem":"우리나라가 시장경제를 바탕으로 경제활동을 한다는 것을 가장 잘 보여 주는 모습은 무엇인가요?","options":[{"t":"가계와 기업이 시장에서 만나 자유롭게 경쟁하며 거래해요","correct":true},{"t":"모든 가게가 나라에서 정해 준 값으로만 팔아요","mis":"SO6-2-u2-X02"},{"t":"가계와 기업은 서로 거래하지 않아요","mis":"SO6-2-u2-X03"},{"t":"물건은 건물이 있는 시장에서만 살 수 있어요","mis":"SO6-2-u2-X01"}],"explanation":["시장에서 만나요.","자유롭게 경쟁해요.","그 모습이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L02_basic#1','soc',6,2,'u2','L02','tb_g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',1,'mc','auto','63쪽 가족의 일과에서 가계가 기업의 생산 활동에 참여하는 때는 언제인가요?',ARRAY['SO6-2-u2-X04','SO6-2-u2-X05']::text[],true,'{"seq":1,"concept":"SO6-2-u2-C2","difficulty":1,"kind":"mc","stem":"63쪽 가족의 일과에서 가계가 기업의 생산 활동에 참여하는 때는 언제인가요?","options":[{"t":"오전 10시","correct":true},{"t":"오후 7시","mis":"SO6-2-u2-X04"},{"t":"오후 10시","mis":"SO6-2-u2-X05"},{"t":"오후 5시","mis":"SO6-2-u2-X05"}],"explanation":["일터에서 일하는 때예요.","생산 활동에 참여해요.","오전 10시예요."],"asset":{"type":"passage","lines":["오전 10시 — 부모님이 각자 일터에서 일해요.","오후 5시 — 자동차 판매점에서 가족에게 필요한 차를 살펴봐요.","오후 7시 — 가족이 모여 함께 저녁을 먹어요.","오후 10시 — 부모님이 저축에 관해 의논해요.","(말풍선) 은행에 저축을 해서 이자를 받아 소득을 얻을 수도 있어요."],"numbered":false,"title":"『사회』 63쪽 — 어느 가족의 일과"},"variant_rule":{"alt":[{"stem":"63쪽 가족의 일과에서 부모님이 저축에 관해 의논하는 때는 언제인가요?","options":[{"t":"오후 10시","correct":true},{"t":"오전 10시","mis":"SO6-2-u2-X04"},{"t":"오후 5시","mis":"SO6-2-u2-X05"},{"t":"오후 7시","mis":"SO6-2-u2-X04"}],"explanation":["저축을 의논해요.","마지막 일과예요.","오후 10시예요."],"asset":{"type":"passage","lines":["오전 10시 — 부모님이 각자 일터에서 일해요.","오후 5시 — 자동차 판매점에서 가족에게 필요한 차를 살펴봐요.","오후 7시 — 가족이 모여 함께 저녁을 먹어요.","오후 10시 — 부모님이 저축에 관해 의논해요.","(말풍선) 은행에 저축을 해서 이자를 받아 소득을 얻을 수도 있어요."],"numbered":false,"title":"『사회』 63쪽 — 어느 가족의 일과"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L02_basic#2','soc',6,2,'u2','L02','tb_g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',1,'blank','auto','꼭 기억해요: 가계는 기업의 생산 활동에 참여하고 그에 대한 대가로 (    )을 얻어요. 빈칸에 알맞은 말은?',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C2","difficulty":1,"kind":"blank","stem":"꼭 기억해요: 가계는 기업의 생산 활동에 참여하고 그에 대한 대가로 (    )을 얻어요. 빈칸에 알맞은 말은?","options":[{"t":"소득","correct":true},{"t":"비용","mis":"SO6-2-u2-X03"},{"t":"이윤","mis":"SO6-2-u2-X03"},{"t":"세금","mis":"SO6-2-u2-X03"}],"explanation":["일한 대가예요.","가계가 얻어요.","소득이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L02_basic#3','soc',6,2,'u2','L02','tb_g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',1,'sa','auto','꼭 기억해요: (ㄱㅇ)은 사람들의 생활에 필요한 물건이나 서비스를 생산하고 판매하여 그 대가로 이윤을 얻어요. 낱말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u2-C2","difficulty":1,"kind":"sa","stem":"꼭 기억해요: (ㄱㅇ)은 사람들의 생활에 필요한 물건이나 서비스를 생산하고 판매하여 그 대가로 이윤을 얻어요. 낱말을 쓰세요.","answer":["기업"],"explanation":["초성은 ㄱㅇ이에요.","이윤을 얻어요.","기업이에요."],"mis":"SO6-2-u2-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L02_basic#4','soc',6,2,'u2','L02','tb_g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',1,'ox','auto','은행에 저축을 해서 이자를 받는 것도 가계가 소득을 얻는 방법이에요.',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C2","difficulty":1,"kind":"ox","stem":"은행에 저축을 해서 이자를 받는 것도 가계가 소득을 얻는 방법이에요.","answer":"O","reason_options":[{"t":"63쪽 말풍선처럼 저축 이자로도 소득을 얻을 수 있기 때문에","correct":true},{"t":"소득은 회사에서 받는 월급만 뜻하기 때문에","mis":"SO6-2-u2-X03"}],"mis":"SO6-2-u2-X03","explanation":["63쪽 말풍선이에요.","이자도 소득이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L02_basic#5','soc',6,2,'u2','L02','tb_g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',2,'mc','auto','64쪽 자동차 가운데 휘발유 1 L로 가장 멀리 갈 수 있는 차는 무엇인가요?',ARRAY['SO6-2-u2-X05']::text[],true,'{"seq":5,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"mc","stem":"64쪽 자동차 가운데 휘발유 1 L로 가장 멀리 갈 수 있는 차는 무엇인가요?","options":[{"t":"자동차 ①","correct":true},{"t":"자동차 ②","mis":"SO6-2-u2-X05"},{"t":"자동차 ③","mis":"SO6-2-u2-X05"}],"explanation":["1 L로 가는 거리를 봐요.","15 km가 가장 멀어요.","자동차 ①이에요."],"asset":{"type":"passage","lines":["모아 둔 돈 — 5천만 원","자동차 ① — 7인승 · 3천만 원 · 품질 보증 5년 · 1 L로 15 km","①의 그 밖의 특징 — 시야가 높아 운전하기 편함 · 스마트폰으로 제어","자동차 ② — 5인승 · 2천만 원 · 품질 보증 3년 · 1 L로 10 km","②의 그 밖의 특징 — 인공지능 시스템 · 중고차이나 승차감이 편안함","자동차 ③ — 9인승 · 4천만 원 · 품질 보증 5년 · 1 L로 9 km","③의 그 밖의 특징 — 인공지능 시스템 · 실내 공기 청정기"],"numbered":false,"title":"『사회』 64쪽 할 수 있어요 — 우리 가족이 살 자동차"},"variant_rule":{"alt":[{"stem":"64쪽 자동차 가운데 가족 아홉 명이 함께 탈 수 있는 차는 무엇인가요?","options":[{"t":"자동차 ③","correct":true},{"t":"자동차 ①","mis":"SO6-2-u2-X05"},{"t":"자동차 ②","mis":"SO6-2-u2-X05"}],"explanation":["몇 인승인지 봐요.","9인승이에요.","자동차 ③이에요."],"asset":{"type":"passage","lines":["모아 둔 돈 — 5천만 원","자동차 ① — 7인승 · 3천만 원 · 품질 보증 5년 · 1 L로 15 km","①의 그 밖의 특징 — 시야가 높아 운전하기 편함 · 스마트폰으로 제어","자동차 ② — 5인승 · 2천만 원 · 품질 보증 3년 · 1 L로 10 km","②의 그 밖의 특징 — 인공지능 시스템 · 중고차이나 승차감이 편안함","자동차 ③ — 9인승 · 4천만 원 · 품질 보증 5년 · 1 L로 9 km","③의 그 밖의 특징 — 인공지능 시스템 · 실내 공기 청정기"],"numbered":false,"title":"『사회』 64쪽 할 수 있어요 — 우리 가족이 살 자동차"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L02_basic#6','soc',6,2,'u2','L02','tb_g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',2,'mc','auto','가격과 연비를 기준으로 삼는다면 자동차 ①과 자동차 ③ 가운데 어느 차가 더 알맞나요?',ARRAY['SO6-2-u2-X05']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"mc","stem":"가격과 연비를 기준으로 삼는다면 자동차 ①과 자동차 ③ 가운데 어느 차가 더 알맞나요?","options":[{"t":"자동차 ①","correct":true},{"t":"자동차 ③","mis":"SO6-2-u2-X05"},{"t":"두 차가 똑같아요","mis":"SO6-2-u2-X05"}],"explanation":["①이 더 싸요.","①이 연비도 좋아요.","자동차 ①이에요."],"asset":{"type":"passage","lines":["모아 둔 돈 — 5천만 원","자동차 ① — 7인승 · 3천만 원 · 품질 보증 5년 · 1 L로 15 km","①의 그 밖의 특징 — 시야가 높아 운전하기 편함 · 스마트폰으로 제어","자동차 ② — 5인승 · 2천만 원 · 품질 보증 3년 · 1 L로 10 km","②의 그 밖의 특징 — 인공지능 시스템 · 중고차이나 승차감이 편안함","자동차 ③ — 9인승 · 4천만 원 · 품질 보증 5년 · 1 L로 9 km","③의 그 밖의 특징 — 인공지능 시스템 · 실내 공기 청정기"],"numbered":false,"title":"『사회』 64쪽 할 수 있어요 — 우리 가족이 살 자동차"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L02_basic#7','soc',6,2,'u2','L02','tb_g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',2,'match','auto','65쪽 기업이 하는 일과 그 설명을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"match","stem":"65쪽 기업이 하는 일과 그 설명을 알맞게 이으세요.","pairs":[{"l":"근로자를 고용해요","r":"상품을 생산하려고 일할 사람을 뽑아요"},{"l":"급여를 지급해요","r":"일한 대가로 근로자에게 돈을 줘요"},{"l":"연구해요","r":"품질 검사와 소비자 분석으로 더 좋은 물건을 만들려 해요"},{"l":"세금을 내요","r":"판매로 얻은 수익에 대하여 나라에 돈을 내요"}],"mis":"SO6-2-u2-X03","explanation":["고용은 사람을 뽑는 일이에요.","급여는 일한 대가예요.","세금은 나라에 내요."],"asset":{"type":"passage","lines":["① 기업은 물건을 생산해 판매하거나 서비스를 제공합니다.","② 기업은 상품을 생산하려고 근로자를 고용합니다.","③ 기업은 근로자에게 급여를 지급합니다.","④ 기업은 더 좋은 물건이나 서비스를 생산하려고 연구합니다.","⑤ 기업은 판매로 얻은 수익에 대하여 나라에 세금을 냅니다."],"numbered":false,"title":"『사회』 65쪽 — 기업이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L02_basic#8','soc',6,2,'u2','L02','tb_g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',2,'mc','auto','66쪽 신문 기사에서 기업이 지속적인 성장을 위해 한 노력은 무엇인가요?',ARRAY['SO6-2-u2-X02','SO6-2-u2-X06']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"mc","stem":"66쪽 신문 기사에서 기업이 지속적인 성장을 위해 한 노력은 무엇인가요?","options":[{"t":"생산 시설을 늘리고 오래된 시설을 교체했어요","correct":true},{"t":"상품 가격을 올리고 생산량을 줄였어요","mis":"SO6-2-u2-X02"},{"t":"근로자에게 급여를 주지 않았어요","mis":"SO6-2-u2-X06"}],"explanation":["시설에 투자했어요.","품질과 생산량이 높아졌어요.","생산 시설을 늘리고 바꿨어요."],"asset":{"type":"passage","lines":["(간추림) ○○ 기업은 올해 생산 시설을 늘리고 오래된 시설을 교체했다.","그 결과 상품의 품질과 생산량을 높였다.","보다 저렴한 가격에 우수한 품질의 상품을 고객에게 안정적으로 공급하게 됐다.","회사는 기업이 지속해서 성장하고 발전해야 한다고 강조했다."],"numbered":false,"title":"『사회』 66쪽 신문 기사 「지속적인 성장을 위한 기업의 노력」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L02_basic#9','soc',6,2,'u2','L02','tb_g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',2,'blank','auto','67쪽 고리에서 ㉠(가계 → 기업)에 들어갈 붙임딱지는 무엇인가요?',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"blank","stem":"67쪽 고리에서 ㉠(가계 → 기업)에 들어갈 붙임딱지는 무엇인가요?","options":[{"t":"노동력","correct":true},{"t":"이윤","mis":"SO6-2-u2-X03"},{"t":"물건이나 서비스","mis":"SO6-2-u2-X03"},{"t":"세금","mis":"SO6-2-u2-X03"}],"explanation":["가계가 기업에 주는 것이에요.","일하는 힘이에요.","노동력이에요."],"asset":{"type":"passage","lines":["가계 → 기업 : (  ㉠  )","기업 → 가계 : 소득","기업 → 시장 : 물건이나 서비스","시장 → 기업 : (  ㉡  )","시장 → 가계 : 물건이나 서비스"],"title":"『사회』 67쪽 — 가계, 기업, 시장의 관계(붙임딱지 두 칸 비움)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L02_basic#10','soc',6,2,'u2','L02','tb_g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',3,'essay','teacher','가계가 역할을 제대로 하지 못한다면 기업과 시장에 어떤 일이 생길지 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u2-C2","difficulty":3,"kind":"essay","stem":"가계가 역할을 제대로 하지 못한다면 기업과 시장에 어떤 일이 생길지 두 가지 쓰세요.","answer_guide":{"answer":"예: 기업이 노동력을 얻지 못해 물건을 생산하기 어려워져요. 물건을 사 줄 사람이 줄어 기업이 이윤을 얻지 못하고 성장하기 어려워져요.","scoring_points":["노동력과 관련된 일을 썼는가","소비·이윤과 관련된 일을 썼는가","원인과 결과를 이어 썼는가"]},"explanation":["가계가 하는 두 역할을 떠올려요.","그 역할이 끊기면?","두 가지를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L02_challenge#1','soc',6,2,'u2','L02','tb_g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',2,'error','auto','가계와 기업의 역할에 대한 설명 가운데 잘못된 것을 고르세요.',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"error","stem":"가계와 기업의 역할에 대한 설명 가운데 잘못된 것을 고르세요.","options":[{"t":"가계는 근로자에게 급여를 지급해요","correct":true,"mis_target":"SO6-2-u2-X03"},{"t":"기업은 가계에 일자리를 제공해요","mis":"SO6-2-u2-X03"},{"t":"가계는 소득으로 기업이 만든 물건이나 서비스를 소비해요","mis":"SO6-2-u2-X03"}],"explanation":["급여를 주는 쪽을 봐요.","급여는 기업이 줘요.","가계가 급여를 지급한다는 말이 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L02_challenge#2','soc',6,2,'u2','L02','tb_g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',2,'sa','auto','온라인에서 기업에 관한 사람들의 평가와 만족감을 살피고, 누군가 일부러 만든 좋지 않은 평판이 퍼지기 전에 대응하는 직업은 무엇인가요?','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"sa","stem":"온라인에서 기업에 관한 사람들의 평가와 만족감을 살피고, 누군가 일부러 만든 좋지 않은 평판이 퍼지기 전에 대응하는 직업은 무엇인가요?","answer":["사이버 평판 관리자"],"explanation":["68쪽 별별 직업이에요.","온라인 평판을 관리해요.","사이버 평판 관리자예요."],"mis":"SO6-2-u2-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L02_challenge#3','soc',6,2,'u2','L02','tb_g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',3,'mc','auto','가족 아홉 명이 타야 하고 실내 공기를 중요하게 여기는 가족이라면 어느 자동차를 고를까요?',ARRAY['SO6-2-u2-X05']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C2","difficulty":3,"kind":"mc","stem":"가족 아홉 명이 타야 하고 실내 공기를 중요하게 여기는 가족이라면 어느 자동차를 고를까요?","options":[{"t":"자동차 ③","correct":true},{"t":"자동차 ①","mis":"SO6-2-u2-X05"},{"t":"자동차 ②","mis":"SO6-2-u2-X05"}],"explanation":["9인승이 필요해요.","실내 공기 청정기가 있어요.","자동차 ③이에요."],"asset":{"type":"passage","lines":["모아 둔 돈 — 5천만 원","자동차 ① — 7인승 · 3천만 원 · 품질 보증 5년 · 1 L로 15 km","①의 그 밖의 특징 — 시야가 높아 운전하기 편함 · 스마트폰으로 제어","자동차 ② — 5인승 · 2천만 원 · 품질 보증 3년 · 1 L로 10 km","②의 그 밖의 특징 — 인공지능 시스템 · 중고차이나 승차감이 편안함","자동차 ③ — 9인승 · 4천만 원 · 품질 보증 5년 · 1 L로 9 km","③의 그 밖의 특징 — 인공지능 시스템 · 실내 공기 청정기"],"numbered":false,"title":"『사회』 64쪽 할 수 있어요 — 우리 가족이 살 자동차"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L02_challenge#4','soc',6,2,'u2','L02','tb_g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',3,'sa','auto','위 가족이 자동차 ③을 산다면 모아 둔 돈 5천만 원에서 얼마가 남나요?','{}'::text[],false,'{"seq":4,"concept":"SO6-2-u2-C2","difficulty":3,"kind":"sa","stem":"위 가족이 자동차 ③을 산다면 모아 둔 돈 5천만 원에서 얼마가 남나요?","answer":["1천만 원","천만 원","1000만 원"],"explanation":["5천만 원에서 빼요.","자동차 ③은 4천만 원이에요.","1천만 원이 남아요."],"asset":{"type":"passage","lines":["모아 둔 돈 — 5천만 원","자동차 ① — 7인승 · 3천만 원 · 품질 보증 5년 · 1 L로 15 km","①의 그 밖의 특징 — 시야가 높아 운전하기 편함 · 스마트폰으로 제어","자동차 ② — 5인승 · 2천만 원 · 품질 보증 3년 · 1 L로 10 km","②의 그 밖의 특징 — 인공지능 시스템 · 중고차이나 승차감이 편안함","자동차 ③ — 9인승 · 4천만 원 · 품질 보증 5년 · 1 L로 9 km","③의 그 밖의 특징 — 인공지능 시스템 · 실내 공기 청정기"],"numbered":false,"title":"『사회』 64쪽 할 수 있어요 — 우리 가족이 살 자동차"},"mis":"SO6-2-u2-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L02_challenge#5','soc',6,2,'u2','L02','tb_g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',3,'ox','auto','합리적 선택은 언제나 가장 값싼 자동차를 고르는 것이에요.',ARRAY['SO6-2-u2-X05']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C2","difficulty":3,"kind":"ox","stem":"합리적 선택은 언제나 가장 값싼 자동차를 고르는 것이에요.","answer":"X","reason_options":[{"t":"가족마다 중요하게 여기는 기준이 달라, 기준에 따라 비교해서 고르기 때문에","correct":true},{"t":"돈을 적게 쓰는 것만이 만족을 크게 하기 때문에","mis":"SO6-2-u2-X05"}],"mis":"SO6-2-u2-X05","explanation":["기준은 가족마다 달라요.","기준으로 견주어 골라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L02_challenge#6','soc',6,2,'u2','L02','tb_g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',3,'mc','auto','67쪽 고리에서 ㉡(시장 → 기업)에 들어갈 것은 무엇인가요?',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C2","difficulty":3,"kind":"mc","stem":"67쪽 고리에서 ㉡(시장 → 기업)에 들어갈 것은 무엇인가요?","options":[{"t":"이윤","correct":true},{"t":"소득","mis":"SO6-2-u2-X03"},{"t":"노동력","mis":"SO6-2-u2-X03"},{"t":"물건이나 서비스","mis":"SO6-2-u2-X03"}],"explanation":["기업이 시장에서 얻어요.","판매 수입에서 비용을 뺀 것이에요.","이윤이에요."],"asset":{"type":"passage","lines":["가계 → 기업 : (  ㉠  )","기업 → 가계 : 소득","기업 → 시장 : 물건이나 서비스","시장 → 기업 : (  ㉡  )","시장 → 가계 : 물건이나 서비스"],"title":"『사회』 67쪽 — 가계, 기업, 시장의 관계(붙임딱지 두 칸 비움)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L02_challenge#7','soc',6,2,'u2','L02','tb_g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',3,'mc','auto','기업이 역할을 제대로 하지 못한다면 가계에는 어떤 일이 생길까요?',ARRAY['SO6-2-u2-X04','SO6-2-u2-X07']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C2","difficulty":3,"kind":"mc","stem":"기업이 역할을 제대로 하지 못한다면 가계에는 어떤 일이 생길까요?","options":[{"t":"가계가 소득을 얻지 못해 필요한 물건이나 서비스를 사기 어려워져요","correct":true},{"t":"가계는 아무 영향도 받지 않아요","mis":"SO6-2-u2-X04"},{"t":"가계의 소득이 오히려 늘어나요","mis":"SO6-2-u2-X07"}],"explanation":["기업이 일자리를 주지 못해요.","소득이 줄어요.","물건을 사기 어려워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L02_challenge#8','soc',6,2,'u2','L02','tb_g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',4,'essay','teacher','가계와 기업의 관계를 「노동력」, 「소득」이라는 말을 넣어 정리해 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u2-C2","difficulty":4,"kind":"essay","stem":"가계와 기업의 관계를 「노동력」, 「소득」이라는 말을 넣어 정리해 쓰세요.","answer_guide":{"answer":"예: 가계는 기업에 노동력을 제공하고 기업에서 소득을 얻어 생활에 필요한 물건이나 서비스를 사요. 기업은 가계의 노동력으로 물건이나 서비스를 생산하고 가계에 소득을 제공해요.","scoring_points":["노동력의 흐름을 썼는가","소득의 흐름을 썼는가","서로 도움을 주고받는 관계임을 밝혔는가"]},"explanation":["누가 무엇을 주나요?","받는 쪽도 써요.","주고받는 관계로 정리해요."],"asset":{"type":"passage","lines":["가계 → 기업 : (  ㉠  )","기업 → 가계 : 소득","기업 → 시장 : 물건이나 서비스","시장 → 기업 : (  ㉡  )","시장 → 가계 : 물건이나 서비스"],"title":"『사회』 67쪽 — 가계, 기업, 시장의 관계(붙임딱지 두 칸 비움)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L02_challenge#9','soc',6,2,'u2','L02','tb_g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',4,'essay','teacher','64쪽 자동차 표에서 우리 가족이 중요하게 여기는 기준 세 가지를 정하고, 고른 자동차와 그 까닭, 남은 돈으로 하고 싶은 일을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u2-C2","difficulty":4,"kind":"essay","stem":"64쪽 자동차 표에서 우리 가족이 중요하게 여기는 기준 세 가지를 정하고, 고른 자동차와 그 까닭, 남은 돈으로 하고 싶은 일을 쓰세요.","answer_guide":{"answer":"예: 기준은 가격, 연비, 크기예요. 자동차 ①을 골랐어요. 7인승이라 넉넉하고 연비가 가장 좋으며 가격도 적당하기 때문이에요. 남은 2천만 원은 저축해요.","scoring_points":["기준 세 가지를 정했는가","기준에 맞는 까닭을 표의 사실로 들었는가","남은 돈을 바르게 셈해 계획했는가"]},"explanation":["기준을 먼저 정해요.","표에서 근거를 찾아요.","남은 돈도 셈해요."],"asset":{"type":"passage","lines":["모아 둔 돈 — 5천만 원","자동차 ① — 7인승 · 3천만 원 · 품질 보증 5년 · 1 L로 15 km","①의 그 밖의 특징 — 시야가 높아 운전하기 편함 · 스마트폰으로 제어","자동차 ② — 5인승 · 2천만 원 · 품질 보증 3년 · 1 L로 10 km","②의 그 밖의 특징 — 인공지능 시스템 · 중고차이나 승차감이 편안함","자동차 ③ — 9인승 · 4천만 원 · 품질 보증 5년 · 1 L로 9 km","③의 그 밖의 특징 — 인공지능 시스템 · 실내 공기 청정기"],"numbered":false,"title":"『사회』 64쪽 할 수 있어요 — 우리 가족이 살 자동차"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L02_challenge#10','soc',6,2,'u2','L02','tb_g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',4,'mc','auto','기업이 성장하려고 노력할 때 소비자가 얻게 되는 좋은 점으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u2-X04','SO6-2-u2-X02']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C2","difficulty":4,"kind":"mc","stem":"기업이 성장하려고 노력할 때 소비자가 얻게 되는 좋은 점으로 알맞은 것은 무엇인가요?","options":[{"t":"품질 좋은 상품을 보다 저렴한 가격에 살 수 있어요","correct":true},{"t":"기업만 이익을 보고 소비자는 손해를 봐요","mis":"SO6-2-u2-X04"},{"t":"상품 값이 반드시 비싸져요","mis":"SO6-2-u2-X02"},{"t":"일자리가 줄어들어요","mis":"SO6-2-u2-X04"}],"explanation":["품질과 생산량이 높아져요.","값이 저렴해질 수 있어요.","소비자에게도 좋아요."],"asset":{"type":"passage","lines":["(간추림) ○○ 기업은 올해 생산 시설을 늘리고 오래된 시설을 교체했다.","그 결과 상품의 품질과 생산량을 높였다.","보다 저렴한 가격에 우수한 품질의 상품을 고객에게 안정적으로 공급하게 됐다.","회사는 기업이 지속해서 성장하고 발전해야 한다고 강조했다."],"numbered":false,"title":"『사회』 66쪽 신문 기사 「지속적인 성장을 위한 기업의 노력」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L03_basic#1','soc',6,2,'u2','L03','tb_g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',1,'mc','auto','69쪽 기사에 따르면 입사 후 1년간 80 % 이상 출근한 근로자에게 보장하는 유급 휴가는 며칠인가요?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C3","difficulty":1,"kind":"mc","stem":"69쪽 기사에 따르면 입사 후 1년간 80 % 이상 출근한 근로자에게 보장하는 유급 휴가는 며칠인가요?","options":[{"t":"15일","correct":true},{"t":"1일","mis":"SO6-2-u2-X06"},{"t":"28일","mis":"SO6-2-u2-X06"},{"t":"42일","mis":"SO6-2-u2-X06"}],"explanation":["「근로 기준법」 제60조예요.","80 % 이상 출근이에요.","15일이에요."],"asset":{"type":"passage","lines":["(간추림) 휴가나 휴식 같은 기본 권리조차 보장받지 못하는 근로자가 많다.","「근로 기준법」 제60조 — 입사 후 1년간 80 % 이상 출근하면 15일의 유급 휴가","1년 미만이거나 80 % 미만 출근하면 1개월 개근할 때마다 1일의 유급 휴가","조사에 응한 근로자 중 28 %는 휴가를 제대로 사용하지 못했다.","응답자의 42 %는 몸이 아파도 휴가를 쓸 수 없어 출근했다.","휴게실 사용을 자제하라거나 쓰지 말라는 통보, 쓴 뒤 불이익을 받은 근로자도 있다."],"numbered":false,"title":"『사회』 69쪽 신문 기사 「법의 보호 밖에 놓여 있는 근로자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L03_basic#2','soc',6,2,'u2','L03','tb_g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',1,'sa','auto','휴가 기간에도 급여가 지급되는 휴가를 무엇이라고 하나요?','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u2-C3","difficulty":1,"kind":"sa","stem":"휴가 기간에도 급여가 지급되는 휴가를 무엇이라고 하나요?","answer":["유급 휴가","유급휴가"],"explanation":["69쪽 낱말 풀이예요.","급여가 지급돼요.","유급 휴가예요."],"mis":"SO6-2-u2-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L03_basic#3','soc',6,2,'u2','L03','tb_g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',1,'ox','auto','근로자는 근로 조건이나 근로 환경 등에 관해 기업과 협의할 수 없어요.',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C3","difficulty":1,"kind":"ox","stem":"근로자는 근로 조건이나 근로 환경 등에 관해 기업과 협의할 수 없어요.","answer":"X","reason_options":[{"t":"우리나라는 법과 제도로 근로자가 기업과 협의할 수 있게 보장하기 때문에","correct":true},{"t":"근로 조건은 기업이 혼자 정하는 것이기 때문에","mis":"SO6-2-u2-X06"}],"mis":"SO6-2-u2-X06","explanation":["71쪽 그림 ②예요.","협의할 수 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L03_basic#4','soc',6,2,'u2','L03','tb_g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',1,'blank','auto','꼭 기억해요: 우리나라는 근로자의 권리를 보호하려고 (    )과 제도를 마련해 두었어요. 빈칸에 알맞은 말은?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C3","difficulty":1,"kind":"blank","stem":"꼭 기억해요: 우리나라는 근로자의 권리를 보호하려고 (    )과 제도를 마련해 두었어요. 빈칸에 알맞은 말은?","options":[{"t":"법","correct":true},{"t":"광고","mis":"SO6-2-u2-X06"},{"t":"시장","mis":"SO6-2-u2-X06"},{"t":"관습","mis":"SO6-2-u2-X06"}],"explanation":["나라가 마련했어요.","제도와 짝이에요.","법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L03_basic#5','soc',6,2,'u2','L03','tb_g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',2,'mc','auto','69쪽 기사에서 몸이 아파도 휴가를 쓸 수 없어서 출근했다고 답한 사람은 응답자의 몇 %인가요?',ARRAY['SO6-2-u2-X06']::text[],true,'{"seq":5,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"mc","stem":"69쪽 기사에서 몸이 아파도 휴가를 쓸 수 없어서 출근했다고 답한 사람은 응답자의 몇 %인가요?","options":[{"t":"42 %","correct":true},{"t":"28 %","mis":"SO6-2-u2-X06"},{"t":"80 %","mis":"SO6-2-u2-X06"},{"t":"15 %","mis":"SO6-2-u2-X06"}],"explanation":["28 %는 휴가를 제대로 못 쓴 사람이에요.","아파도 출근한 사람은 따로 있어요.","42 %예요."],"asset":{"type":"passage","lines":["(간추림) 휴가나 휴식 같은 기본 권리조차 보장받지 못하는 근로자가 많다.","「근로 기준법」 제60조 — 입사 후 1년간 80 % 이상 출근하면 15일의 유급 휴가","1년 미만이거나 80 % 미만 출근하면 1개월 개근할 때마다 1일의 유급 휴가","조사에 응한 근로자 중 28 %는 휴가를 제대로 사용하지 못했다.","응답자의 42 %는 몸이 아파도 휴가를 쓸 수 없어 출근했다.","휴게실 사용을 자제하라거나 쓰지 말라는 통보, 쓴 뒤 불이익을 받은 근로자도 있다."],"numbered":false,"title":"『사회』 69쪽 신문 기사 「법의 보호 밖에 놓여 있는 근로자」"},"variant_rule":{"alt":[{"stem":"69쪽 기사에서 휴가를 제대로 사용하지 못했다고 답한 근로자는 몇 %인가요?","options":[{"t":"28 %","correct":true},{"t":"42 %","mis":"SO6-2-u2-X06"},{"t":"80 %","mis":"SO6-2-u2-X06"},{"t":"15 %","mis":"SO6-2-u2-X06"}],"explanation":["42 %는 아파도 출근한 사람이에요.","휴가를 못 쓴 비율을 찾아요.","28 %예요."],"asset":{"type":"passage","lines":["(간추림) 휴가나 휴식 같은 기본 권리조차 보장받지 못하는 근로자가 많다.","「근로 기준법」 제60조 — 입사 후 1년간 80 % 이상 출근하면 15일의 유급 휴가","1년 미만이거나 80 % 미만 출근하면 1개월 개근할 때마다 1일의 유급 휴가","조사에 응한 근로자 중 28 %는 휴가를 제대로 사용하지 못했다.","응답자의 42 %는 몸이 아파도 휴가를 쓸 수 없어 출근했다.","휴게실 사용을 자제하라거나 쓰지 말라는 통보, 쓴 뒤 불이익을 받은 근로자도 있다."],"numbered":false,"title":"『사회』 69쪽 신문 기사 「법의 보호 밖에 놓여 있는 근로자」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L03_basic#6','soc',6,2,'u2','L03','tb_g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',2,'match','auto','71쪽 그림과 근로자의 권리를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"match","stem":"71쪽 그림과 근로자의 권리를 알맞게 이으세요.","pairs":[{"l":"단체를 만들거나 가입하기","r":"더 나은 근로 조건을 만들려고 함께 모여요"},{"l":"기업과 협의하기","r":"출퇴근 시간을 조정하는 방안을 기업과 이야기해요"},{"l":"단체로 행동하기","r":"함께 복지 혜택을 늘려 달라고 요청해요"}],"mis":"SO6-2-u2-X06","explanation":["모이는 것은 단체예요.","이야기하는 것은 협의예요.","함께 요청하는 것은 단체 행동이에요."],"asset":{"type":"passage","lines":["그림 ① 근로자는 더 나은 근로 조건을 만들려고 단체를 만들거나 가입해요.","그림 ② 「출퇴근 시간을 개인별 상황에 맞게 조정할 수 있으면 좋겠습니다.」","그림 ② 「근무 시간을 자유롭게 운영하면 어떨까요?」","그림 ③ 「복지 혜택이 너무 부족해요.」","그림 ③ 「우리가 함께 복지 혜택을 늘려 달라고 요청합시다.」"],"title":"『사회』 71쪽 — 근로자의 권리를 보호하는 법과 제도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L03_basic#7','soc',6,2,'u2','L03','tb_g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',2,'mc','auto','근로자의 권리를 보호해야 하는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u2-X06','SO6-2-u2-X07']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"mc","stem":"근로자의 권리를 보호해야 하는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"노동력이 경제활동에서 중요하고, 근로자와 기업은 서로 의존하기 때문이에요","correct":true},{"t":"근로자만 이익을 보면 되기 때문이에요","mis":"SO6-2-u2-X06"},{"t":"기업은 근로자 없이도 생산할 수 있기 때문이에요","mis":"SO6-2-u2-X07"}],"explanation":["노동력은 꼭 필요해요.","근로자와 기업은 서로 의존해요.","그래서 보호해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L03_basic#8','soc',6,2,'u2','L03','tb_g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',2,'mc','auto','우리나라가 근로자의 권리를 보호하려고 실시하는 제도는 무엇인가요?',ARRAY['SO6-2-u2-X06']::text[],true,'{"seq":8,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"mc","stem":"우리나라가 근로자의 권리를 보호하려고 실시하는 제도는 무엇인가요?","options":[{"t":"육아 휴직 제도","correct":true},{"t":"휴가를 쓰지 못하게 하는 제도","mis":"SO6-2-u2-X06"},{"t":"기업이 근로 조건을 혼자 정하는 제도","mis":"SO6-2-u2-X06"}],"explanation":["71쪽 말풍선이에요.","근로자를 돕는 제도예요.","육아 휴직 제도예요."],"variant_rule":{"alt":[{"stem":"다음 가운데 근로자의 권리를 보호하는 제도는 무엇인가요?","options":[{"t":"최저 임금 제도","correct":true},{"t":"휴게실 사용을 막는 제도","mis":"SO6-2-u2-X06"},{"t":"기업이 급여를 마음대로 줄이는 제도","mis":"SO6-2-u2-X06"}],"explanation":["71쪽 말풍선이에요.","임금의 바닥을 정해요.","최저 임금 제도예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L03_basic#9','soc',6,2,'u2','L03','tb_g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',2,'sa','auto','69쪽 기사에서 기업으로부터 사용을 자제하라거나 아예 사용하지 말라는 통보를 받았다는 곳은 어디인가요?','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"sa","stem":"69쪽 기사에서 기업으로부터 사용을 자제하라거나 아예 사용하지 말라는 통보를 받았다는 곳은 어디인가요?","answer":["휴게실"],"explanation":["쉬는 곳이에요.","사용했다가 불이익을 받기도 했어요.","휴게실이에요."],"asset":{"type":"passage","lines":["(간추림) 휴가나 휴식 같은 기본 권리조차 보장받지 못하는 근로자가 많다.","「근로 기준법」 제60조 — 입사 후 1년간 80 % 이상 출근하면 15일의 유급 휴가","1년 미만이거나 80 % 미만 출근하면 1개월 개근할 때마다 1일의 유급 휴가","조사에 응한 근로자 중 28 %는 휴가를 제대로 사용하지 못했다.","응답자의 42 %는 몸이 아파도 휴가를 쓸 수 없어 출근했다.","휴게실 사용을 자제하라거나 쓰지 말라는 통보, 쓴 뒤 불이익을 받은 근로자도 있다."],"numbered":false,"title":"『사회』 69쪽 신문 기사 「법의 보호 밖에 놓여 있는 근로자」"},"mis":"SO6-2-u2-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L03_basic#10','soc',6,2,'u2','L03','tb_g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',3,'essay','teacher','근로자의 권리를 보호하는 방법을 하나 제시하고, 그 방법의 장점과 보완할 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u2-C3","difficulty":3,"kind":"essay","stem":"근로자의 권리를 보호하는 방법을 하나 제시하고, 그 방법의 장점과 보완할 점을 쓰세요.","answer_guide":{"answer":"예: 근로자에게 하는 폭언이나 폭행을 법에 따라 처벌해요. 장점: 근로자가 마음의 상처 없이 안전하게 일할 수 있어요. 보완할 점: 정도에 따라 어떻게 처벌할지 정하면 좋겠어요.","scoring_points":["보호 방법을 구체적으로 썼는가","장점을 썼는가","보완할 점을 썼는가"]},"explanation":["방법을 하나 정해요.","좋은 점을 써요.","더 고칠 점도 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L03_challenge#1','soc',6,2,'u2','L03','tb_g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',2,'error','auto','근로자의 권리를 보호하는 법과 제도에 대한 설명 가운데 잘못된 것을 고르세요.',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"error","stem":"근로자의 권리를 보호하는 법과 제도에 대한 설명 가운데 잘못된 것을 고르세요.","options":[{"t":"근로자는 다른 근로자들과 함께 단체로 행동할 수 없어요","correct":true,"mis_target":"SO6-2-u2-X06"},{"t":"근로자는 단체를 만들거나 단체에 가입할 수 있어요","mis":"SO6-2-u2-X06"},{"t":"우리나라는 최저 임금 제도를 실시해요","mis":"SO6-2-u2-X06"}],"explanation":["71쪽 그림 ③을 봐요.","단체로 행동할 수 있어요.","단체로 행동할 수 없다는 말이 잘못이에요."],"asset":{"type":"passage","lines":["그림 ① 근로자는 더 나은 근로 조건을 만들려고 단체를 만들거나 가입해요.","그림 ② 「출퇴근 시간을 개인별 상황에 맞게 조정할 수 있으면 좋겠습니다.」","그림 ② 「근무 시간을 자유롭게 운영하면 어떨까요?」","그림 ③ 「복지 혜택이 너무 부족해요.」","그림 ③ 「우리가 함께 복지 혜택을 늘려 달라고 요청합시다.」"],"title":"『사회』 71쪽 — 근로자의 권리를 보호하는 법과 제도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L03_challenge#2','soc',6,2,'u2','L03','tb_g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',2,'mc','auto','입사한 지 1년이 안 된 근로자는 「근로 기준법」 제60조에 따라 유급 휴가를 어떻게 받나요?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"mc","stem":"입사한 지 1년이 안 된 근로자는 「근로 기준법」 제60조에 따라 유급 휴가를 어떻게 받나요?","options":[{"t":"1개월 개근할 때마다 1일","correct":true},{"t":"1년 동안 휴가가 없어요","mis":"SO6-2-u2-X06"},{"t":"1개월 개근할 때마다 15일","mis":"SO6-2-u2-X06"}],"explanation":["1년 미만인 경우예요.","1개월 개근이 기준이에요.","1일씩이에요."],"asset":{"type":"passage","lines":["(간추림) 휴가나 휴식 같은 기본 권리조차 보장받지 못하는 근로자가 많다.","「근로 기준법」 제60조 — 입사 후 1년간 80 % 이상 출근하면 15일의 유급 휴가","1년 미만이거나 80 % 미만 출근하면 1개월 개근할 때마다 1일의 유급 휴가","조사에 응한 근로자 중 28 %는 휴가를 제대로 사용하지 못했다.","응답자의 42 %는 몸이 아파도 휴가를 쓸 수 없어 출근했다.","휴게실 사용을 자제하라거나 쓰지 말라는 통보, 쓴 뒤 불이익을 받은 근로자도 있다."],"numbered":false,"title":"『사회』 69쪽 신문 기사 「법의 보호 밖에 놓여 있는 근로자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L03_challenge#3','soc',6,2,'u2','L03','tb_g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',3,'mc','auto','근로자의 권리가 보호받지 못하는 상태가 계속되면 어떻게 될까요?',ARRAY['SO6-2-u2-X07','SO6-2-u2-X04']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C3","difficulty":3,"kind":"mc","stem":"근로자의 권리가 보호받지 못하는 상태가 계속되면 어떻게 될까요?","options":[{"t":"근로자의 의욕이 낮아져 좋은 물건이나 서비스를 만들기 어려워져요","correct":true},{"t":"기업은 아무 영향을 받지 않아요","mis":"SO6-2-u2-X07"},{"t":"소비자와는 상관없는 일이에요","mis":"SO6-2-u2-X04"}],"explanation":["일할 의욕이 떨어져요.","기업의 생산도 어려워져요.","모두에게 영향이 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L03_challenge#4','soc',6,2,'u2','L03','tb_g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',3,'mc','auto','71쪽 그림 ③에서 「복지 혜택이 너무 부족해요.」라는 말 뒤에 근로자들이 한 일은 무엇인가요?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C3","difficulty":3,"kind":"mc","stem":"71쪽 그림 ③에서 「복지 혜택이 너무 부족해요.」라는 말 뒤에 근로자들이 한 일은 무엇인가요?","options":[{"t":"함께 복지 혜택을 늘려 달라고 요청했어요","correct":true},{"t":"각자 조용히 참기로 했어요","mis":"SO6-2-u2-X06"},{"t":"기업 대신 근로 조건을 혼자 정했어요","mis":"SO6-2-u2-X06"}],"explanation":["함께 행동했어요.","정당한 권리를 주장했어요.","함께 요청했어요."],"asset":{"type":"passage","lines":["그림 ① 근로자는 더 나은 근로 조건을 만들려고 단체를 만들거나 가입해요.","그림 ② 「출퇴근 시간을 개인별 상황에 맞게 조정할 수 있으면 좋겠습니다.」","그림 ② 「근무 시간을 자유롭게 운영하면 어떨까요?」","그림 ③ 「복지 혜택이 너무 부족해요.」","그림 ③ 「우리가 함께 복지 혜택을 늘려 달라고 요청합시다.」"],"title":"『사회』 71쪽 — 근로자의 권리를 보호하는 법과 제도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L03_challenge#5','soc',6,2,'u2','L03','tb_g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',3,'ox','auto','근로자의 권리가 보호받으면 기업도 원하는 목표를 이룰 수 있어요.',ARRAY['SO6-2-u2-X07']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C3","difficulty":3,"kind":"ox","stem":"근로자의 권리가 보호받으면 기업도 원하는 목표를 이룰 수 있어요.","answer":"O","reason_options":[{"t":"근로자가 자기 일을 성실히 할 수 있게 되기 때문에","correct":true},{"t":"근로자의 권리는 기업과 상관없는 일이기 때문에","mis":"SO6-2-u2-X07"}],"mis":"SO6-2-u2-X07","explanation":["근로자가 성실히 일해요.","기업도 목표를 이뤄요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L03_challenge#6','soc',6,2,'u2','L03','tb_g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',3,'sa','auto','「근무 시간을 자유롭게 운영하면 어떨까요?」처럼 근로자가 근로 조건을 두고 기업과 의논하는 일을 두 글자로 무엇이라고 하나요?','{}'::text[],false,'{"seq":6,"concept":"SO6-2-u2-C3","difficulty":3,"kind":"sa","stem":"「근무 시간을 자유롭게 운영하면 어떨까요?」처럼 근로자가 근로 조건을 두고 기업과 의논하는 일을 두 글자로 무엇이라고 하나요?","answer":["협의"],"explanation":["71쪽 그림 ②예요.","기업과 의논해요.","협의예요."],"asset":{"type":"passage","lines":["그림 ① 근로자는 더 나은 근로 조건을 만들려고 단체를 만들거나 가입해요.","그림 ② 「출퇴근 시간을 개인별 상황에 맞게 조정할 수 있으면 좋겠습니다.」","그림 ② 「근무 시간을 자유롭게 운영하면 어떨까요?」","그림 ③ 「복지 혜택이 너무 부족해요.」","그림 ③ 「우리가 함께 복지 혜택을 늘려 달라고 요청합시다.」"],"title":"『사회』 71쪽 — 근로자의 권리를 보호하는 법과 제도"},"mis":"SO6-2-u2-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L03_challenge#7','soc',6,2,'u2','L03','tb_g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',3,'mc','auto','근로자의 권리를 보호하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C3","difficulty":3,"kind":"mc","stem":"근로자의 권리를 보호하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"근로자를 부당하게 해고할 수 없게 해요","correct":true},{"t":"휴식을 줄여 더 오래 일하게 해요","mis":"SO6-2-u2-X06"},{"t":"휴게실 사용을 막아요","mis":"SO6-2-u2-X06"},{"t":"권리에 관한 교육을 없애요","mis":"SO6-2-u2-X06"}],"explanation":["70쪽 친구와 활동이에요.","부당한 해고를 막아요.","그 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L03_challenge#8','soc',6,2,'u2','L03','tb_g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',4,'essay','teacher','근로자의 권리를 보호하자는 캠페인 문구를 만들고, 그 문구에 담은 권리를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u2-C3","difficulty":4,"kind":"essay","stem":"근로자의 권리를 보호하자는 캠페인 문구를 만들고, 그 문구에 담은 권리를 쓰세요.","answer_guide":{"answer":"예: 「작업 현장에서 위험할 땐 멈추세요! 정지 신호가 안전 신호!」 — 근로자가 안전하게 일할 권리를 담았어요.","scoring_points":["캠페인 문구를 만들었는가","담은 권리를 밝혔는가","쉽게 전달되도록 표현했는가"]},"explanation":["짧고 힘 있게 써요.","어떤 권리인지 밝혀요.","누구에게 전할지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L03_challenge#9','soc',6,2,'u2','L03','tb_g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',4,'essay','teacher','69쪽 기사 속 근로자들이 겪은 일이 왜 문제인지 「근로 기준법」의 내용과 이어서 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u2-C3","difficulty":4,"kind":"essay","stem":"69쪽 기사 속 근로자들이 겪은 일이 왜 문제인지 「근로 기준법」의 내용과 이어서 쓰세요.","answer_guide":{"answer":"예: 「근로 기준법」은 유급 휴가를 보장하는데, 28 %가 휴가를 제대로 쓰지 못하고 42 %는 아파도 출근했어요. 법이 정한 권리가 지켜지지 않았기 때문에 문제예요.","scoring_points":["법이 보장하는 내용을 썼는가","기사 속 사실을 들었는가","권리가 지켜지지 않았음을 밝혔는가"]},"explanation":["법은 무엇을 보장하나요?","기사에서는 어땠나요?","둘을 견주어요."],"asset":{"type":"passage","lines":["(간추림) 휴가나 휴식 같은 기본 권리조차 보장받지 못하는 근로자가 많다.","「근로 기준법」 제60조 — 입사 후 1년간 80 % 이상 출근하면 15일의 유급 휴가","1년 미만이거나 80 % 미만 출근하면 1개월 개근할 때마다 1일의 유급 휴가","조사에 응한 근로자 중 28 %는 휴가를 제대로 사용하지 못했다.","응답자의 42 %는 몸이 아파도 휴가를 쓸 수 없어 출근했다.","휴게실 사용을 자제하라거나 쓰지 말라는 통보, 쓴 뒤 불이익을 받은 근로자도 있다."],"numbered":false,"title":"『사회』 69쪽 신문 기사 「법의 보호 밖에 놓여 있는 근로자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L03_challenge#10','soc',6,2,'u2','L03','tb_g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',4,'mc','auto','「작업 현장에서 위험할 땐 멈추세요! 정지 신호가 안전 신호!」라는 캠페인 문구가 강조하는 것은 무엇인가요?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C3","difficulty":4,"kind":"mc","stem":"「작업 현장에서 위험할 땐 멈추세요! 정지 신호가 안전 신호!」라는 캠페인 문구가 강조하는 것은 무엇인가요?","options":[{"t":"근로자가 안전하게 일할 수 있는 환경","correct":true},{"t":"더 많은 광고","mis":"SO6-2-u2-X06"},{"t":"더 낮은 임금","mis":"SO6-2-u2-X06"},{"t":"휴게실 없애기","mis":"SO6-2-u2-X06"}],"explanation":["위험할 땐 멈추래요.","안전을 말해요.","안전하게 일할 환경이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L04_basic#1','soc',6,2,'u2','L04','tb_g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',1,'mc','auto','우리나라에서 기업을 세워 다른 기업과 자유롭게 경쟁하며 경제활동에 참여할 수 있는 것을 무엇이라고 하나요?',ARRAY['SO6-2-u2-X09','SO6-2-u2-X02']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C4","difficulty":1,"kind":"mc","stem":"우리나라에서 기업을 세워 다른 기업과 자유롭게 경쟁하며 경제활동에 참여할 수 있는 것을 무엇이라고 하나요?","options":[{"t":"기업의 자유","correct":true},{"t":"근로자의 권리","mis":"SO6-2-u2-X09"},{"t":"사회적 책임","mis":"SO6-2-u2-X09"},{"t":"시장의 가격","mis":"SO6-2-u2-X02"}],"explanation":["72쪽이에요.","헌법이 보장해요.","기업의 자유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L04_basic#2','soc',6,2,'u2','L04','tb_g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',1,'ox','auto','기업은 적은 비용으로 큰 이윤을 얻을 수 있도록 합리적으로 결정하려고 노력해요.',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C4","difficulty":1,"kind":"ox","stem":"기업은 적은 비용으로 큰 이윤을 얻을 수 있도록 합리적으로 결정하려고 노력해요.","answer":"O","reason_options":[{"t":"어떤 상품을 얼마나 생산할지 따져서 자유롭게 정하기 때문에","correct":true},{"t":"기업은 비용은 생각하지 않고 생산하기 때문에","mis":"SO6-2-u2-X08"}],"mis":"SO6-2-u2-X08","explanation":["꼭 기억해요 1이에요.","비용과 이윤을 따져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L04_basic#3','soc',6,2,'u2','L04','tb_g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',1,'sa','auto','꼭 기억해요: 기업의 경제활동은 사회에 큰 영향을 미치므로 사회에 대한 (ㅊㅇㄱ)을 가져야 해요. 낱말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u2-C4","difficulty":1,"kind":"sa","stem":"꼭 기억해요: 기업의 경제활동은 사회에 큰 영향을 미치므로 사회에 대한 (ㅊㅇㄱ)을 가져야 해요. 낱말을 쓰세요.","answer":["책임감"],"explanation":["초성은 ㅊㅇㄱ이에요.","사회에 대한 마음가짐이에요.","책임감이에요."],"mis":"SO6-2-u2-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L04_basic#4','soc',6,2,'u2','L04','tb_g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',1,'mc','auto','75쪽 신문 기사에서 ○○ 기업이 매년 지구의 날에 해 온 일은 무엇인가요?',ARRAY['SO6-2-u2-X09','SO6-2-u2-X08']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C4","difficulty":1,"kind":"mc","stem":"75쪽 신문 기사에서 ○○ 기업이 매년 지구의 날에 해 온 일은 무엇인가요?","options":[{"t":"△△ 공원에서 나무 심기 캠페인","correct":true},{"t":"광고비 늘리기","mis":"SO6-2-u2-X09"},{"t":"다른 기업과 함께 가격 올리기","mis":"SO6-2-u2-X08"}],"explanation":["지구의 날 행사예요.","나무를 심어요.","나무 심기 캠페인이에요."],"asset":{"type":"passage","lines":["(간추림) ○○ 기업은 2016년부터 매년 지구의 날(4월 22일)에 나무를 심어 왔다.","장소는 △△ 공원, 까닭은 도심의 미세 먼지와 기후 위기 대응이다.","올해는 탄소 흡수량이 많다고 알려진 신갈나무와 갈참나무 100그루를 심었다.","「사회에 이바지하며 지속가능한 경영을 해 보자는 생각에서 하고 있다.」"],"numbered":false,"title":"『사회』 75쪽 신문 기사 「기업이 사회적 책임 다해야… 지구의 날 기념 나무 심기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L04_basic#5','soc',6,2,'u2','L04','tb_g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',2,'mc','auto','73쪽 ①에서 10대와 20대가 고루 좋아하는 제품은 무엇인가요?',ARRAY['SO6-2-u2-X05']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"mc","stem":"73쪽 ①에서 10대와 20대가 고루 좋아하는 제품은 무엇인가요?","options":[{"t":"□□ 제품","correct":true},{"t":"○○ 제품","mis":"SO6-2-u2-X05"},{"t":"△△ 제품","mis":"SO6-2-u2-X05"}],"explanation":["두 나이대를 함께 봐요.","둘 다 높은 제품을 찾아요.","□□ 제품이에요."],"asset":{"type":"passage","lines":["① 제품 선호도 — 10대: □□ 가장 높음, △△ 중간, ○○ 낮음","① 제품 선호도 — 20대: ○○ 가장 높음, □□ 비슷하게 높음, △△ 낮음","② 상품 가격 — ㉮ 기업 2,200원 · 우리 기업 2,300원 · ㉯ 기업 2,400원","② 생산 비용 — 세 기업 모두 1,500원","③ 1위 ㉰ 기업 광고비 지출 비율 — 온라인 46 % · 방송 27 %","③ (이어서) 기타 12 % · 지면 10 % · 현장 5 %"],"numbered":false,"title":"『사회』 73쪽 — 기업이 내려야 할 결정(그래프·표를 글로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L04_basic#6','soc',6,2,'u2','L04','tb_g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',2,'mc','auto','73쪽 ②에서 우리 기업 상품의 판매량을 높이려면 어떤 결정을 내릴 수 있을까요?',ARRAY['SO6-2-u2-X05','SO6-2-u2-X08']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"mc","stem":"73쪽 ②에서 우리 기업 상품의 판매량을 높이려면 어떤 결정을 내릴 수 있을까요?","options":[{"t":"가격을 2,200원으로 낮춰요","correct":true},{"t":"가격을 2,400원으로 올려요","mis":"SO6-2-u2-X05"},{"t":"다른 기업과 약속해 함께 가격을 올려요","mis":"SO6-2-u2-X08"}],"explanation":["우리 기업은 2,300원이에요.","생산 비용은 모두 1,500원이에요.","가격을 2,200원으로 낮춰요."],"asset":{"type":"passage","lines":["① 제품 선호도 — 10대: □□ 가장 높음, △△ 중간, ○○ 낮음","① 제품 선호도 — 20대: ○○ 가장 높음, □□ 비슷하게 높음, △△ 낮음","② 상품 가격 — ㉮ 기업 2,200원 · 우리 기업 2,300원 · ㉯ 기업 2,400원","② 생산 비용 — 세 기업 모두 1,500원","③ 1위 ㉰ 기업 광고비 지출 비율 — 온라인 46 % · 방송 27 %","③ (이어서) 기타 12 % · 지면 10 % · 현장 5 %"],"numbered":false,"title":"『사회』 73쪽 — 기업이 내려야 할 결정(그래프·표를 글로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L04_basic#7','soc',6,2,'u2','L04','tb_g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',2,'mc','auto','73쪽 ③에서 1위 ㉰ 기업이 광고비를 가장 많이 쓴 곳은 어디인가요?',ARRAY['SO6-2-u2-X05']::text[],true,'{"seq":7,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"mc","stem":"73쪽 ③에서 1위 ㉰ 기업이 광고비를 가장 많이 쓴 곳은 어디인가요?","options":[{"t":"온라인 광고","correct":true},{"t":"방송 광고","mis":"SO6-2-u2-X05"},{"t":"지면 광고","mis":"SO6-2-u2-X05"},{"t":"현장 광고","mis":"SO6-2-u2-X05"}],"explanation":["비율을 견줘요.","46 %가 가장 커요.","온라인 광고예요."],"asset":{"type":"passage","lines":["① 제품 선호도 — 10대: □□ 가장 높음, △△ 중간, ○○ 낮음","① 제품 선호도 — 20대: ○○ 가장 높음, □□ 비슷하게 높음, △△ 낮음","② 상품 가격 — ㉮ 기업 2,200원 · 우리 기업 2,300원 · ㉯ 기업 2,400원","② 생산 비용 — 세 기업 모두 1,500원","③ 1위 ㉰ 기업 광고비 지출 비율 — 온라인 46 % · 방송 27 %","③ (이어서) 기타 12 % · 지면 10 % · 현장 5 %"],"numbered":false,"title":"『사회』 73쪽 — 기업이 내려야 할 결정(그래프·표를 글로)"},"variant_rule":{"alt":[{"stem":"73쪽 ③에서 ㉰ 기업이 광고비를 두 번째로 많이 쓴 곳은 어디인가요?","options":[{"t":"방송 광고","correct":true},{"t":"온라인 광고","mis":"SO6-2-u2-X05"},{"t":"지면 광고","mis":"SO6-2-u2-X05"},{"t":"현장 광고","mis":"SO6-2-u2-X05"}],"explanation":["46 % 다음을 찾아요.","27 %예요.","방송 광고예요."],"asset":{"type":"passage","lines":["① 제품 선호도 — 10대: □□ 가장 높음, △△ 중간, ○○ 낮음","① 제품 선호도 — 20대: ○○ 가장 높음, □□ 비슷하게 높음, △△ 낮음","② 상품 가격 — ㉮ 기업 2,200원 · 우리 기업 2,300원 · ㉯ 기업 2,400원","② 생산 비용 — 세 기업 모두 1,500원","③ 1위 ㉰ 기업 광고비 지출 비율 — 온라인 46 % · 방송 27 %","③ (이어서) 기타 12 % · 지면 10 % · 현장 5 %"],"numbered":false,"title":"『사회』 73쪽 — 기업이 내려야 할 결정(그래프·표를 글로)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L04_basic#8','soc',6,2,'u2','L04','tb_g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',2,'match','auto','76쪽 사진과 기업이 중요하게 여기는 가치를 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"match","stem":"76쪽 사진과 기업이 중요하게 여기는 가치를 알맞게 이으세요.","pairs":[{"l":"환경","r":"공장 지붕에 태양광 패널을 설치해요"},{"l":"사회","r":"직원들이 벽화를 그려 지역을 가꿔요"},{"l":"투명 경영","r":"기업과 근로자가 함께 힘을 모아요"}],"mis":"SO6-2-u2-X09","explanation":["태양광은 환경이에요.","지역을 가꾸는 것은 사회예요.","근로자와 소통은 투명 경영이에요."],"asset":{"type":"passage","lines":["사진 ① 공장 지붕에 태양광 패널을 설치해 친환경 에너지 사용을 늘립니다.","사진 ② 기업을 투명하게 운영하려고 기업과 근로자가 함께 힘을 모읍니다.","사진 ③ 기업 직원들이 벽화 작업을 하며 지역을 아름답게 가꿉니다."],"title":"『사회』 76쪽 — 기업의 사회적 책임이 커졌어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L04_basic#9','soc',6,2,'u2','L04','tb_g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',2,'ox','auto','기업끼리 경쟁하는 것은 그 자체로 나쁜 일이에요.',ARRAY['SO6-2-u2-X25']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"ox","stem":"기업끼리 경쟁하는 것은 그 자체로 나쁜 일이에요.","answer":"X","reason_options":[{"t":"자유로운 경쟁으로 품질 좋고 다양한 상품이 생기고, 문제는 지나친 경쟁에서 생기기 때문에","correct":true},{"t":"기업이 이윤을 얻으려는 것 자체가 잘못이기 때문에","mis":"SO6-2-u2-X25"}],"mis":"SO6-2-u2-X25","explanation":["경쟁은 좋은 상품을 낳아요.","지나친 경쟁이 문제예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L04_basic#10','soc',6,2,'u2','L04','tb_g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',3,'essay','teacher','74쪽 그림의 문제 가운데 하나를 골라, 그 문제가 생긴 까닭과 해결 방법을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"essay","stem":"74쪽 그림의 문제 가운데 하나를 골라, 그 문제가 생긴 까닭과 해결 방법을 쓰세요.","answer_guide":{"answer":"예: 일부 회사들끼리 약속해서 함께 가격을 올렸어요. 소비자의 피해는 생각하지 않고 이윤만 중요하게 여겼기 때문이에요. 정부가 공정하게 경쟁하는지 감시하면 좋겠어요.","scoring_points":["문제를 하나 골랐는가","생긴 까닭을 썼는가","알맞은 해결 방법을 썼는가"]},"explanation":["문제를 골라요.","왜 생겼나요?","어떻게 고칠까요?"],"asset":{"type":"passage","lines":["그림 ㉮ 기업이 제품을 생산하는 과정에서 환경을 오염하기도 합니다.","그림 ㉯ 일부 회사들끼리 약속해서 함께 가격을 올리기도 합니다.","그림 ㉰ 소비자에게 잘못된 정보를 제공하기도 합니다.","그림 ㉱ 기업 간에 사업을 방해하는 경우도 있습니다."],"title":"『사회』 74쪽 — 기업이 경제활동을 하면서 생길 수 있는 문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L04_challenge#1','soc',6,2,'u2','L04','tb_g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',2,'error','auto','77쪽 「재미있게 확인해요」의 가게 설명 가운데 잘못된 것을 고르세요.',ARRAY['SO6-2-u2-X08','SO6-2-u2-X06','SO6-2-u2-X01']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"error","stem":"77쪽 「재미있게 확인해요」의 가게 설명 가운데 잘못된 것을 고르세요.","options":[{"t":"우리나라에서 기업은 어떤 상품을 얼마나 생산할지 자유롭게 정할 수 없어요","correct":true,"mis_target":"SO6-2-u2-X08"},{"t":"근로자는 더 나은 근로 조건을 만들려고 단체를 만들거나 가입할 수 있어요","mis":"SO6-2-u2-X06"},{"t":"시장은 물건이나 서비스의 거래가 이루어지는 곳이에요","mis":"SO6-2-u2-X01"}],"explanation":["기업의 자유를 떠올려요.","무엇을 얼마나 만들지 스스로 정해요.","정할 수 없다는 말이 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L04_challenge#2','soc',6,2,'u2','L04','tb_g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',2,'mc','auto','72쪽 기사에서 말한 기업의 자유로운 경제활동의 장점은 무엇인가요?',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"mc","stem":"72쪽 기사에서 말한 기업의 자유로운 경제활동의 장점은 무엇인가요?","options":[{"t":"투자와 일자리를 늘리고 국민 삶의 질을 높여요","correct":true},{"t":"기업이 세금을 내지 않아도 돼요","mis":"SO6-2-u2-X08"},{"t":"기업이 법을 지키지 않아도 돼요","mis":"SO6-2-u2-X08"}],"explanation":["기사의 말을 찾아요.","투자·일자리·삶의 질이에요.","그 장점이에요."],"asset":{"type":"passage","lines":["(간추림) 기업 경영자 모임의 대표가 말했다.","「기업의 자유로운 경제활동이 투자와 일자리를 늘리고 국민 삶의 질을 높인다.」","「기업은 투자를 늘려 좋은 일자리를 만들고, 필요한 근로자를 충분히 채용해야 한다.」","「정부와 국회도 기업 성장의 동반자가 되어 자유로운 경제활동을 지원해야 한다.」"],"numbered":false,"title":"『사회』 72쪽 신문 기사 「우리 경제를 다시 뛰게 하자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L04_challenge#3','soc',6,2,'u2','L04','tb_g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',3,'mc','auto','정부와 국회가 기업의 자유로운 경제활동을 지원하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u2-X08','SO6-2-u2-X09']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"mc","stem":"정부와 국회가 기업의 자유로운 경제활동을 지원하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"자유로운 경제활동을 막는 불합리한 법과 제도를 고쳐요","correct":true},{"t":"기업 대신 무엇을 생산할지 모두 정해 줘요","mis":"SO6-2-u2-X08"},{"t":"기업끼리 가격을 맞추도록 도와줘요","mis":"SO6-2-u2-X09"}],"explanation":["정부와 국회는 동반자예요.","방해되는 제도를 고쳐요.","그 방법이에요."],"asset":{"type":"passage","lines":["(간추림) 기업 경영자 모임의 대표가 말했다.","「기업의 자유로운 경제활동이 투자와 일자리를 늘리고 국민 삶의 질을 높인다.」","「기업은 투자를 늘려 좋은 일자리를 만들고, 필요한 근로자를 충분히 채용해야 한다.」","「정부와 국회도 기업 성장의 동반자가 되어 자유로운 경제활동을 지원해야 한다.」"],"numbered":false,"title":"『사회』 72쪽 신문 기사 「우리 경제를 다시 뛰게 하자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L04_challenge#4','soc',6,2,'u2','L04','tb_g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',3,'match','auto','74쪽 문제와 그 문제를 줄이는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"match","stem":"74쪽 문제와 그 문제를 줄이는 방법을 알맞게 이으세요.","pairs":[{"l":"환경을 오염해요","r":"환경을 오염하지 않는 것이 확인되면 세금 혜택을 줘요"},{"l":"소비자에게 잘못된 정보를 줘요","r":"허위·과장 광고를 하지 못하게 정부가 감시해요"},{"l":"다른 기업의 사업을 방해해요","r":"작은 기업도 공정하게 경쟁하도록 법을 만들어요"}],"mis":"SO6-2-u2-X09","explanation":["환경에는 세금 혜택이에요.","잘못된 정보에는 감시예요.","방해에는 공정 경쟁의 법이에요."],"asset":{"type":"passage","lines":["그림 ㉮ 기업이 제품을 생산하는 과정에서 환경을 오염하기도 합니다.","그림 ㉯ 일부 회사들끼리 약속해서 함께 가격을 올리기도 합니다.","그림 ㉰ 소비자에게 잘못된 정보를 제공하기도 합니다.","그림 ㉱ 기업 간에 사업을 방해하는 경우도 있습니다."],"title":"『사회』 74쪽 — 기업이 경제활동을 하면서 생길 수 있는 문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L04_challenge#5','soc',6,2,'u2','L04','tb_g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',3,'mc','auto','기업이 경쟁하는 과정에서 74쪽과 같은 문제가 생기는 까닭은 무엇인가요?',ARRAY['SO6-2-u2-X08','SO6-2-u2-X25']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"mc","stem":"기업이 경쟁하는 과정에서 74쪽과 같은 문제가 생기는 까닭은 무엇인가요?","options":[{"t":"소비자나 다른 기업의 피해는 생각하지 않고 이윤만 중요하게 여겨서","correct":true},{"t":"기업에 자유가 전혀 없어서","mis":"SO6-2-u2-X08"},{"t":"경쟁은 언제나 나쁜 일이라서","mis":"SO6-2-u2-X25"}],"explanation":["남의 피해를 놓쳤어요.","이윤만 생각했어요.","그래서 문제가 생겨요."],"asset":{"type":"passage","lines":["그림 ㉮ 기업이 제품을 생산하는 과정에서 환경을 오염하기도 합니다.","그림 ㉯ 일부 회사들끼리 약속해서 함께 가격을 올리기도 합니다.","그림 ㉰ 소비자에게 잘못된 정보를 제공하기도 합니다.","그림 ㉱ 기업 간에 사업을 방해하는 경우도 있습니다."],"title":"『사회』 74쪽 — 기업이 경제활동을 하면서 생길 수 있는 문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L04_challenge#6','soc',6,2,'u2','L04','tb_g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',3,'mc','auto','75쪽 기사에서 신갈나무와 갈참나무를 심은 까닭은 무엇인가요?',ARRAY['SO6-2-u2-X09']::text[],true,'{"seq":6,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"mc","stem":"75쪽 기사에서 신갈나무와 갈참나무를 심은 까닭은 무엇인가요?","options":[{"t":"탄소 흡수량이 많다고 알려져서","correct":true},{"t":"값이 가장 싸서","mis":"SO6-2-u2-X09"},{"t":"광고판으로 쓰려고","mis":"SO6-2-u2-X09"}],"explanation":["기후 위기에 대응해요.","탄소를 많이 흡수해요.","그래서 골랐어요."],"asset":{"type":"passage","lines":["(간추림) ○○ 기업은 2016년부터 매년 지구의 날(4월 22일)에 나무를 심어 왔다.","장소는 △△ 공원, 까닭은 도심의 미세 먼지와 기후 위기 대응이다.","올해는 탄소 흡수량이 많다고 알려진 신갈나무와 갈참나무 100그루를 심었다.","「사회에 이바지하며 지속가능한 경영을 해 보자는 생각에서 하고 있다.」"],"numbered":false,"title":"『사회』 75쪽 신문 기사 「기업이 사회적 책임 다해야… 지구의 날 기념 나무 심기」"},"variant_rule":{"alt":[{"stem":"75쪽 기사에서 올해 캠페인 현장에서 심은 나무는 몇 그루인가요?","options":[{"t":"100그루","correct":true},{"t":"22그루","mis":"SO6-2-u2-X09"},{"t":"2016그루","mis":"SO6-2-u2-X09"}],"explanation":["22는 지구의 날 날짜예요.","2016은 시작한 해예요.","100그루예요."],"asset":{"type":"passage","lines":["(간추림) ○○ 기업은 2016년부터 매년 지구의 날(4월 22일)에 나무를 심어 왔다.","장소는 △△ 공원, 까닭은 도심의 미세 먼지와 기후 위기 대응이다.","올해는 탄소 흡수량이 많다고 알려진 신갈나무와 갈참나무 100그루를 심었다.","「사회에 이바지하며 지속가능한 경영을 해 보자는 생각에서 하고 있다.」"],"numbered":false,"title":"『사회』 75쪽 신문 기사 「기업이 사회적 책임 다해야… 지구의 날 기념 나무 심기」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L04_challenge#7','soc',6,2,'u2','L04','tb_g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',3,'ox','auto','과거에도 기업은 환경, 사회, 투명 경영을 가장 중요하게 여겼어요.',ARRAY['SO6-2-u2-X09']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"ox","stem":"과거에도 기업은 환경, 사회, 투명 경영을 가장 중요하게 여겼어요.","answer":"X","reason_options":[{"t":"과거에는 많은 이윤만 중요하게 여겼고, 경제가 성장하며 사회적 책임이 커졌기 때문에","correct":true},{"t":"기업은 처음부터 이윤보다 사회만 생각했기 때문에","mis":"SO6-2-u2-X09"}],"mis":"SO6-2-u2-X09","explanation":["76쪽 첫 문장이에요.","과거엔 이윤만 봤어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L04_challenge#8','soc',6,2,'u2','L04','tb_g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',4,'essay','teacher','기업에 자유가 없을 때와 기업에 자유만 있을 때 각각 어떤 일이 생길지 쓰고, 기업에 자유와 책임이 함께 필요한 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u2-C4","difficulty":4,"kind":"essay","stem":"기업에 자유가 없을 때와 기업에 자유만 있을 때 각각 어떤 일이 생길지 쓰고, 기업에 자유와 책임이 함께 필요한 까닭을 쓰세요.","answer_guide":{"answer":"예: 자유가 없으면 원하는 물건을 만들 수 없어 소비자가 다양한 물건을 살 수 없어요. 자유만 있으면 이윤만 좇다 환경 오염 같은 문제가 생겨요. 그래서 자유와 책임이 함께 필요해요.","scoring_points":["자유가 없을 때를 썼는가","자유만 있을 때를 썼는가","자유와 책임이 함께 필요한 까닭을 썼는가"]},"explanation":["자유가 없으면?","자유만 있으면?","둘을 함께 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L04_challenge#9','soc',6,2,'u2','L04','tb_g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',4,'essay','teacher','활동지 글에서 ○○ 기업이 사회적 책임을 다하는 모습을 두 가지 찾아 쓰고, 그 모습이 환경·사회·투명 경영 가운데 어느 쪽인지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u2-C4","difficulty":4,"kind":"essay","stem":"활동지 글에서 ○○ 기업이 사회적 책임을 다하는 모습을 두 가지 찾아 쓰고, 그 모습이 환경·사회·투명 경영 가운데 어느 쪽인지 쓰세요.","answer_guide":{"answer":"예: 스포츠 용품을 환경친화적으로 생산하고 재활용해요(환경). 근로자의 권리를 존중해요(사회).","scoring_points":["책임을 다하는 모습 두 가지를 찾았는가","각각의 갈래를 바르게 밝혔는가","글의 사실로 썼는가"]},"explanation":["글에서 찾아요.","갈래를 나눠요.","두 가지를 써요."],"asset":{"type":"passage","lines":["(간추림) ○○ 기업은 스포츠 용품을 환경친화적으로 생산하고 재활용한다.","제품 수명을 늘리는 수리 서비스와 중고 제품 판매도 늘리고 있다.","사회 관계망 서비스에 환경 문제의 심각성을 알리는 캠페인 광고를 올린다.","친환경 소재, 지속가능한 에너지, 근로자의 권리 존중을 실천한다."],"numbered":false,"title":"활동지 — ○○ 기업의 지속가능성 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L04_challenge#10','soc',6,2,'u2','L04','tb_g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',4,'mc','auto','73쪽 자료를 보고 내린 결정과 그 까닭이 알맞게 짝지어진 것은 무엇인가요?',ARRAY['SO6-2-u2-X02','SO6-2-u2-X05']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C4","difficulty":4,"kind":"mc","stem":"73쪽 자료를 보고 내린 결정과 그 까닭이 알맞게 짝지어진 것은 무엇인가요?","options":[{"t":"우리 기업 가격이 ㉮ 기업보다 비싸니 2,200원으로 낮춘다","correct":true},{"t":"생산 비용이 1,500원이니 가격을 2,400원으로 올린다","mis":"SO6-2-u2-X02"},{"t":"㉰ 기업이 방송 광고를 가장 많이 하니 방송 광고만 한다","mis":"SO6-2-u2-X05"},{"t":"10대만 좋아하는 ○○ 제품을 늘린다","mis":"SO6-2-u2-X05"}],"explanation":["자료의 사실과 맞는지 봐요.","우리 기업은 2,300원이에요.","가격을 낮추는 결정이 맞아요."],"asset":{"type":"passage","lines":["① 제품 선호도 — 10대: □□ 가장 높음, △△ 중간, ○○ 낮음","① 제품 선호도 — 20대: ○○ 가장 높음, □□ 비슷하게 높음, △△ 낮음","② 상품 가격 — ㉮ 기업 2,200원 · 우리 기업 2,300원 · ㉯ 기업 2,400원","② 생산 비용 — 세 기업 모두 1,500원","③ 1위 ㉰ 기업 광고비 지출 비율 — 온라인 46 % · 방송 27 %","③ (이어서) 기타 12 % · 지면 10 % · 현장 5 %"],"numbered":false,"title":"『사회』 73쪽 — 기업이 내려야 할 결정(그래프·표를 글로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L05_basic#1','soc',6,2,'u2','L05','tb_g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C5',1,'mc','auto','국가의 전체적인 생산 수준이나 국민 소득이 증가하여 경제 규모가 커지는 것을 무엇이라고 하나요?',ARRAY['SO6-2-u2-X10','SO6-2-u2-X09']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C5","difficulty":1,"kind":"mc","stem":"국가의 전체적인 생산 수준이나 국민 소득이 증가하여 경제 규모가 커지는 것을 무엇이라고 하나요?","options":[{"t":"경제성장","correct":true},{"t":"시장경제","mis":"SO6-2-u2-X10"},{"t":"인구 증가","mis":"SO6-2-u2-X10"},{"t":"사회적 책임","mis":"SO6-2-u2-X09"}],"explanation":["경제 규모가 커져요.","생산과 소득이 늘어요.","경제성장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L05_basic#2','soc',6,2,'u2','L05','tb_g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C5',1,'sa','auto','6·25 전쟁으로 폐허가 된 뒤 이룬 우리나라의 빠른 경제성장을 세계는 무엇이라고 불렀나요?','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u2-C5","difficulty":1,"kind":"sa","stem":"6·25 전쟁으로 폐허가 된 뒤 이룬 우리나라의 빠른 경제성장을 세계는 무엇이라고 불렀나요?","answer":["한강의 기적"],"explanation":["80쪽 누리집 글이에요.","강 이름이 들어가요.","한강의 기적이에요."],"asset":{"type":"passage","lines":["(간추림) 우리나라는 세계에서 손꼽힐 만큼 빠른 경제성장을 이루었다.","6·25 전쟁으로 산업 시설이 폐허가 되고 자본·자원도 거의 없었다.","세계는 이 성장을 「한강의 기적」이라고 불렀다.","1960년대 경제 개발 5개년 계획 — 경공업 제품 수출","1970년대 — 중화학 공업이 발달하며 빠르게 성장","1988년 제24회 서울 올림픽 대회 · 1996년 12월 OECD에 29번째로 가입","오늘날 — 휴대 전화·반도체·자동차·화학·철강, 음악·게임·웹툰"],"numbered":false,"title":"『사회』 80쪽 누리집 글 「한국 경제, 기적을 만들다」"},"mis":"SO6-2-u2-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L05_basic#3','soc',6,2,'u2','L05','tb_g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C5',1,'ox','auto','우리나라는 가계와 기업, 정부가 함께 노력하여 빠른 경제성장을 이루었어요.',ARRAY['SO6-2-u2-X12']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C5","difficulty":1,"kind":"ox","stem":"우리나라는 가계와 기업, 정부가 함께 노력하여 빠른 경제성장을 이루었어요.","answer":"O","reason_options":[{"t":"80쪽처럼 어려운 시기를 겪은 뒤 모두가 함께 노력했기 때문에","correct":true},{"t":"정부 혼자의 노력으로 저절로 이루어졌기 때문에","mis":"SO6-2-u2-X12"}],"mis":"SO6-2-u2-X12","explanation":["꼭 기억해요 2예요.","가계·기업·정부가 함께했어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L05_basic#4','soc',6,2,'u2','L05','tb_g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C6',1,'blank','auto','꼭 기억해요: 경제성장에 따라 사람들의 생활이 풍족해지면서 (    )와 관련한 산업이 발달했어요. 빈칸에 알맞은 말은?',ARRAY['SO6-2-u2-X13']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C6","difficulty":1,"kind":"blank","stem":"꼭 기억해요: 경제성장에 따라 사람들의 생활이 풍족해지면서 (    )와 관련한 산업이 발달했어요. 빈칸에 알맞은 말은?","options":[{"t":"문화","correct":true},{"t":"정치","mis":"SO6-2-u2-X13"},{"t":"전쟁","mis":"SO6-2-u2-X13"}],"explanation":["생활이 풍족해졌어요.","영화·음악·게임이에요.","문화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L05_basic#5','soc',6,2,'u2','L05','tb_g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C5',2,'mc','auto','79쪽 자료에서 1960년에 1인당 국민 총소득이 더 높았던 나라는 어디인가요?',ARRAY['SO6-2-u2-X11']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C5","difficulty":2,"kind":"mc","stem":"79쪽 자료에서 1960년에 1인당 국민 총소득이 더 높았던 나라는 어디인가요?","options":[{"t":"○○ 나라","correct":true},{"t":"우리나라","mis":"SO6-2-u2-X11"},{"t":"두 나라가 같았어요","mis":"SO6-2-u2-X11"}],"explanation":["1960년 값을 견줘요.","우리나라 120, ○○ 나라 230이에요.","○○ 나라예요."],"asset":{"type":"passage","lines":["연도 — 1960 · 1970 · 1980 · 1990 · 2000 · 2010 · 2023","우리나라 — 120 · 280 · 1,870 · 6,450 · 11,030 · 22,290 · 35,490","○○ 나라 — 230 · 240 · 770 · 830 · 1,180 · 2,360 · 4,230","(단위: 달러 · 꺾은선그래프를 글로 옮김)"],"numbered":false,"title":"『사회』 79쪽 — 1인당 국민 총소득 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L05_basic#6','soc',6,2,'u2','L05','tb_g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C5',2,'mc','auto','79쪽 자료에서 2023년 우리나라의 1인당 국민 총소득은 얼마인가요?',ARRAY['SO6-2-u2-X10']::text[],true,'{"seq":6,"concept":"SO6-2-u2-C5","difficulty":2,"kind":"mc","stem":"79쪽 자료에서 2023년 우리나라의 1인당 국민 총소득은 얼마인가요?","options":[{"t":"35,490달러","correct":true},{"t":"4,230달러","mis":"SO6-2-u2-X10"},{"t":"22,290달러","mis":"SO6-2-u2-X10"},{"t":"11,030달러","mis":"SO6-2-u2-X10"}],"explanation":["2023년 우리나라 값이에요.","4,230달러는 ○○ 나라예요.","35,490달러예요."],"asset":{"type":"passage","lines":["연도 — 1960 · 1970 · 1980 · 1990 · 2000 · 2010 · 2023","우리나라 — 120 · 280 · 1,870 · 6,450 · 11,030 · 22,290 · 35,490","○○ 나라 — 230 · 240 · 770 · 830 · 1,180 · 2,360 · 4,230","(단위: 달러 · 꺾은선그래프를 글로 옮김)"],"numbered":false,"title":"『사회』 79쪽 — 1인당 국민 총소득 변화"},"variant_rule":{"alt":[{"stem":"79쪽 자료에서 2010년 우리나라의 1인당 국민 총소득은 얼마인가요?","options":[{"t":"22,290달러","correct":true},{"t":"2,360달러","mis":"SO6-2-u2-X10"},{"t":"35,490달러","mis":"SO6-2-u2-X10"},{"t":"11,030달러","mis":"SO6-2-u2-X10"}],"explanation":["2010년 우리나라 값이에요.","2,360달러는 ○○ 나라예요.","22,290달러예요."],"asset":{"type":"passage","lines":["연도 — 1960 · 1970 · 1980 · 1990 · 2000 · 2010 · 2023","우리나라 — 120 · 280 · 1,870 · 6,450 · 11,030 · 22,290 · 35,490","○○ 나라 — 230 · 240 · 770 · 830 · 1,180 · 2,360 · 4,230","(단위: 달러 · 꺾은선그래프를 글로 옮김)"],"numbered":false,"title":"『사회』 79쪽 — 1인당 국민 총소득 변화"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L05_basic#7','soc',6,2,'u2','L05','tb_g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C5',2,'mc','auto','우리나라의 경제성장을 「한강의 기적」이라고 부르는 까닭은 무엇인가요?',ARRAY['SO6-2-u2-X11','SO6-2-u2-X12']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C5","difficulty":2,"kind":"mc","stem":"우리나라의 경제성장을 「한강의 기적」이라고 부르는 까닭은 무엇인가요?","options":[{"t":"산업 시설이 폐허가 되고 자본·자원이 거의 없는 상태에서 매우 빠르게 성장해서","correct":true},{"t":"자원이 풍부해서 쉽게 성장해서","mis":"SO6-2-u2-X11"},{"t":"한강 주변에서만 경제가 성장해서","mis":"SO6-2-u2-X12"}],"explanation":["출발은 폐허였어요.","자본·자원도 거의 없었어요.","그런데도 빠르게 성장해서예요."],"asset":{"type":"passage","lines":["(간추림) 우리나라는 세계에서 손꼽힐 만큼 빠른 경제성장을 이루었다.","6·25 전쟁으로 산업 시설이 폐허가 되고 자본·자원도 거의 없었다.","세계는 이 성장을 「한강의 기적」이라고 불렀다.","1960년대 경제 개발 5개년 계획 — 경공업 제품 수출","1970년대 — 중화학 공업이 발달하며 빠르게 성장","1988년 제24회 서울 올림픽 대회 · 1996년 12월 OECD에 29번째로 가입","오늘날 — 휴대 전화·반도체·자동차·화학·철강, 음악·게임·웹툰"],"numbered":false,"title":"『사회』 80쪽 누리집 글 「한국 경제, 기적을 만들다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L05_basic#8','soc',6,2,'u2','L05','tb_g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C6',2,'match','auto','경제성장이 우리 생활에 미친 영향과 그 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u2-C6","difficulty":2,"kind":"match","stem":"경제성장이 우리 생활에 미친 영향과 그 모습을 알맞게 이으세요.","pairs":[{"l":"첨단 기술","r":"물건을 생산하는 속도가 빨라지고 생산량이 늘었어요"},{"l":"문화 산업","r":"생활이 풍족해지면서 콘텐츠 산업이 발달했어요"},{"l":"교육","r":"디지털 기기로 수업하며 교육의 질이 높아졌어요"},{"l":"의료","r":"수준 높은 의료 혜택으로 기대 수명이 늘었어요"}],"mis":"SO6-2-u2-X13","explanation":["생산 속도는 첨단 기술이에요.","콘텐츠는 문화 산업이에요.","기대 수명은 의료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L05_basic#9','soc',6,2,'u2','L05','tb_g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C6',2,'mc','auto','82쪽 기사에서 2022년 우리나라 콘텐츠 산업 수출액은 얼마인가요?',ARRAY['SO6-2-u2-X13']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C6","difficulty":2,"kind":"mc","stem":"82쪽 기사에서 2022년 우리나라 콘텐츠 산업 수출액은 얼마인가요?","options":[{"t":"132.4억 달러","correct":true},{"t":"119.2억 달러","mis":"SO6-2-u2-X13"},{"t":"13.7억 달러","mis":"SO6-2-u2-X13"}],"explanation":["2022년 값을 찾아요.","119.2억 달러는 2020년이에요.","132.4억 달러예요."],"asset":{"type":"passage","lines":["콘텐츠 산업 — 게임, 영화, 방송, 출판, 만화, 음악, 애니메이션, 광고, 캐릭터","2022년 수출액 132.4억 달러 — 전년보다 6.3 % 늘어 역대 최대","같은 기간 전기차, 가전제품 같은 주요 품목의 수출액보다 많았다.","콘텐츠 수출이 늘면 화장품, 식품 수출도 함께 늘었다.","수출액(억 달러) — 2006년 13.7 · 2010년 31.9 · 2014년 52.7","수출액(억 달러) — 2018년 96.2 · 2020년 119.2 · 2022년 132.4"],"numbered":false,"title":"『사회』 82쪽 신문 기사 「콘텐츠 산업 수출액 역대 최대」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L05_basic#10','soc',6,2,'u2','L05','tb_g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C5',3,'essay','teacher','80쪽 글을 보고 우리나라 경제성장 과정을 시대 순서대로 세 가지 이상 쓰고, 빠르게 성장할 수 있었던 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u2-C5","difficulty":3,"kind":"essay","stem":"80쪽 글을 보고 우리나라 경제성장 과정을 시대 순서대로 세 가지 이상 쓰고, 빠르게 성장할 수 있었던 까닭을 쓰세요.","answer_guide":{"answer":"예: 1960년대 경공업 제품 수출 → 1970년대 중화학 공업 발달 → 1988년 서울 올림픽 대회 → 1996년 OECD 가입. 가계와 기업, 정부가 함께 노력했기 때문이에요.","scoring_points":["시대 순서가 바른가","세 가지 이상 썼는가","가계·기업·정부의 노력을 까닭으로 썼는가"]},"explanation":["글에서 연도를 찾아요.","차례대로 써요.","함께한 노력을 써요."],"asset":{"type":"passage","lines":["(간추림) 우리나라는 세계에서 손꼽힐 만큼 빠른 경제성장을 이루었다.","6·25 전쟁으로 산업 시설이 폐허가 되고 자본·자원도 거의 없었다.","세계는 이 성장을 「한강의 기적」이라고 불렀다.","1960년대 경제 개발 5개년 계획 — 경공업 제품 수출","1970년대 — 중화학 공업이 발달하며 빠르게 성장","1988년 제24회 서울 올림픽 대회 · 1996년 12월 OECD에 29번째로 가입","오늘날 — 휴대 전화·반도체·자동차·화학·철강, 음악·게임·웹툰"],"numbered":false,"title":"『사회』 80쪽 누리집 글 「한국 경제, 기적을 만들다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L05_challenge#1','soc',6,2,'u2','L05','tb_g6_2_soc_u2_L05_challenge','lesson_challenge','SO6-2-u2-C5',2,'error','auto','우리나라 경제성장 과정에 대한 설명 가운데 잘못된 것을 고르세요.',ARRAY['SO6-2-u2-X11']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C5","difficulty":2,"kind":"error","stem":"우리나라 경제성장 과정에 대한 설명 가운데 잘못된 것을 고르세요.","options":[{"t":"1960년대부터 반도체와 웹툰을 주로 수출했어요","correct":true,"mis_target":"SO6-2-u2-X11"},{"t":"1970년대부터 중화학 공업이 발달했어요","mis":"SO6-2-u2-X11"},{"t":"1996년 12월 OECD에 29번째로 가입했어요","mis":"SO6-2-u2-X11"}],"explanation":["1960년대는 경공업이에요.","반도체·웹툰은 오늘날이에요.","1960년대 반도체·웹툰은 잘못이에요."],"asset":{"type":"passage","lines":["(간추림) 우리나라는 세계에서 손꼽힐 만큼 빠른 경제성장을 이루었다.","6·25 전쟁으로 산업 시설이 폐허가 되고 자본·자원도 거의 없었다.","세계는 이 성장을 「한강의 기적」이라고 불렀다.","1960년대 경제 개발 5개년 계획 — 경공업 제품 수출","1970년대 — 중화학 공업이 발달하며 빠르게 성장","1988년 제24회 서울 올림픽 대회 · 1996년 12월 OECD에 29번째로 가입","오늘날 — 휴대 전화·반도체·자동차·화학·철강, 음악·게임·웹툰"],"numbered":false,"title":"『사회』 80쪽 누리집 글 「한국 경제, 기적을 만들다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L05_challenge#2','soc',6,2,'u2','L05','tb_g6_2_soc_u2_L05_challenge','lesson_challenge','SO6-2-u2-C6',2,'mc','auto','83쪽 자료에서 2022년 우리나라의 기대 수명은 몇 세인가요?',ARRAY['SO6-2-u2-X13']::text[],true,'{"seq":2,"concept":"SO6-2-u2-C6","difficulty":2,"kind":"mc","stem":"83쪽 자료에서 2022년 우리나라의 기대 수명은 몇 세인가요?","options":[{"t":"82.7세","correct":true},{"t":"62.3세","mis":"SO6-2-u2-X13"},{"t":"76.0세","mis":"SO6-2-u2-X13"}],"explanation":["2022년 값이에요.","62.3세는 1970년이에요.","82.7세예요."],"asset":{"type":"passage","lines":["우리나라 기대 수명 — 1970년 62.3세 · 1980년 66.1세 · 1990년 71.7세","우리나라 기대 수명 — 2000년 76.0세 · 2010년 80.2세 · 2022년 82.7세","에듀 테크 시장 — 2022년 7.8조 원 · 2024년 9.2조 원 · 2026년 10.8조 원(전망)"],"title":"『사회』 83쪽 — 교육과 의료의 변화(그래프를 글로)"},"variant_rule":{"alt":[{"stem":"83쪽 자료에서 1970년 우리나라의 기대 수명은 몇 세인가요?","options":[{"t":"62.3세","correct":true},{"t":"82.7세","mis":"SO6-2-u2-X13"},{"t":"71.7세","mis":"SO6-2-u2-X13"}],"explanation":["1970년 값이에요.","82.7세는 2022년이에요.","62.3세예요."],"asset":{"type":"passage","lines":["우리나라 기대 수명 — 1970년 62.3세 · 1980년 66.1세 · 1990년 71.7세","우리나라 기대 수명 — 2000년 76.0세 · 2010년 80.2세 · 2022년 82.7세","에듀 테크 시장 — 2022년 7.8조 원 · 2024년 9.2조 원 · 2026년 10.8조 원(전망)"],"title":"『사회』 83쪽 — 교육과 의료의 변화(그래프를 글로)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L05_challenge#3','soc',6,2,'u2','L05','tb_g6_2_soc_u2_L05_challenge','lesson_challenge','SO6-2-u2-C5',3,'mc','auto','79쪽 자료에서 1980년 이후 두 나라의 1인당 국민 총소득은 어떻게 변했나요?',ARRAY['SO6-2-u2-X11']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C5","difficulty":3,"kind":"mc","stem":"79쪽 자료에서 1980년 이후 두 나라의 1인당 국민 총소득은 어떻게 변했나요?","options":[{"t":"우리나라가 빠르게 늘어 ○○ 나라와 차이가 크게 벌어졌어요","correct":true},{"t":"두 나라의 차이가 점점 줄었어요","mis":"SO6-2-u2-X11"},{"t":"○○ 나라가 우리나라를 앞질렀어요","mis":"SO6-2-u2-X11"}],"explanation":["1980년 1,870과 770이에요.","2023년 35,490과 4,230이에요.","차이가 크게 벌어졌어요."],"asset":{"type":"passage","lines":["연도 — 1960 · 1970 · 1980 · 1990 · 2000 · 2010 · 2023","우리나라 — 120 · 280 · 1,870 · 6,450 · 11,030 · 22,290 · 35,490","○○ 나라 — 230 · 240 · 770 · 830 · 1,180 · 2,360 · 4,230","(단위: 달러 · 꺾은선그래프를 글로 옮김)"],"numbered":false,"title":"『사회』 79쪽 — 1인당 국민 총소득 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L05_challenge#4','soc',6,2,'u2','L05','tb_g6_2_soc_u2_L05_challenge','lesson_challenge','SO6-2-u2-C5',3,'sa','auto','79쪽 자료에서 2023년 우리나라의 1인당 국민 총소득은 ○○ 나라보다 몇 달러 더 많은가요?','{}'::text[],false,'{"seq":4,"concept":"SO6-2-u2-C5","difficulty":3,"kind":"sa","stem":"79쪽 자료에서 2023년 우리나라의 1인당 국민 총소득은 ○○ 나라보다 몇 달러 더 많은가요?","answer":["31,260달러","31260달러","31,260","31260"],"explanation":["35,490에서 4,230을 빼요.","받아내림에 주의해요.","31,260달러예요."],"asset":{"type":"passage","lines":["연도 — 1960 · 1970 · 1980 · 1990 · 2000 · 2010 · 2023","우리나라 — 120 · 280 · 1,870 · 6,450 · 11,030 · 22,290 · 35,490","○○ 나라 — 230 · 240 · 770 · 830 · 1,180 · 2,360 · 4,230","(단위: 달러 · 꺾은선그래프를 글로 옮김)"],"numbered":false,"title":"『사회』 79쪽 — 1인당 국민 총소득 변화"},"mis":"SO6-2-u2-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L05_challenge#5','soc',6,2,'u2','L05','tb_g6_2_soc_u2_L05_challenge','lesson_challenge','SO6-2-u2-C5',3,'ox','auto','경제성장은 빠를수록 좋은 것이고, 느리게 성장하는 나라는 잘못하고 있는 거예요.',ARRAY['SO6-2-u2-X24']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C5","difficulty":3,"kind":"ox","stem":"경제성장은 빠를수록 좋은 것이고, 느리게 성장하는 나라는 잘못하고 있는 거예요.","answer":"X","reason_options":[{"t":"나라마다 성장 속도가 다르고, 빠른 성장에는 여러 문제도 따르기 때문에","correct":true},{"t":"빠르게 성장한 나라만 생활이 나아지기 때문에","mis":"SO6-2-u2-X24"}],"mis":"SO6-2-u2-X24","explanation":["속도는 나라마다 달라요.","빠른 성장에도 문제가 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L05_challenge#6','soc',6,2,'u2','L05','tb_g6_2_soc_u2_L05_challenge','lesson_challenge','SO6-2-u2-C5',3,'mc','auto','1인당 국민 총소득의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u2-X10']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C5","difficulty":3,"kind":"mc","stem":"1인당 국민 총소득의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"한 나라의 국민이 일정 기간 생산 활동에 참여한 대가로 받은 소득의 합계를 인구수로 나눈 금액","correct":true},{"t":"나라 안 모든 기업의 이윤을 더한 금액","mis":"SO6-2-u2-X10"},{"t":"한 사람이 평생 버는 돈","mis":"SO6-2-u2-X10"}],"explanation":["79쪽 낱말 풀이예요.","소득의 합계를 인구수로 나눠요.","그 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L05_challenge#7','soc',6,2,'u2','L05','tb_g6_2_soc_u2_L05_challenge','lesson_challenge','SO6-2-u2-C6',3,'mc','auto','경제가 성장하면서 문화 산업이 발달한 까닭은 무엇인가요?',ARRAY['SO6-2-u2-X12','SO6-2-u2-X13']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C6","difficulty":3,"kind":"mc","stem":"경제가 성장하면서 문화 산업이 발달한 까닭은 무엇인가요?","options":[{"t":"일자리와 소득이 늘어 생활이 풍족해지면서 문화에 관한 관심이 높아져서","correct":true},{"t":"경제성장과 상관없이 저절로 발달해서","mis":"SO6-2-u2-X12"},{"t":"정치에 관한 관심만 높아져서","mis":"SO6-2-u2-X13"}],"explanation":["소득이 늘었어요.","생활이 풍족해졌어요.","문화에 관심이 높아졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L05_challenge#8','soc',6,2,'u2','L05','tb_g6_2_soc_u2_L05_challenge','lesson_challenge','SO6-2-u2-C6',4,'essay','teacher','82쪽 수출액 자료로 알 수 있는 점을 쓰고, 콘텐츠 산업이 더 발달하면 우리 경제가 어떻게 달라질지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u2-C6","difficulty":4,"kind":"essay","stem":"82쪽 수출액 자료로 알 수 있는 점을 쓰고, 콘텐츠 산업이 더 발달하면 우리 경제가 어떻게 달라질지 쓰세요.","answer_guide":{"answer":"예: 2006년 13.7억 달러에서 2022년 132.4억 달러로 크게 늘었어요. 콘텐츠 산업이 더 발달하면 관련 일자리가 늘고 화장품·식품 수출도 늘어 경제가 더 성장할 거예요.","scoring_points":["수출액 변화를 수로 썼는가","경제에 미칠 영향을 썼는가","기사 속 사실과 이어 썼는가"]},"explanation":["처음과 마지막 값을 견줘요.","앞으로를 생각해요.","근거를 들어요."],"asset":{"type":"passage","lines":["콘텐츠 산업 — 게임, 영화, 방송, 출판, 만화, 음악, 애니메이션, 광고, 캐릭터","2022년 수출액 132.4억 달러 — 전년보다 6.3 % 늘어 역대 최대","같은 기간 전기차, 가전제품 같은 주요 품목의 수출액보다 많았다.","콘텐츠 수출이 늘면 화장품, 식품 수출도 함께 늘었다.","수출액(억 달러) — 2006년 13.7 · 2010년 31.9 · 2014년 52.7","수출액(억 달러) — 2018년 96.2 · 2020년 119.2 · 2022년 132.4"],"numbered":false,"title":"『사회』 82쪽 신문 기사 「콘텐츠 산업 수출액 역대 최대」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L05_challenge#9','soc',6,2,'u2','L05','tb_g6_2_soc_u2_L05_challenge','lesson_challenge','SO6-2-u2-C5',4,'essay','teacher','연설문 (가)와 (나)의 수출 총액을 비교하고, 수출이 크게 늘어난 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u2-C5","difficulty":4,"kind":"essay","stem":"연설문 (가)와 (나)의 수출 총액을 비교하고, 수출이 크게 늘어난 까닭을 쓰세요.","answer_guide":{"answer":"예: (가)는 100억 달러, (나)는 6,300억 달러예요. 경제 개발 계획으로 중화학 공업을 키웠고, 오늘날에는 반도체 같은 첨단 산업과 문화 콘텐츠 수출이 늘었기 때문이에요.","scoring_points":["두 수출 총액을 바르게 썼는가","(가) 시기의 까닭을 썼는가","(나) 시기의 까닭을 썼는가"]},"explanation":["두 연설의 수를 찾아요.","산업이 어떻게 바뀌었나요?","까닭을 써요."],"asset":{"type":"passage","lines":["(가) 드디어 우리는 수출 100억 달러를 돌파했습니다.","(가) 1962년만 해도 수출 실적은 겨우 5천여만 달러, 대부분 농산물·광산물이었습니다.","(가) 중화학 공업은 선진국 수준으로 발전해 가고 있습니다.","(나) 올해 대한민국의 수출은 6,300억 달러를 돌파하여 사상 최대입니다.","(나) 메모리 반도체는 세계 1위, 조선·석유 화학도 크게 늘었습니다.","(나) 문화 콘텐츠 수출이 3년 연속 100억 달러를 넘었습니다."],"numbered":false,"title":"활동지 — 대통령 연설문 두 편(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L05_challenge#10','soc',6,2,'u2','L05','tb_g6_2_soc_u2_L05_challenge','lesson_challenge','SO6-2-u2-C6',4,'mc','auto','경제성장과 첨단 기술에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u2-X13','SO6-2-u2-X12']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C6","difficulty":4,"kind":"mc","stem":"경제성장과 첨단 기술에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"드론, 자율 주행, 생성형 인공지능 같은 첨단 기술로 생활이 편리해졌어요","correct":true},{"t":"첨단 기술이 발전하면 생산량이 줄어들어요","mis":"SO6-2-u2-X13"},{"t":"첨단 기술은 경제성장과 관계가 없어요","mis":"SO6-2-u2-X12"},{"t":"빅데이터 전문가는 데이터를 지우는 일을 해요","mis":"SO6-2-u2-X13"}],"explanation":["81쪽 사진이에요.","생산 속도와 양이 늘어요.","생활이 편리해졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L07_basic#1','soc',6,2,'u2','L07','tb_g6_2_soc_u2_L07_basic','lesson_basic','SO6-2-u2-C7',1,'mc','auto','86쪽에서 경제적으로 부유한 사람과 가난한 사람의 소득 차이가 커지는 문제를 무엇이라고 했나요?',ARRAY['SO6-2-u2-X14']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C7","difficulty":1,"kind":"mc","stem":"86쪽에서 경제적으로 부유한 사람과 가난한 사람의 소득 차이가 커지는 문제를 무엇이라고 했나요?","options":[{"t":"빈부 격차","correct":true},{"t":"과소비","mis":"SO6-2-u2-X14"},{"t":"노사 갈등","mis":"SO6-2-u2-X14"},{"t":"환경 문제","mis":"SO6-2-u2-X14"}],"explanation":["소득 차이예요.","부유함과 가난함의 차이예요.","빈부 격차예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L07_basic#2','soc',6,2,'u2','L07','tb_g6_2_soc_u2_L07_basic','lesson_basic','SO6-2-u2-C7',1,'blank','auto','꼭 기억해요: 자연의 무분별한 개발, 오염 물질과 쓰레기 증가로 (    )가 발생했어요. 빈칸에 알맞은 말은?',ARRAY['SO6-2-u2-X14']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C7","difficulty":1,"kind":"blank","stem":"꼭 기억해요: 자연의 무분별한 개발, 오염 물질과 쓰레기 증가로 (    )가 발생했어요. 빈칸에 알맞은 말은?","options":[{"t":"환경 문제","correct":true},{"t":"과소비 문제","mis":"SO6-2-u2-X14"},{"t":"노사 갈등","mis":"SO6-2-u2-X14"}],"explanation":["자연이 망가졌어요.","오염과 쓰레기예요.","환경 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L07_basic#3','soc',6,2,'u2','L07','tb_g6_2_soc_u2_L07_basic','lesson_basic','SO6-2-u2-C8',1,'sa','auto','공유하는 자원을 자신의 이익만 생각하며 사용하여 결과적으로 공동체 전체가 피해를 보게 되는 현상을 무엇이라고 하나요?','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u2-C8","difficulty":1,"kind":"sa","stem":"공유하는 자원을 자신의 이익만 생각하며 사용하여 결과적으로 공동체 전체가 피해를 보게 되는 현상을 무엇이라고 하나요?","answer":["공유지의 비극"],"explanation":["92쪽이에요.","함께 쓰는 자원이에요.","공유지의 비극이에요."],"mis":"SO6-2-u2-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L07_basic#4','soc',6,2,'u2','L07','tb_g6_2_soc_u2_L07_basic','lesson_basic','SO6-2-u2-C8',1,'ox','auto','빠른 경제성장으로 발생한 문제를 해결하려고 정부, 기업, 근로자, 시민 단체, 개인이 함께 노력해요.',ARRAY['SO6-2-u2-X15']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C8","difficulty":1,"kind":"ox","stem":"빠른 경제성장으로 발생한 문제를 해결하려고 정부, 기업, 근로자, 시민 단체, 개인이 함께 노력해요.","answer":"O","reason_options":[{"t":"91쪽처럼 여러 주체가 각자 자리에서 노력하기 때문에","correct":true},{"t":"정부 혼자만 노력하면 되기 때문에","mis":"SO6-2-u2-X15"}],"mis":"SO6-2-u2-X15","explanation":["꼭 기억해요 2예요.","모두 함께해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L07_basic#5','soc',6,2,'u2','L07','tb_g6_2_soc_u2_L07_basic','lesson_basic','SO6-2-u2-C7',2,'mc','auto','85쪽 기사에서 □□ 지역은 재활용 쓰레기 가운데 얼마 정도만 자원으로 활용하나요?',ARRAY['SO6-2-u2-X14']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C7","difficulty":2,"kind":"mc","stem":"85쪽 기사에서 □□ 지역은 재활용 쓰레기 가운데 얼마 정도만 자원으로 활용하나요?","options":[{"t":"55 % 정도","correct":true},{"t":"거의 전부","mis":"SO6-2-u2-X14"},{"t":"10 % 정도","mis":"SO6-2-u2-X14"}],"explanation":["기사의 수를 찾아요.","나머지는 태우거나 묻어요.","55 % 정도예요."],"asset":{"type":"passage","lines":["(간추림) □□ 지역에서 버린 비닐과 플라스틱이 일주일도 안 돼 처리장을 채웠다.","특히 배달 음식을 담는 플라스틱 쓰레기가 많이 늘었다.","재활용 쓰레기 가운데 55 % 정도만 자원으로 쓰고, 나머지는 태우거나 묻는다.","쓰레기를 줄이고 자원 낭비를 막을 관심이 필요하다."],"numbered":false,"title":"『사회』 85쪽 뉴스 기사 「산처럼 쌓인 일회용품 쓰레기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L07_basic#6','soc',6,2,'u2','L07','tb_g6_2_soc_u2_L07_basic','lesson_basic','SO6-2-u2-C7',2,'mc','auto','86쪽 기사에서 말하는 상대적 빈곤율의 뜻은 무엇인가요?',ARRAY['SO6-2-u2-X14','SO6-2-u2-X10']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C7","difficulty":2,"kind":"mc","stem":"86쪽 기사에서 말하는 상대적 빈곤율의 뜻은 무엇인가요?","options":[{"t":"전체 인구 중 빈곤 위험에 처한 인구 비율","correct":true},{"t":"전체 인구 중 부자의 비율","mis":"SO6-2-u2-X14"},{"t":"한 해 동안 경제가 성장한 비율","mis":"SO6-2-u2-X10"}],"explanation":["기사에 뜻이 있어요.","빈곤 위험에 처한 사람이에요.","그 비율이에요."],"asset":{"type":"passage","lines":["(간추림) 1950년대 우리나라는 세계에서 손꼽히게 가난한 나라였다.","빠른 경제성장으로 세계 10위의 경제 대국이 되었고, 2021년 선진국으로 인정받았다.","하지만 OECD 국가 중 상대적 빈곤율이 높은 편이다.","상대적 빈곤율 = 전체 인구 중 빈곤 위험에 처한 인구 비율","2022년(%) 코스타리카 21.2 · 미국 18.1 · 이스라엘 16.8 · 대한민국 14.9","(이어서) 뉴질랜드 14.3 · 에스파냐 13.7 · 캐나다 11.9 · 영국 11.8","(이어서) 프랑스 8.3 · 노르웨이 8.0"],"numbered":false,"title":"『사회』 86쪽 신문 기사 「상대적 빈곤율 OECD 국가 중 높아 … 빈부 격차 심각」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L07_basic#7','soc',6,2,'u2','L07','tb_g6_2_soc_u2_L07_basic','lesson_basic','SO6-2-u2-C7',2,'mc','auto','86쪽 자료에서 2022년 대한민국의 상대적 빈곤율은 몇 %인가요?',ARRAY['SO6-2-u2-X14']::text[],true,'{"seq":7,"concept":"SO6-2-u2-C7","difficulty":2,"kind":"mc","stem":"86쪽 자료에서 2022년 대한민국의 상대적 빈곤율은 몇 %인가요?","options":[{"t":"14.9 %","correct":true},{"t":"21.2 %","mis":"SO6-2-u2-X14"},{"t":"8.0 %","mis":"SO6-2-u2-X14"},{"t":"18.1 %","mis":"SO6-2-u2-X14"}],"explanation":["대한민국 값을 찾아요.","21.2 %는 코스타리카예요.","14.9 %예요."],"asset":{"type":"passage","lines":["(간추림) 1950년대 우리나라는 세계에서 손꼽히게 가난한 나라였다.","빠른 경제성장으로 세계 10위의 경제 대국이 되었고, 2021년 선진국으로 인정받았다.","하지만 OECD 국가 중 상대적 빈곤율이 높은 편이다.","상대적 빈곤율 = 전체 인구 중 빈곤 위험에 처한 인구 비율","2022년(%) 코스타리카 21.2 · 미국 18.1 · 이스라엘 16.8 · 대한민국 14.9","(이어서) 뉴질랜드 14.3 · 에스파냐 13.7 · 캐나다 11.9 · 영국 11.8","(이어서) 프랑스 8.3 · 노르웨이 8.0"],"numbered":false,"title":"『사회』 86쪽 신문 기사 「상대적 빈곤율 OECD 국가 중 높아 … 빈부 격차 심각」"},"variant_rule":{"alt":[{"stem":"86쪽 자료에서 상대적 빈곤율이 가장 높은 나라는 어디인가요?","options":[{"t":"코스타리카","correct":true},{"t":"대한민국","mis":"SO6-2-u2-X14"},{"t":"노르웨이","mis":"SO6-2-u2-X14"},{"t":"미국","mis":"SO6-2-u2-X14"}],"explanation":["가장 큰 값을 찾아요.","21.2 %예요.","코스타리카예요."],"asset":{"type":"passage","lines":["(간추림) 1950년대 우리나라는 세계에서 손꼽히게 가난한 나라였다.","빠른 경제성장으로 세계 10위의 경제 대국이 되었고, 2021년 선진국으로 인정받았다.","하지만 OECD 국가 중 상대적 빈곤율이 높은 편이다.","상대적 빈곤율 = 전체 인구 중 빈곤 위험에 처한 인구 비율","2022년(%) 코스타리카 21.2 · 미국 18.1 · 이스라엘 16.8 · 대한민국 14.9","(이어서) 뉴질랜드 14.3 · 에스파냐 13.7 · 캐나다 11.9 · 영국 11.8","(이어서) 프랑스 8.3 · 노르웨이 8.0"],"numbered":false,"title":"『사회』 86쪽 신문 기사 「상대적 빈곤율 OECD 국가 중 높아 … 빈부 격차 심각」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L07_basic#8','soc',6,2,'u2','L07','tb_g6_2_soc_u2_L07_basic','lesson_basic','SO6-2-u2-C7',2,'match','auto','기사 제목과 그 기사가 다루는 문제를 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u2-C7","difficulty":2,"kind":"match","stem":"기사 제목과 그 기사가 다루는 문제를 알맞게 이으세요.","pairs":[{"l":"버려지는 옷 10만 톤… 태우고 묻고","r":"과소비와 자원 낭비"},{"l":"임금 인상 놓고 산업계 노사 갈등","r":"저임금과 노사 갈등"},{"l":"산처럼 쌓인 일회용품 쓰레기","r":"환경 문제"},{"l":"상대적 빈곤율 OECD 국가 중 높아","r":"빈부 격차"}],"mis":"SO6-2-u2-X14","explanation":["옷을 버리는 것은 자원 낭비예요.","임금 다툼은 노사 갈등이에요.","빈곤율은 빈부 격차예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L07_basic#9','soc',6,2,'u2','L07','tb_g6_2_soc_u2_L07_basic','lesson_basic','SO6-2-u2-C8',2,'mc','auto','91쪽에서 서로 소통하며 더 나은 근로 환경을 만들려고 노력하는 것은 누구인가요?',ARRAY['SO6-2-u2-X15']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C8","difficulty":2,"kind":"mc","stem":"91쪽에서 서로 소통하며 더 나은 근로 환경을 만들려고 노력하는 것은 누구인가요?","options":[{"t":"기업과 근로자","correct":true},{"t":"정부만","mis":"SO6-2-u2-X15"},{"t":"시민 단체만","mis":"SO6-2-u2-X15"}],"explanation":["노사 갈등을 푸는 노력이에요.","노사는 기업과 근로자예요.","기업과 근로자예요."],"asset":{"type":"passage","lines":["정부 — 다양한 제도와 정책을 만들어요(더 나은 일자리를 제공하려는 노력).","기업과 근로자 — 서로 소통하며 더 나은 근로 환경을 만들어요(노사 갈등을 풀려는 노력).","시민 단체와 개인 — 해변의 쓰레기를 주워 환경을 보호하고, 에너지를 절약해요."],"title":"『사회』 91쪽 — 빠른 경제성장으로 발생한 문제를 해결하려는 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L07_basic#10','soc',6,2,'u2','L07','tb_g6_2_soc_u2_L07_basic','lesson_basic','SO6-2-u2-C7',3,'essay','teacher','빈부 격차가 커지면 어떤 문제가 생기는지 쓰고, 빈부 격차가 줄어들면 우리 생활이 어떻게 달라질지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u2-C7","difficulty":3,"kind":"essay","stem":"빈부 격차가 커지면 어떤 문제가 생기는지 쓰고, 빈부 격차가 줄어들면 우리 생활이 어떻게 달라질지 쓰세요.","answer_guide":{"answer":"예: 소득이 낮은 사람은 점점 더 살기 어려워져 사람들 사이에 갈등이 커지고 사회가 불안정해져요. 빈부 격차가 줄면 갈등이 줄어 사회가 안정되고 경제가 성장할 수 있어요.","scoring_points":["커질 때의 문제를 썼는가","줄어들 때의 변화를 썼는가","갈등·안정과 이어 썼는가"]},"explanation":["커지면 어떻게 될까요?","줄면 어떻게 될까요?","둘 다 써요."],"asset":{"type":"passage","lines":["(간추림) 1950년대 우리나라는 세계에서 손꼽히게 가난한 나라였다.","빠른 경제성장으로 세계 10위의 경제 대국이 되었고, 2021년 선진국으로 인정받았다.","하지만 OECD 국가 중 상대적 빈곤율이 높은 편이다.","상대적 빈곤율 = 전체 인구 중 빈곤 위험에 처한 인구 비율","2022년(%) 코스타리카 21.2 · 미국 18.1 · 이스라엘 16.8 · 대한민국 14.9","(이어서) 뉴질랜드 14.3 · 에스파냐 13.7 · 캐나다 11.9 · 영국 11.8","(이어서) 프랑스 8.3 · 노르웨이 8.0"],"numbered":false,"title":"『사회』 86쪽 신문 기사 「상대적 빈곤율 OECD 국가 중 높아 … 빈부 격차 심각」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L07_challenge#1','soc',6,2,'u2','L07','tb_g6_2_soc_u2_L07_challenge','lesson_challenge','SO6-2-u2-C8',2,'error','auto','공유지의 비극에 대한 설명 가운데 잘못된 것을 고르세요.',ARRAY['SO6-2-u2-X16']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C8","difficulty":2,"kind":"error","stem":"공유지의 비극에 대한 설명 가운데 잘못된 것을 고르세요.","options":[{"t":"공유지의 비극은 모두가 자원을 아껴 써서 생기는 일이에요","correct":true,"mis_target":"SO6-2-u2-X16"},{"t":"지하자원, 공기, 땅, 물은 모두 함께 사용해야 하는 자원이에요","mis":"SO6-2-u2-X16"},{"t":"자원을 소중히 여기고 공동의 이익을 추구하는 태도가 필요해요","mis":"SO6-2-u2-X16"}],"explanation":["자기 이익만 생각해서 생겨요.","아껴 쓰면 생기지 않아요.","아껴 써서 생긴다는 말이 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L07_challenge#2','soc',6,2,'u2','L07','tb_g6_2_soc_u2_L07_challenge','lesson_challenge','SO6-2-u2-C7',2,'mc','auto','87쪽에서 필요한 것보다 더 많은 돈을 쓰는 문제를 가리키는 낱말은 무엇인가요?',ARRAY['SO6-2-u2-X14']::text[],true,'{"seq":2,"concept":"SO6-2-u2-C7","difficulty":2,"kind":"mc","stem":"87쪽에서 필요한 것보다 더 많은 돈을 쓰는 문제를 가리키는 낱말은 무엇인가요?","options":[{"t":"과소비","correct":true},{"t":"자원 낭비","mis":"SO6-2-u2-X14"},{"t":"빈부 격차","mis":"SO6-2-u2-X14"}],"explanation":["돈을 지나치게 써요.","87쪽이에요.","과소비예요."],"variant_rule":{"alt":[{"stem":"물건이나 서비스를 함부로 헤프게 쓰는 것을 무엇이라고 하나요?","options":[{"t":"자원 낭비","correct":true},{"t":"과소비","mis":"SO6-2-u2-X14"},{"t":"노사 갈등","mis":"SO6-2-u2-X14"}],"explanation":["헤프게 써요.","87쪽이에요.","자원 낭비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L07_challenge#3','soc',6,2,'u2','L07','tb_g6_2_soc_u2_L07_challenge','lesson_challenge','SO6-2-u2-C8',3,'mc','auto','92쪽 공동 어장에서 물고기가 하나도 남지 않게 된 까닭은 무엇인가요?',ARRAY['SO6-2-u2-X16']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C8","difficulty":3,"kind":"mc","stem":"92쪽 공동 어장에서 물고기가 하나도 남지 않게 된 까닭은 무엇인가요?","options":[{"t":"사람들이 자기 이익만 생각해 정한 횟수보다 더 많이 잡아서","correct":true},{"t":"모두 일주일에 두 번씩만 잡아서","mis":"SO6-2-u2-X16"},{"t":"물고기를 잡는 규칙이 너무 엄격해서","mis":"SO6-2-u2-X16"}],"explanation":["두 번씩이면 지속돼요.","세 번, 남들 따라 더 잡았어요.","자기 이익만 생각해서예요."],"asset":{"type":"passage","lines":["◊◊ 마을에는 공동 어장이 있어요.","마을 사람들이 각각 일주일에 두 번씩 잡으면 물고기가 사라지지 않고 계속 잡을 수 있어요.","「나는 세 번 나가면 물고기를 더 많이 잡을 수 있겠지?」","「이미 두 번 잡았지만, 남들이 잡을 때 나만 안 잡으면 손해잖아?」","몇 달 뒤 물고기가 하나도 남지 않게 됐어요."],"title":"『사회』 92쪽 풍덩! 사회 속으로 — 공동 어장 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L07_challenge#4','soc',6,2,'u2','L07','tb_g6_2_soc_u2_L07_challenge','lesson_challenge','SO6-2-u2-C8',3,'mc','auto','90쪽 평가표에서 합계 점수가 가장 높은 방안은 무엇인가요?',ARRAY['SO6-2-u2-X15']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C8","difficulty":3,"kind":"mc","stem":"90쪽 평가표에서 합계 점수가 가장 높은 방안은 무엇인가요?","options":[{"t":"방안 ㉰","correct":true},{"t":"방안 ㉮","mis":"SO6-2-u2-X15"},{"t":"방안 ㉯","mis":"SO6-2-u2-X15"}],"explanation":["기준별 점수를 더해요.","㉮ 12점, ㉯ 8점, ㉰ 19점이에요.","방안 ㉰예요."],"asset":{"type":"passage","lines":["방안 ㉮ 시민 단체를 만들어 무분별한 개발 감시하기","방안 ㉯ 개발할 수 있는 자원량을 법으로 정하기","방안 ㉰ 환경 문제의 심각성을 알리는 캠페인 벌이기","실천할 수 있나요? — ㉮ 1점 · ㉯ 1점 · ㉰ 5점","효과가 큰가요? — ㉮ 5점 · ㉯ 5점 · ㉰ 5점","비용이 적게 드나요? — ㉮ 3점 · ㉯ 1점 · ㉰ 5점","시간이 많이 필요하나요? — ㉮ 3점 · ㉯ 1점 · ㉰ 4점"],"title":"『사회』 90쪽 할 수 있어요 — 어느 모둠의 환경 문제 해결 방안 평가표(1~5점)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L07_challenge#5','soc',6,2,'u2','L07','tb_g6_2_soc_u2_L07_challenge','lesson_challenge','SO6-2-u2-C8',3,'sa','auto','90쪽 평가표에서 방안 ㉮의 합계는 몇 점인가요?','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u2-C8","difficulty":3,"kind":"sa","stem":"90쪽 평가표에서 방안 ㉮의 합계는 몇 점인가요?","answer":["12점","12"],"explanation":["1, 5, 3, 3을 더해요.","네 기준을 모두 더해요.","12점이에요."],"asset":{"type":"passage","lines":["방안 ㉮ 시민 단체를 만들어 무분별한 개발 감시하기","방안 ㉯ 개발할 수 있는 자원량을 법으로 정하기","방안 ㉰ 환경 문제의 심각성을 알리는 캠페인 벌이기","실천할 수 있나요? — ㉮ 1점 · ㉯ 1점 · ㉰ 5점","효과가 큰가요? — ㉮ 5점 · ㉯ 5점 · ㉰ 5점","비용이 적게 드나요? — ㉮ 3점 · ㉯ 1점 · ㉰ 5점","시간이 많이 필요하나요? — ㉮ 3점 · ㉯ 1점 · ㉰ 4점"],"title":"『사회』 90쪽 할 수 있어요 — 어느 모둠의 환경 문제 해결 방안 평가표(1~5점)"},"mis":"SO6-2-u2-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L07_challenge#6','soc',6,2,'u2','L07','tb_g6_2_soc_u2_L07_challenge','lesson_challenge','SO6-2-u2-C7',3,'ox','auto','우리나라는 선진국이 되었으니 빈부 격차 문제는 저절로 사라졌어요.',ARRAY['SO6-2-u2-X26']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C7","difficulty":3,"kind":"ox","stem":"우리나라는 선진국이 되었으니 빈부 격차 문제는 저절로 사라졌어요.","answer":"X","reason_options":[{"t":"경제 대국이 되었어도 상대적 빈곤율이 OECD 국가 중 높은 편이기 때문에","correct":true},{"t":"경제가 성장하면 모든 사람의 소득이 똑같아지기 때문에","mis":"SO6-2-u2-X26"}],"mis":"SO6-2-u2-X26","explanation":["86쪽 기사를 봐요.","빈곤율이 높은 편이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["(간추림) 1950년대 우리나라는 세계에서 손꼽히게 가난한 나라였다.","빠른 경제성장으로 세계 10위의 경제 대국이 되었고, 2021년 선진국으로 인정받았다.","하지만 OECD 국가 중 상대적 빈곤율이 높은 편이다.","상대적 빈곤율 = 전체 인구 중 빈곤 위험에 처한 인구 비율","2022년(%) 코스타리카 21.2 · 미국 18.1 · 이스라엘 16.8 · 대한민국 14.9","(이어서) 뉴질랜드 14.3 · 에스파냐 13.7 · 캐나다 11.9 · 영국 11.8","(이어서) 프랑스 8.3 · 노르웨이 8.0"],"numbered":false,"title":"『사회』 86쪽 신문 기사 「상대적 빈곤율 OECD 국가 중 높아 … 빈부 격차 심각」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L07_challenge#7','soc',6,2,'u2','L07','tb_g6_2_soc_u2_L07_challenge','lesson_challenge','SO6-2-u2-C7',3,'mc','auto','과소비와 자원 낭비 문제가 계속되면 어떻게 될까요?',ARRAY['SO6-2-u2-X12']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C7","difficulty":3,"kind":"mc","stem":"과소비와 자원 낭비 문제가 계속되면 어떻게 될까요?","options":[{"t":"빚을 지거나 자원이 고갈되어 경제가 계속 성장하기 어려워져요","correct":true},{"t":"경제가 더 빠르게 성장해요","mis":"SO6-2-u2-X12"},{"t":"환경에는 아무 영향이 없어요","mis":"SO6-2-u2-X12"}],"explanation":["돈과 자원이 바닥나요.","환경도 오염돼요.","성장하기 어려워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L07_challenge#8','soc',6,2,'u2','L07','tb_g6_2_soc_u2_L07_challenge','lesson_challenge','SO6-2-u2-C8',4,'essay','teacher','90쪽 평가표에서 「효과가 큰가요?」 기준 하나만으로는 방안을 고를 수 없는 까닭을 쓰고, 평가 기준을 여러 개 세우는 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u2-C8","difficulty":4,"kind":"essay","stem":"90쪽 평가표에서 「효과가 큰가요?」 기준 하나만으로는 방안을 고를 수 없는 까닭을 쓰고, 평가 기준을 여러 개 세우는 까닭을 쓰세요.","answer_guide":{"answer":"예: 세 방안 모두 효과가 5점이라 하나만으로는 차이가 없어요. 실천할 수 있는지, 비용과 시간은 어떤지 여러 기준으로 견주어야 가장 알맞은 방안을 고를 수 있어요.","scoring_points":["효과 점수가 모두 같음을 밝혔는가","다른 기준의 쓰임을 썼는가","여러 기준으로 견주는 까닭을 썼는가"]},"explanation":["효과 점수를 봐요.","다른 기준은 어떤가요?","까닭을 써요."],"asset":{"type":"passage","lines":["방안 ㉮ 시민 단체를 만들어 무분별한 개발 감시하기","방안 ㉯ 개발할 수 있는 자원량을 법으로 정하기","방안 ㉰ 환경 문제의 심각성을 알리는 캠페인 벌이기","실천할 수 있나요? — ㉮ 1점 · ㉯ 1점 · ㉰ 5점","효과가 큰가요? — ㉮ 5점 · ㉯ 5점 · ㉰ 5점","비용이 적게 드나요? — ㉮ 3점 · ㉯ 1점 · ㉰ 5점","시간이 많이 필요하나요? — ㉮ 3점 · ㉯ 1점 · ㉰ 4점"],"title":"『사회』 90쪽 할 수 있어요 — 어느 모둠의 환경 문제 해결 방안 평가표(1~5점)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L07_challenge#9','soc',6,2,'u2','L07','tb_g6_2_soc_u2_L07_challenge','lesson_challenge','SO6-2-u2-C8',4,'essay','teacher','92쪽 공동 어장 이야기와 같은 공유지의 비극을 막으려면 어떻게 해야 하는지 두 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u2-C8","difficulty":4,"kind":"essay","stem":"92쪽 공동 어장 이야기와 같은 공유지의 비극을 막으려면 어떻게 해야 하는지 두 가지 쓰세요.","answer_guide":{"answer":"예: 한 사람이 잡을 수 있는 횟수를 규칙으로 정하고 지키게 해요. 함께 쓰는 자원을 소중히 여기고 모두의 이익을 생각하는 태도를 가져요.","scoring_points":["규칙 같은 막는 방법을 썼는가","태도와 노력을 썼는가","두 가지를 썼는가"]},"explanation":["막는 방법이 있어요.","태도도 필요해요.","둘 다 써요."],"asset":{"type":"passage","lines":["◊◊ 마을에는 공동 어장이 있어요.","마을 사람들이 각각 일주일에 두 번씩 잡으면 물고기가 사라지지 않고 계속 잡을 수 있어요.","「나는 세 번 나가면 물고기를 더 많이 잡을 수 있겠지?」","「이미 두 번 잡았지만, 남들이 잡을 때 나만 안 잡으면 손해잖아?」","몇 달 뒤 물고기가 하나도 남지 않게 됐어요."],"title":"『사회』 92쪽 풍덩! 사회 속으로 — 공동 어장 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L07_challenge#10','soc',6,2,'u2','L07','tb_g6_2_soc_u2_L07_challenge','lesson_challenge','SO6-2-u2-C8',4,'mc','auto','90쪽 평가표를 보고 바르게 말한 것은 무엇인가요?',ARRAY['SO6-2-u2-X15']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C8","difficulty":4,"kind":"mc","stem":"90쪽 평가표를 보고 바르게 말한 것은 무엇인가요?","options":[{"t":"방안 ㉯는 효과는 크지만 실천하기 어렵고 비용이 많이 들어 합계가 가장 낮아요","correct":true},{"t":"방안 ㉮는 모든 기준에서 5점이에요","mis":"SO6-2-u2-X15"},{"t":"방안 ㉰는 효과가 가장 작아요","mis":"SO6-2-u2-X15"},{"t":"평가 기준은 하나만 세우는 것이 좋아요","mis":"SO6-2-u2-X15"}],"explanation":["㉯의 점수를 살펴요.","실천 1점, 비용 1점이에요.","그래서 합계가 가장 낮아요."],"asset":{"type":"passage","lines":["방안 ㉮ 시민 단체를 만들어 무분별한 개발 감시하기","방안 ㉯ 개발할 수 있는 자원량을 법으로 정하기","방안 ㉰ 환경 문제의 심각성을 알리는 캠페인 벌이기","실천할 수 있나요? — ㉮ 1점 · ㉯ 1점 · ㉰ 5점","효과가 큰가요? — ㉮ 5점 · ㉯ 5점 · ㉰ 5점","비용이 적게 드나요? — ㉮ 3점 · ㉯ 1점 · ㉰ 5점","시간이 많이 필요하나요? — ㉮ 3점 · ㉯ 1점 · ㉰ 4점"],"title":"『사회』 90쪽 할 수 있어요 — 어느 모둠의 환경 문제 해결 방안 평가표(1~5점)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L09_basic#1','soc',6,2,'u2','L09','tb_g6_2_soc_u2_L09_basic','lesson_basic','SO6-2-u2-C9',1,'mc','auto','96쪽에서 나라와 나라 사이에 물자나 서비스를 사고팔거나 교환하는 활동을 가리키는 낱말은 무엇인가요?',ARRAY['SO6-2-u2-X18']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"mc","stem":"96쪽에서 나라와 나라 사이에 물자나 서비스를 사고팔거나 교환하는 활동을 가리키는 낱말은 무엇인가요?","options":[{"t":"무역","correct":true},{"t":"저축","mis":"SO6-2-u2-X18"},{"t":"소비","mis":"SO6-2-u2-X18"},{"t":"생산","mis":"SO6-2-u2-X18"}],"explanation":["나라와 나라 사이예요.","사고팔거나 교환해요.","무역이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L09_basic#2','soc',6,2,'u2','L09','tb_g6_2_soc_u2_L09_basic','lesson_basic','SO6-2-u2-C9',1,'ox','auto','다른 나라에서 물자나 서비스를 사 오는 것을 수출이라고 해요.',ARRAY['SO6-2-u2-X17']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"ox","stem":"다른 나라에서 물자나 서비스를 사 오는 것을 수출이라고 해요.","answer":"X","reason_options":[{"t":"사 오는 것은 수입이고, 다른 나라에 파는 것이 수출이기 때문에","correct":true},{"t":"물자가 나라 밖에서 움직이면 모두 수출이기 때문에","mis":"SO6-2-u2-X17"}],"mis":"SO6-2-u2-X17","explanation":["꼭 기억해요 2예요.","사 오면 수입이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L09_basic#3','soc',6,2,'u2','L09','tb_g6_2_soc_u2_L09_basic','lesson_basic','SO6-2-u2-C9',1,'sa','auto','다른 나라에 물자나 서비스를 파는 것을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"sa","stem":"다른 나라에 물자나 서비스를 파는 것을 두 글자로 쓰세요.","answer":["수출"],"explanation":["파는 쪽이에요.","96쪽이에요.","수출이에요."],"mis":"SO6-2-u2-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L09_basic#4','soc',6,2,'u2','L09','tb_g6_2_soc_u2_L09_basic','lesson_basic','SO6-2-u2-C9',1,'mc','auto','94쪽 교실 물건 가운데 오스트레일리아에서 캐낸 철로 만든 것은 무엇인가요?',ARRAY['SO6-2-u2-X18']::text[],true,'{"seq":4,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"mc","stem":"94쪽 교실 물건 가운데 오스트레일리아에서 캐낸 철로 만든 것은 무엇인가요?","options":[{"t":"의자","correct":true},{"t":"출입문","mis":"SO6-2-u2-X18"},{"t":"책꽂이","mis":"SO6-2-u2-X18"},{"t":"옷","mis":"SO6-2-u2-X18"}],"explanation":["오스트레일리아를 찾아요.","철로 만들었어요.","의자예요."],"asset":{"type":"passage","lines":["인도네시아에서 자란 나무로 만든 출입문","중국에서 만든 연필","사우디아라비아에서 생산한 원유로 만든 플라스틱 책꽂이","미국에서 만든 프로그램을 사용하는 태블릿","오스트레일리아에서 캐낸 철로 만든 의자","베트남에서 만든 옷"],"title":"『사회』 94쪽 생각을 열어요 — 교실 속 물건과 재료"},"variant_rule":{"alt":[{"stem":"94쪽 교실 물건 가운데 사우디아라비아에서 생산한 원유로 만든 것은 무엇인가요?","options":[{"t":"플라스틱 책꽂이","correct":true},{"t":"출입문","mis":"SO6-2-u2-X18"},{"t":"의자","mis":"SO6-2-u2-X18"},{"t":"연필","mis":"SO6-2-u2-X18"}],"explanation":["사우디아라비아를 찾아요.","원유로 플라스틱을 만들어요.","플라스틱 책꽂이예요."],"asset":{"type":"passage","lines":["인도네시아에서 자란 나무로 만든 출입문","중국에서 만든 연필","사우디아라비아에서 생산한 원유로 만든 플라스틱 책꽂이","미국에서 만든 프로그램을 사용하는 태블릿","오스트레일리아에서 캐낸 철로 만든 의자","베트남에서 만든 옷"],"title":"『사회』 94쪽 생각을 열어요 — 교실 속 물건과 재료"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L09_basic#5','soc',6,2,'u2','L09','tb_g6_2_soc_u2_L09_basic','lesson_basic','SO6-2-u2-C9',2,'mc','auto','95쪽 벽란도에서 다른 나라 상인들이 고려에서 사 간 물건은 무엇인가요?',ARRAY['SO6-2-u2-X17']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"mc","stem":"95쪽 벽란도에서 다른 나라 상인들이 고려에서 사 간 물건은 무엇인가요?","options":[{"t":"삼베, 모시, 인삼, 종이","correct":true},{"t":"비단, 약재, 서적","mis":"SO6-2-u2-X17"},{"t":"악기, 보석","mis":"SO6-2-u2-X17"}],"explanation":["사 간 것과 판 것을 나눠요.","비단·약재는 가져와 판 것이에요.","삼베, 모시, 인삼, 종이예요."],"asset":{"type":"passage","lines":["고려의 수도 개경 근처에 벽란도라는 큰 항구가 있었어요.","송나라 상인부터 멀리 아라비아 상인까지 드나들었어요.","다른 나라 상인들은 비단, 약재, 서적, 악기, 보석 등을 가져와 팔았어요.","고려에서 삼베, 모시, 인삼, 종이 등을 사 갔어요."],"title":"『사회』 95쪽 — 고려 시대 벽란도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L09_basic#6','soc',6,2,'u2','L09','tb_g6_2_soc_u2_L09_basic','lesson_basic','SO6-2-u2-C9',2,'mc','auto','96쪽 기사 제목 가운데 수출과 관련된 것은 무엇인가요?',ARRAY['SO6-2-u2-X17']::text[],true,'{"seq":6,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"mc","stem":"96쪽 기사 제목 가운데 수출과 관련된 것은 무엇인가요?","options":[{"t":"㉣ 국내 떡볶이 수출 길 활짝","correct":true},{"t":"㉠ 수입 학용품, 안전 확인 필수","mis":"SO6-2-u2-X17"},{"t":"㉡ 어린이 입맛 맞춘 수입 과자 인기","mis":"SO6-2-u2-X17"}],"explanation":["파는 쪽을 찾아요.","떡볶이를 다른 나라에 팔아요.","㉣이에요."],"asset":{"type":"passage","lines":["㉠ 수입 학용품, 안전 확인 필수","㉡ 어린이 입맛 맞춘 수입 과자 인기","㉢ 수출품 실은 컨테이너 55개, 중앙아시아 도착","㉣ 국내 떡볶이 수출 길 활짝","㉤ 드라마, 예능 수출로 한국 널리 알린다"],"numbered":false,"title":"『사회』 96쪽 친구와 활동 — 무역 뉴스 기사 제목"},"variant_rule":{"alt":[{"stem":"96쪽 기사 제목 가운데 서비스를 수출한 것은 무엇인가요?","options":[{"t":"㉤ 드라마, 예능 수출로 한국 널리 알린다","correct":true},{"t":"㉢ 수출품 실은 컨테이너 55개, 중앙아시아 도착","mis":"SO6-2-u2-X18"},{"t":"㉠ 수입 학용품, 안전 확인 필수","mis":"SO6-2-u2-X17"}],"explanation":["손에 잡히지 않는 것을 찾아요.","드라마·예능은 서비스예요.","㉤이에요."],"asset":{"type":"passage","lines":["㉠ 수입 학용품, 안전 확인 필수","㉡ 어린이 입맛 맞춘 수입 과자 인기","㉢ 수출품 실은 컨테이너 55개, 중앙아시아 도착","㉣ 국내 떡볶이 수출 길 활짝","㉤ 드라마, 예능 수출로 한국 널리 알린다"],"numbered":false,"title":"『사회』 96쪽 친구와 활동 — 무역 뉴스 기사 제목"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L09_basic#7','soc',6,2,'u2','L09','tb_g6_2_soc_u2_L09_basic','lesson_basic','SO6-2-u2-C9',2,'mc','auto','97쪽처럼 한 나라가 천연가스를 생산할 수 없다면 어떤 문제가 생길까요?',ARRAY['SO6-2-u2-X18','SO6-2-u2-X22']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"mc","stem":"97쪽처럼 한 나라가 천연가스를 생산할 수 없다면 어떤 문제가 생길까요?","options":[{"t":"난방을 하거나 차량을 운행하기 어려워져요","correct":true},{"t":"비행기를 만들 수 없게 돼요","mis":"SO6-2-u2-X18"},{"t":"아무 문제도 생기지 않아요","mis":"SO6-2-u2-X22"}],"explanation":["천연가스의 쓰임을 봐요.","난방과 차량 연료예요.","그래서 어려워져요."],"asset":{"type":"passage","lines":["비행기를 만드는 데는 수준 높은 기술이 필요해 일부 국가에서만 만들 수 있어요.","천연가스는 난방이나 차량 연료로 쓰이는데, 매장된 곳이 많지 않아 일부 국가에서만 생산해요."],"title":"『사회』 97쪽 스스로 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L09_basic#8','soc',6,2,'u2','L09','tb_g6_2_soc_u2_L09_basic','lesson_basic','SO6-2-u2-C9',2,'mc','auto','98쪽 ㉮ 나라가 생산하여 수출할 때 더 유리한 상품은 무엇인가요?',ARRAY['SO6-2-u2-X22','SO6-2-u2-X18']::text[],true,'{"seq":8,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"mc","stem":"98쪽 ㉮ 나라가 생산하여 수출할 때 더 유리한 상품은 무엇인가요?","options":[{"t":"옷","correct":true},{"t":"쌀","mis":"SO6-2-u2-X22"},{"t":"쌀과 옷 모두 수출하지 않아요","mis":"SO6-2-u2-X18"}],"explanation":["㉮ 나라는 기술 수준이 높아요.","옷에서 더 큰 이익을 얻어요.","옷이에요."],"asset":{"type":"passage","lines":["㉮ 나라와 ㉯ 나라는 모두 쌀과 옷을 생산할 수 있어요.","㉮ 나라는 ㉯ 나라보다 같은 시간과 비용으로 쌀과 옷을 모두 더 많이 생산해요.","㉮ 나라는 기술 수준이 높아 쌀보다 옷을 생산해 수출할 때 더 큰 이익을 얻어요.","㉯ 나라는 기술 수준은 낮지만 쌀을 재배하기에 알맞아 쌀을 수출할 때 더 큰 이익을 얻어요."],"numbered":false,"title":"『사회』 98쪽 친구와 활동 — ㉮ 나라와 ㉯ 나라"},"variant_rule":{"alt":[{"stem":"98쪽 ㉯ 나라가 생산하여 수출할 때 더 유리한 상품은 무엇인가요?","options":[{"t":"쌀","correct":true},{"t":"옷","mis":"SO6-2-u2-X22"},{"t":"쌀과 옷 모두 수입만 해요","mis":"SO6-2-u2-X22"}],"explanation":["㉯ 나라는 쌀 재배에 알맞아요.","쌀에서 더 큰 이익을 얻어요.","쌀이에요."],"asset":{"type":"passage","lines":["㉮ 나라와 ㉯ 나라는 모두 쌀과 옷을 생산할 수 있어요.","㉮ 나라는 ㉯ 나라보다 같은 시간과 비용으로 쌀과 옷을 모두 더 많이 생산해요.","㉮ 나라는 기술 수준이 높아 쌀보다 옷을 생산해 수출할 때 더 큰 이익을 얻어요.","㉯ 나라는 기술 수준은 낮지만 쌀을 재배하기에 알맞아 쌀을 수출할 때 더 큰 이익을 얻어요."],"numbered":false,"title":"『사회』 98쪽 친구와 활동 — ㉮ 나라와 ㉯ 나라"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L09_basic#9','soc',6,2,'u2','L09','tb_g6_2_soc_u2_L09_basic','lesson_basic','SO6-2-u2-C9',2,'blank','auto','꼭 기억해요: 각 나라가 효율적으로 생산하는 상품을 (    )하고, 효율적으로 생산하기 어려운 상품을 수입하면 더 우수한 품질의 상품을 저렴하게 쓸 수 있어요. 빈칸에 알맞은 말은?',ARRAY['SO6-2-u2-X17','SO6-2-u2-X18']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"blank","stem":"꼭 기억해요: 각 나라가 효율적으로 생산하는 상품을 (    )하고, 효율적으로 생산하기 어려운 상품을 수입하면 더 우수한 품질의 상품을 저렴하게 쓸 수 있어요. 빈칸에 알맞은 말은?","options":[{"t":"수출","correct":true},{"t":"수입","mis":"SO6-2-u2-X17"},{"t":"생산 중단","mis":"SO6-2-u2-X18"}],"explanation":["잘 만드는 상품이에요.","다른 나라에 팔아요.","수출이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L09_basic#10','soc',6,2,'u2','L09','tb_g6_2_soc_u2_L09_basic','lesson_basic','SO6-2-u2-C9',3,'essay','teacher','무역이 이루어지는 까닭을 「자연환경」, 「자원」, 「기술」 가운데 두 낱말 이상을 넣어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u2-C9","difficulty":3,"kind":"essay","stem":"무역이 이루어지는 까닭을 「자연환경」, 「자원」, 「기술」 가운데 두 낱말 이상을 넣어 쓰세요.","answer_guide":{"answer":"예: 나라마다 자연환경, 자원, 자본, 기술이 달라 더 효율적으로 생산할 수 있는 물자가 다르기 때문이에요. 잘 만드는 것은 수출하고 부족한 것은 수입해 이익을 얻어요.","scoring_points":["나라마다 조건이 다름을 썼는가","낱말을 두 개 이상 넣었는가","수출과 수입으로 이익을 얻음을 썼는가"]},"explanation":["나라마다 무엇이 다른가요?","낱말을 넣어요.","수출과 수입을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L09_challenge#1','soc',6,2,'u2','L09','tb_g6_2_soc_u2_L09_challenge','lesson_challenge','SO6-2-u2-C9',2,'error','auto','무역에 대한 설명 가운데 잘못된 것을 고르세요.',ARRAY['SO6-2-u2-X22','SO6-2-u2-X18']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"error","stem":"무역에 대한 설명 가운데 잘못된 것을 고르세요.","options":[{"t":"나라 안에서 구할 수 있는 물자는 다른 나라에서 수입하지 않아요","correct":true,"mis_target":"SO6-2-u2-X22"},{"t":"드라마 같은 서비스도 다른 나라에 수출해요","mis":"SO6-2-u2-X18"},{"t":"고려 시대 벽란도에서도 무역이 이루어졌어요","mis":"SO6-2-u2-X18"}],"explanation":["99쪽 꼭 기억해요 1이에요.","구할 수 있어도 수입하기도 해요.","수입하지 않는다는 말이 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L09_challenge#2','soc',6,2,'u2','L09','tb_g6_2_soc_u2_L09_challenge','lesson_challenge','SO6-2-u2-C9',2,'sa','auto','신드바드가 인도에서 온갖 향신료를 사들인 일은 신드바드 쪽에서 보면 수출과 수입 가운데 무엇인가요?','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"sa","stem":"신드바드가 인도에서 온갖 향신료를 사들인 일은 신드바드 쪽에서 보면 수출과 수입 가운데 무엇인가요?","answer":["수입"],"explanation":["사들였어요.","사 오면 수입이에요.","수입이에요."],"asset":{"type":"passage","lines":["바그다드 상인 신드바드는 태양 나라 사람들이 안장 없이 말을 타는 것을 봤어요.","신드바드는 안장을 만들어 왕에게 바쳤고, 사람들이 너도나도 주문했어요.","신드바드는 안장을 만들어 팔아 큰돈을 벌었어요.","그 뒤 인도에서 온갖 향신료를 사들여 돈을 벌었어요."],"title":"활동지 — 신드바드 이야기(간추림)"},"mis":"SO6-2-u2-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L09_challenge#3','soc',6,2,'u2','L09','tb_g6_2_soc_u2_L09_challenge','lesson_challenge','SO6-2-u2-C9',3,'mc','auto','98쪽 ㉮ 나라는 쌀과 옷을 모두 더 많이 생산할 수 있어요. 그런데도 두 나라가 무역하면 좋은 까닭은 무엇인가요?',ARRAY['SO6-2-u2-X22','SO6-2-u2-X18']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C9","difficulty":3,"kind":"mc","stem":"98쪽 ㉮ 나라는 쌀과 옷을 모두 더 많이 생산할 수 있어요. 그런데도 두 나라가 무역하면 좋은 까닭은 무엇인가요?","options":[{"t":"각 나라가 더 큰 이익을 얻는 상품에 집중하면 두 나라 모두 더 풍족해지기 때문이에요","correct":true},{"t":"모든 것을 더 잘 만드는 나라는 무역할 필요가 없기 때문이에요","mis":"SO6-2-u2-X22"},{"t":"㉯ 나라가 쌀을 공짜로 주기 때문이에요","mis":"SO6-2-u2-X18"}],"explanation":["㉮ 나라는 옷에 집중해요.","㉯ 나라는 쌀에 집중해요.","서로 바꾸면 모두 더 풍족해요."],"asset":{"type":"passage","lines":["㉮ 나라와 ㉯ 나라는 모두 쌀과 옷을 생산할 수 있어요.","㉮ 나라는 ㉯ 나라보다 같은 시간과 비용으로 쌀과 옷을 모두 더 많이 생산해요.","㉮ 나라는 기술 수준이 높아 쌀보다 옷을 생산해 수출할 때 더 큰 이익을 얻어요.","㉯ 나라는 기술 수준은 낮지만 쌀을 재배하기에 알맞아 쌀을 수출할 때 더 큰 이익을 얻어요."],"numbered":false,"title":"『사회』 98쪽 친구와 활동 — ㉮ 나라와 ㉯ 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L09_challenge#4','soc',6,2,'u2','L09','tb_g6_2_soc_u2_L09_challenge','lesson_challenge','SO6-2-u2-C9',3,'mc','auto','99쪽에서 우리나라가 흑연을 거의 생산하지 않게 된 까닭은 무엇인가요?',ARRAY['SO6-2-u2-X18','SO6-2-u2-X19']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C9","difficulty":3,"kind":"mc","stem":"99쪽에서 우리나라가 흑연을 거의 생산하지 않게 된 까닭은 무엇인가요?","options":[{"t":"다른 나라에서 저렴한 가격의 흑연을 수입하게 되어서","correct":true},{"t":"흑연이 쓸모없는 자원이 되어서","mis":"SO6-2-u2-X18"},{"t":"처음부터 흑연이 전혀 없어서","mis":"SO6-2-u2-X19"}],"explanation":["과거엔 세계적인 생산국이었어요.","더 싼 흑연을 수입했어요.","그래서 거의 생산하지 않아요."],"asset":{"type":"passage","lines":["흑연은 연필뿐만 아니라 스마트폰, 배터리의 원료로 쓰이는 자원이에요.","과거 우리나라는 세계적인 흑연 생산국이었어요.","다른 나라에서 저렴한 흑연을 수입하면서 우리나라에서는 거의 생산하지 않게 됐어요.","우리나라는 수입한 흑연으로 전기차 배터리를 만들어 수출해요.","흑연을 생산하는 나라는 이 배터리를 단 전기차를 수입하기도 해요."],"title":"『사회』 99쪽 — 흑연과 전기차 배터리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L09_challenge#5','soc',6,2,'u2','L09','tb_g6_2_soc_u2_L09_challenge','lesson_challenge','SO6-2-u2-C9',3,'ox','auto','한 나라 안에서 구할 수 있는 물자나 서비스도 다른 나라에서 수입하기도 해요.',ARRAY['SO6-2-u2-X22']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C9","difficulty":3,"kind":"ox","stem":"한 나라 안에서 구할 수 있는 물자나 서비스도 다른 나라에서 수입하기도 해요.","answer":"O","reason_options":[{"t":"더 좋은 품질이나 더 값싼 물자를 다른 나라에서 구할 수 있기 때문에","correct":true},{"t":"수입은 나라 안에 전혀 없는 물자만 하기 때문에","mis":"SO6-2-u2-X22"}],"mis":"SO6-2-u2-X22","explanation":["99쪽 꼭 기억해요 1이에요.","더 좋고 값싼 것을 사 와요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L09_challenge#6','soc',6,2,'u2','L09','tb_g6_2_soc_u2_L09_challenge','lesson_challenge','SO6-2-u2-C9',3,'mc','auto','99쪽 흑연과 전기차 배터리 이야기를 바르게 정리한 것은 무엇인가요?',ARRAY['SO6-2-u2-X17','SO6-2-u2-X18']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C9","difficulty":3,"kind":"mc","stem":"99쪽 흑연과 전기차 배터리 이야기를 바르게 정리한 것은 무엇인가요?","options":[{"t":"흑연을 수입해 배터리를 만들어 수출하고, 흑연 생산국은 그 배터리를 단 전기차를 수입해요","correct":true},{"t":"우리나라는 흑연을 수출하고 배터리를 수입해요","mis":"SO6-2-u2-X17"},{"t":"흑연 생산국과 우리나라는 아무것도 사고팔지 않아요","mis":"SO6-2-u2-X18"}],"explanation":["흑연은 사 와요.","배터리는 팔아요.","서로 사고팔아요."],"asset":{"type":"passage","lines":["흑연은 연필뿐만 아니라 스마트폰, 배터리의 원료로 쓰이는 자원이에요.","과거 우리나라는 세계적인 흑연 생산국이었어요.","다른 나라에서 저렴한 흑연을 수입하면서 우리나라에서는 거의 생산하지 않게 됐어요.","우리나라는 수입한 흑연으로 전기차 배터리를 만들어 수출해요.","흑연을 생산하는 나라는 이 배터리를 단 전기차를 수입하기도 해요."],"title":"『사회』 99쪽 — 흑연과 전기차 배터리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L09_challenge#7','soc',6,2,'u2','L09','tb_g6_2_soc_u2_L09_challenge','lesson_challenge','SO6-2-u2-C9',3,'mc','auto','활동지 이야기에서 신드바드가 태양 나라에 안장을 만들어 판 것은 무엇인가요?',ARRAY['SO6-2-u2-X17','SO6-2-u2-X18']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C9","difficulty":3,"kind":"mc","stem":"활동지 이야기에서 신드바드가 태양 나라에 안장을 만들어 판 것은 무엇인가요?","options":[{"t":"수출","correct":true},{"t":"수입","mis":"SO6-2-u2-X17"},{"t":"저축","mis":"SO6-2-u2-X18"}],"explanation":["태양 나라에 팔았어요.","파는 쪽이에요.","수출이에요."],"asset":{"type":"passage","lines":["바그다드 상인 신드바드는 태양 나라 사람들이 안장 없이 말을 타는 것을 봤어요.","신드바드는 안장을 만들어 왕에게 바쳤고, 사람들이 너도나도 주문했어요.","신드바드는 안장을 만들어 팔아 큰돈을 벌었어요.","그 뒤 인도에서 온갖 향신료를 사들여 돈을 벌었어요."],"title":"활동지 — 신드바드 이야기(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L09_challenge#8','soc',6,2,'u2','L09','tb_g6_2_soc_u2_L09_challenge','lesson_challenge','SO6-2-u2-C9',4,'essay','teacher','활동지 무역 놀이에서 각자 가진 글자 카드로 더 많은 상품 카드(사과·기차·게임·아연)를 만들려면 어떤 규칙을 더하면 좋을지 쓰고, 무역이 이루어지는 까닭을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u2-C9","difficulty":4,"kind":"essay","stem":"활동지 무역 놀이에서 각자 가진 글자 카드로 더 많은 상품 카드(사과·기차·게임·아연)를 만들려면 어떤 규칙을 더하면 좋을지 쓰고, 무역이 이루어지는 까닭을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 남은 글자 카드를 친구들끼리 자유롭게 바꿀 수 있게 해요. 무역은 서로 가진 자원이나 기술, 처한 환경이 다르기 때문에 이루어져요.","scoring_points":["카드를 바꾸는 규칙을 썼는가","놀이와 무역을 이었는가","까닭을 한 문장으로 썼는가"]},"explanation":["남은 카드를 어떻게 쓸까요?","바꾸면 어떻게 되나요?","무역과 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L09_challenge#9','soc',6,2,'u2','L09','tb_g6_2_soc_u2_L09_challenge','lesson_challenge','SO6-2-u2-C9',4,'essay','teacher','98쪽 ㉮ 나라와 ㉯ 나라가 각각 무엇을 수출하면 좋을지 까닭과 함께 쓰고, 그렇게 무역하면 얻는 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u2-C9","difficulty":4,"kind":"essay","stem":"98쪽 ㉮ 나라와 ㉯ 나라가 각각 무엇을 수출하면 좋을지 까닭과 함께 쓰고, 그렇게 무역하면 얻는 좋은 점을 쓰세요.","answer_guide":{"answer":"예: ㉮ 나라는 기술 수준이 높아 옷을, ㉯ 나라는 쌀 재배에 알맞아 쌀을 수출해요. 서로 잘하는 상품에 집중해 바꾸면 두 나라 모두 더 풍족해져요.","scoring_points":["㉮ 나라의 상품과 까닭을 썼는가","㉯ 나라의 상품과 까닭을 썼는가","좋은 점을 썼는가"]},"explanation":["각 나라의 조건을 봐요.","수출할 상품을 정해요.","좋은 점을 써요."],"asset":{"type":"passage","lines":["㉮ 나라와 ㉯ 나라는 모두 쌀과 옷을 생산할 수 있어요.","㉮ 나라는 ㉯ 나라보다 같은 시간과 비용으로 쌀과 옷을 모두 더 많이 생산해요.","㉮ 나라는 기술 수준이 높아 쌀보다 옷을 생산해 수출할 때 더 큰 이익을 얻어요.","㉯ 나라는 기술 수준은 낮지만 쌀을 재배하기에 알맞아 쌀을 수출할 때 더 큰 이익을 얻어요."],"numbered":false,"title":"『사회』 98쪽 친구와 활동 — ㉮ 나라와 ㉯ 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L09_challenge#10','soc',6,2,'u2','L09','tb_g6_2_soc_u2_L09_challenge','lesson_challenge','SO6-2-u2-C9',4,'mc','auto','95쪽 벽란도에서 일어난 일이 가장 잘 드러나는 제목은 무엇인가요?',ARRAY['SO6-2-u2-X18','SO6-2-u2-X17']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C9","difficulty":4,"kind":"mc","stem":"95쪽 벽란도에서 일어난 일이 가장 잘 드러나는 제목은 무엇인가요?","options":[{"t":"여러 나라 상인들이 귀한 물건을 사고파는 벽란도","correct":true},{"t":"고려 사람들끼리만 장을 보는 벽란도","mis":"SO6-2-u2-X18"},{"t":"물건을 만들기만 하는 벽란도","mis":"SO6-2-u2-X18"},{"t":"다른 나라 상인이 사기만 하는 벽란도","mis":"SO6-2-u2-X17"}],"explanation":["여러 나라 상인이 모여요.","팔기도 사기도 해요.","그 제목이에요."],"asset":{"type":"passage","lines":["고려의 수도 개경 근처에 벽란도라는 큰 항구가 있었어요.","송나라 상인부터 멀리 아라비아 상인까지 드나들었어요.","다른 나라 상인들은 비단, 약재, 서적, 악기, 보석 등을 가져와 팔았어요.","고려에서 삼베, 모시, 인삼, 종이 등을 사 갔어요."],"title":"『사회』 95쪽 — 고려 시대 벽란도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L11_basic#1','soc',6,2,'u2','L11','tb_g6_2_soc_u2_L11_basic','lesson_basic','SO6-2-u2-C10',1,'mc','auto','100쪽 자료에서 우리나라의 주요 수입품은 무엇인가요?',ARRAY['SO6-2-u2-X19']::text[],true,'{"seq":1,"concept":"SO6-2-u2-C10","difficulty":1,"kind":"mc","stem":"100쪽 자료에서 우리나라의 주요 수입품은 무엇인가요?","options":[{"t":"원유","correct":true},{"t":"반도체","mis":"SO6-2-u2-X19"},{"t":"자동차","mis":"SO6-2-u2-X19"},{"t":"무선 통신 기기","mis":"SO6-2-u2-X19"}],"explanation":["수입품 칸을 봐요.","반도체·자동차는 수출품이에요.","원유예요."],"asset":{"type":"passage","lines":["주요 수입품 — 원유 · 정밀 화학 원료 · 천연가스 · 석탄","주요 수출품 — 반도체 · 석유 제품 · 무선 통신 기기 · 자동차","원유 — 불순물을 없애지 않은 자연 상태의 석유","석유 제품 — 원유의 혼합물을 분리해 만든 휘발유, 경유 같은 연료 제품","정밀 화학 원료 — 비료, 의약품, 배터리 등을 만드는 데 필요한 기초 원료"],"title":"『사회』 100쪽 — 우리나라의 주요 수입품과 수출품"},"variant_rule":{"alt":[{"stem":"100쪽 자료에서 우리나라의 주요 수출품은 무엇인가요?","options":[{"t":"반도체","correct":true},{"t":"원유","mis":"SO6-2-u2-X19"},{"t":"석탄","mis":"SO6-2-u2-X19"},{"t":"천연가스","mis":"SO6-2-u2-X19"}],"explanation":["수출품 칸을 봐요.","원유·석탄은 수입품이에요.","반도체예요."],"asset":{"type":"passage","lines":["주요 수입품 — 원유 · 정밀 화학 원료 · 천연가스 · 석탄","주요 수출품 — 반도체 · 석유 제품 · 무선 통신 기기 · 자동차","원유 — 불순물을 없애지 않은 자연 상태의 석유","석유 제품 — 원유의 혼합물을 분리해 만든 휘발유, 경유 같은 연료 제품","정밀 화학 원료 — 비료, 의약품, 배터리 등을 만드는 데 필요한 기초 원료"],"title":"『사회』 100쪽 — 우리나라의 주요 수입품과 수출품"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L11_basic#2','soc',6,2,'u2','L11','tb_g6_2_soc_u2_L11_basic','lesson_basic','SO6-2-u2-C10',1,'ox','auto','세계 여러 나라는 자연환경, 발달한 기술, 지리적 위치 등 각 나라의 특징에 따른 무역이 발달했어요.',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C10","difficulty":1,"kind":"ox","stem":"세계 여러 나라는 자연환경, 발달한 기술, 지리적 위치 등 각 나라의 특징에 따른 무역이 발달했어요.","answer":"O","reason_options":[{"t":"나라마다 가진 조건이 달라 무역하는 모습도 다르기 때문에","correct":true},{"t":"모든 나라가 똑같은 물건만 수출하기 때문에","mis":"SO6-2-u2-X19"}],"mis":"SO6-2-u2-X19","explanation":["꼭 기억해요 2예요.","나라마다 특징이 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L11_basic#3','soc',6,2,'u2','L11','tb_g6_2_soc_u2_L11_basic','lesson_basic','SO6-2-u2-C10',1,'sa','auto','꼭 기억해요: 우리나라는 (ㅊㅇㅈㅇ)을 수입한 후 상품을 생산하여 수출하는 무역이 발달했어요. 낱말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u2-C10","difficulty":1,"kind":"sa","stem":"꼭 기억해요: 우리나라는 (ㅊㅇㅈㅇ)을 수입한 후 상품을 생산하여 수출하는 무역이 발달했어요. 낱말을 쓰세요.","answer":["천연자원","천연 자원"],"explanation":["초성은 ㅊㅇㅈㅇ이에요.","원유·천연가스예요.","천연자원이에요."],"mis":"SO6-2-u2-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L11_basic#4','soc',6,2,'u2','L11','tb_g6_2_soc_u2_L11_basic','lesson_basic','SO6-2-u2-C10',1,'blank','auto','원유에 들어 있는 여러 혼합물을 분리하여 만든 휘발유, 경유 같은 연료 제품을 (    )이라고 해요. 빈칸에 알맞은 말은?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C10","difficulty":1,"kind":"blank","stem":"원유에 들어 있는 여러 혼합물을 분리하여 만든 휘발유, 경유 같은 연료 제품을 (    )이라고 해요. 빈칸에 알맞은 말은?","options":[{"t":"석유 제품","correct":true},{"t":"원유","mis":"SO6-2-u2-X19"},{"t":"정밀 화학 원료","mis":"SO6-2-u2-X19"}],"explanation":["원유를 가공했어요.","휘발유·경유예요.","석유 제품이에요."],"asset":{"type":"passage","lines":["주요 수입품 — 원유 · 정밀 화학 원료 · 천연가스 · 석탄","주요 수출품 — 반도체 · 석유 제품 · 무선 통신 기기 · 자동차","원유 — 불순물을 없애지 않은 자연 상태의 석유","석유 제품 — 원유의 혼합물을 분리해 만든 휘발유, 경유 같은 연료 제품","정밀 화학 원료 — 비료, 의약품, 배터리 등을 만드는 데 필요한 기초 원료"],"title":"『사회』 100쪽 — 우리나라의 주요 수입품과 수출품"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L11_basic#5','soc',6,2,'u2','L11','tb_g6_2_soc_u2_L11_basic','lesson_basic','SO6-2-u2-C10',2,'mc','auto','103쪽 자료에서 쌀을 가장 많이 수출하는 나라는 어디인가요?',ARRAY['SO6-2-u2-X19']::text[],true,'{"seq":5,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"mc","stem":"103쪽 자료에서 쌀을 가장 많이 수출하는 나라는 어디인가요?","options":[{"t":"인도","correct":true},{"t":"타이","mis":"SO6-2-u2-X19"},{"t":"베트남","mis":"SO6-2-u2-X19"},{"t":"미국","mis":"SO6-2-u2-X19"}],"explanation":["가장 큰 비율을 찾아요.","40.5 %예요.","인도예요."],"asset":{"type":"passage","lines":["주요 쌀 수출국(%) — 인도 40.5 · 타이 15.3 · 베트남 13.5","(이어서) 파키스탄 6.5 · 미국 3.8 · 기타 20.4","주요 원유 수출국(하루 백만 배럴) — 사우디아라비아 7.3 · 러시아 5.3 · 캐나다 4.0","(이어서) 이라크 3.8 · 미국 3.5 · 아랍 에미리트 3.5","사진 — 독일이 수출하는 백신 · 일본이 수출하는 로봇 · 미국에서 수입한 온라인 동영상 서비스"],"numbered":false,"title":"『사회』 103쪽 — 세계 여러 나라의 무역 모습"},"variant_rule":{"alt":[{"stem":"103쪽 자료에서 원유를 하루에 가장 많이 수출하는 나라는 어디인가요?","options":[{"t":"사우디아라비아","correct":true},{"t":"러시아","mis":"SO6-2-u2-X19"},{"t":"캐나다","mis":"SO6-2-u2-X19"},{"t":"아랍 에미리트","mis":"SO6-2-u2-X19"}],"explanation":["가장 큰 값을 찾아요.","하루 7.3백만 배럴이에요.","사우디아라비아예요."],"asset":{"type":"passage","lines":["주요 쌀 수출국(%) — 인도 40.5 · 타이 15.3 · 베트남 13.5","(이어서) 파키스탄 6.5 · 미국 3.8 · 기타 20.4","주요 원유 수출국(하루 백만 배럴) — 사우디아라비아 7.3 · 러시아 5.3 · 캐나다 4.0","(이어서) 이라크 3.8 · 미국 3.5 · 아랍 에미리트 3.5","사진 — 독일이 수출하는 백신 · 일본이 수출하는 로봇 · 미국에서 수입한 온라인 동영상 서비스"],"numbered":false,"title":"『사회』 103쪽 — 세계 여러 나라의 무역 모습"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L11_basic#6','soc',6,2,'u2','L11','tb_g6_2_soc_u2_L11_basic','lesson_basic','SO6-2-u2-C10',2,'mc','auto','104쪽 싱가포르에 큰 항구가 발달할 수 있었던 까닭은 무엇인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"mc","stem":"104쪽 싱가포르에 큰 항구가 발달할 수 있었던 까닭은 무엇인가요?","options":[{"t":"유럽과 아시아를 잇는 항로에 자리 잡고 있어서","correct":true},{"t":"넓은 땅에서 농산물이 많이 나서","mis":"SO6-2-u2-X19"},{"t":"원유가 풍부해서","mis":"SO6-2-u2-X19"}],"explanation":["지리적 위치를 봐요.","항로의 길목이에요.","그래서 큰 항구가 발달했어요."],"asset":{"type":"passage","lines":["싱가포르는 서울보다 약간 넓은 나라로, 유럽과 아시아를 잇는 항로에 자리 잡고 있어요.","정부는 이곳을 지나는 선박이 머물 수 있도록 큰 항구를 만들었어요.","여러 나라에서 생산한 상품이 모였고, 이를 필요한 나라에 다시 파는 무역이 발달했어요.","무역과 관련한 여러 은행과 기업이 활동하며 더욱 무역하기 좋은 나라가 됐어요."],"title":"『사회』 104쪽 스스로 활동 — 싱가포르"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L11_basic#7','soc',6,2,'u2','L11','tb_g6_2_soc_u2_L11_basic','lesson_basic','SO6-2-u2-C10',2,'match','auto','103쪽 사진을 보고 나라와 그 나라가 수출하는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"match","stem":"103쪽 사진을 보고 나라와 그 나라가 수출하는 것을 알맞게 이으세요.","pairs":[{"l":"독일","r":"백신"},{"l":"일본","r":"로봇"},{"l":"미국","r":"온라인 동영상 서비스"}],"mis":"SO6-2-u2-X19","explanation":["독일은 백신이에요.","일본은 로봇이에요.","미국은 동영상 서비스예요."],"asset":{"type":"passage","lines":["주요 쌀 수출국(%) — 인도 40.5 · 타이 15.3 · 베트남 13.5","(이어서) 파키스탄 6.5 · 미국 3.8 · 기타 20.4","주요 원유 수출국(하루 백만 배럴) — 사우디아라비아 7.3 · 러시아 5.3 · 캐나다 4.0","(이어서) 이라크 3.8 · 미국 3.5 · 아랍 에미리트 3.5","사진 — 독일이 수출하는 백신 · 일본이 수출하는 로봇 · 미국에서 수입한 온라인 동영상 서비스"],"numbered":false,"title":"『사회』 103쪽 — 세계 여러 나라의 무역 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L11_basic#8','soc',6,2,'u2','L11','tb_g6_2_soc_u2_L11_basic','lesson_basic','SO6-2-u2-C10',2,'mc','auto','102쪽 뉴스 예시에서 2023년 우리나라 김이 가장 많이 수출된 나라는 어디인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"mc","stem":"102쪽 뉴스 예시에서 2023년 우리나라 김이 가장 많이 수출된 나라는 어디인가요?","options":[{"t":"타이","correct":true},{"t":"일본","mis":"SO6-2-u2-X19"},{"t":"미국","mis":"SO6-2-u2-X19"}],"explanation":["뉴스 내용을 봐요.","김 과자가 인기예요.","타이예요."],"asset":{"type":"passage","lines":["뉴스 제목 — K-김 수출 1위 시장은 ‘김 과자 큰손’인 이 나라","우리나라 김 수출액이 2023년 약 4,086억 원으로 역대 최고치를 기록했다.","우리나라 김이 가장 많이 수출된 나라는 타이이다.","타이에서 김 과자가 인기를 끌면서 김 수출량도 늘고 있다."],"title":"『사회』 102쪽 디지털+ 할 수 있어요 — 조사한 뉴스 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L11_basic#9','soc',6,2,'u2','L11','tb_g6_2_soc_u2_L11_basic','lesson_basic','SO6-2-u2-C10',2,'mc','auto','박람회의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u2-X18','SO6-2-u2-X19']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"mc","stem":"박람회의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"일정한 기간과 장소를 정해 놓고 다양한 물품을 전시하는 행사","correct":true},{"t":"물건을 만드는 공장","mis":"SO6-2-u2-X18"},{"t":"배가 지나다니는 바다 위의 길","mis":"SO6-2-u2-X19"}],"explanation":["105쪽이에요.","물품을 전시해요.","그 뜻이에요."],"asset":{"type":"passage","lines":["박람회 — 일정한 기간과 장소를 정해 놓고 다양한 물품을 전시하는 행사","판매자가 홍보관을 운영하고, 판매자와 소비자가 직접 묻고 답해요.","세계 가전 박람회 — 미국 라스베이거스","세계 문구 박람회 — 대한민국 서울","세계 완구 박람회 — 독일 뉘른베르크"],"title":"『사회』 105쪽 풍덩! 사회 속으로 — 박람회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L11_basic#10','soc',6,2,'u2','L11','tb_g6_2_soc_u2_L11_basic','lesson_basic','SO6-2-u2-C10',3,'essay','teacher','100~101쪽을 보고 우리나라 무역의 특징을 「수입」, 「수출」을 넣어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u2-C10","difficulty":3,"kind":"essay","stem":"100~101쪽을 보고 우리나라 무역의 특징을 「수입」, 「수출」을 넣어 쓰세요.","answer_guide":{"answer":"예: 우리나라는 천연자원이 부족해 원유, 천연가스 같은 자원을 수입하고, 발달한 기술로 반도체, 자동차 같은 상품을 만들어 수출해요.","scoring_points":["무엇을 수입하는지 썼는가","무엇을 수출하는지 썼는가","천연자원과 기술의 관계를 썼는가"]},"explanation":["수입품을 봐요.","수출품을 봐요.","둘을 이어요."],"asset":{"type":"passage","lines":["주요 수입품 — 원유 · 정밀 화학 원료 · 천연가스 · 석탄","주요 수출품 — 반도체 · 석유 제품 · 무선 통신 기기 · 자동차","원유 — 불순물을 없애지 않은 자연 상태의 석유","석유 제품 — 원유의 혼합물을 분리해 만든 휘발유, 경유 같은 연료 제품","정밀 화학 원료 — 비료, 의약품, 배터리 등을 만드는 데 필요한 기초 원료"],"title":"『사회』 100쪽 — 우리나라의 주요 수입품과 수출품"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L11_challenge#1','soc',6,2,'u2','L11','tb_g6_2_soc_u2_L11_challenge','lesson_challenge','SO6-2-u2-C10',2,'error','auto','우리나라 무역에 대한 설명 가운데 잘못된 것을 고르세요.',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"error","stem":"우리나라 무역에 대한 설명 가운데 잘못된 것을 고르세요.","options":[{"t":"우리나라는 원유, 천연가스 같은 천연자원을 주로 수출해요","correct":true,"mis_target":"SO6-2-u2-X19"},{"t":"우리나라는 반도체, 자동차 같은 제품을 주로 수출해요","mis":"SO6-2-u2-X19"},{"t":"우리나라는 땅이 넓지 않아 다양한 농산물을 충분히 생산하기 어려워요","mis":"SO6-2-u2-X19"}],"explanation":["천연자원은 부족해요.","그래서 수입해요.","천연자원을 수출한다는 말이 잘못이에요."],"asset":{"type":"passage","lines":["주요 수입품 — 원유 · 정밀 화학 원료 · 천연가스 · 석탄","주요 수출품 — 반도체 · 석유 제품 · 무선 통신 기기 · 자동차","원유 — 불순물을 없애지 않은 자연 상태의 석유","석유 제품 — 원유의 혼합물을 분리해 만든 휘발유, 경유 같은 연료 제품","정밀 화학 원료 — 비료, 의약품, 배터리 등을 만드는 데 필요한 기초 원료"],"title":"『사회』 100쪽 — 우리나라의 주요 수입품과 수출품"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L11_challenge#2','soc',6,2,'u2','L11','tb_g6_2_soc_u2_L11_challenge','lesson_challenge','SO6-2-u2-C10',2,'mc','auto','105쪽에서 세계 완구 박람회가 열리는 곳은 어디인가요?',ARRAY['SO6-2-u2-X19']::text[],true,'{"seq":2,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"mc","stem":"105쪽에서 세계 완구 박람회가 열리는 곳은 어디인가요?","options":[{"t":"독일 뉘른베르크","correct":true},{"t":"미국 라스베이거스","mis":"SO6-2-u2-X19"},{"t":"대한민국 서울","mis":"SO6-2-u2-X19"}],"explanation":["장난감 박람회예요.","독일이에요.","뉘른베르크예요."],"asset":{"type":"passage","lines":["박람회 — 일정한 기간과 장소를 정해 놓고 다양한 물품을 전시하는 행사","판매자가 홍보관을 운영하고, 판매자와 소비자가 직접 묻고 답해요.","세계 가전 박람회 — 미국 라스베이거스","세계 문구 박람회 — 대한민국 서울","세계 완구 박람회 — 독일 뉘른베르크"],"title":"『사회』 105쪽 풍덩! 사회 속으로 — 박람회"},"variant_rule":{"alt":[{"stem":"105쪽에서 그해 선보일 새로운 가전제품을 주제로 하는 박람회가 열리는 곳은 어디인가요?","options":[{"t":"미국 라스베이거스","correct":true},{"t":"독일 뉘른베르크","mis":"SO6-2-u2-X19"},{"t":"대한민국 서울","mis":"SO6-2-u2-X19"}],"explanation":["가전 박람회예요.","미국이에요.","라스베이거스예요."],"asset":{"type":"passage","lines":["박람회 — 일정한 기간과 장소를 정해 놓고 다양한 물품을 전시하는 행사","판매자가 홍보관을 운영하고, 판매자와 소비자가 직접 묻고 답해요.","세계 가전 박람회 — 미국 라스베이거스","세계 문구 박람회 — 대한민국 서울","세계 완구 박람회 — 독일 뉘른베르크"],"title":"『사회』 105쪽 풍덩! 사회 속으로 — 박람회"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L11_challenge#3','soc',6,2,'u2','L11','tb_g6_2_soc_u2_L11_challenge','lesson_challenge','SO6-2-u2-C10',3,'mc','auto','100쪽에서 원유는 주요 수입품, 석유 제품은 주요 수출품인 까닭은 무엇인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C10","difficulty":3,"kind":"mc","stem":"100쪽에서 원유는 주요 수입품, 석유 제품은 주요 수출품인 까닭은 무엇인가요?","options":[{"t":"원유를 수입해 기술로 휘발유, 경유 같은 석유 제품을 만들어 수출하기 때문이에요","correct":true},{"t":"원유와 석유 제품은 같은 물건이기 때문이에요","mis":"SO6-2-u2-X19"},{"t":"석유 제품은 땅에서 바로 캐내기 때문이에요","mis":"SO6-2-u2-X19"}],"explanation":["원유는 자연 상태예요.","분리해 석유 제품을 만들어요.","그래서 수입하고 다시 수출해요."],"asset":{"type":"passage","lines":["주요 수입품 — 원유 · 정밀 화학 원료 · 천연가스 · 석탄","주요 수출품 — 반도체 · 석유 제품 · 무선 통신 기기 · 자동차","원유 — 불순물을 없애지 않은 자연 상태의 석유","석유 제품 — 원유의 혼합물을 분리해 만든 휘발유, 경유 같은 연료 제품","정밀 화학 원료 — 비료, 의약품, 배터리 등을 만드는 데 필요한 기초 원료"],"title":"『사회』 100쪽 — 우리나라의 주요 수입품과 수출품"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L11_challenge#4','soc',6,2,'u2','L11','tb_g6_2_soc_u2_L11_challenge','lesson_challenge','SO6-2-u2-C10',3,'mc','auto','103쪽 쌀 수출국들의 위치에서 찾을 수 있는 공통점은 무엇인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C10","difficulty":3,"kind":"mc","stem":"103쪽 쌀 수출국들의 위치에서 찾을 수 있는 공통점은 무엇인가요?","options":[{"t":"미국을 빼면 주로 아시아 대륙에 있어요","correct":true},{"t":"모두 서아시아에 있어요","mis":"SO6-2-u2-X19"},{"t":"모두 원유를 많이 수출해요","mis":"SO6-2-u2-X19"}],"explanation":["인도·타이·베트남·파키스탄이에요.","미국만 아시아 밖이에요.","주로 아시아예요."],"asset":{"type":"passage","lines":["주요 쌀 수출국(%) — 인도 40.5 · 타이 15.3 · 베트남 13.5","(이어서) 파키스탄 6.5 · 미국 3.8 · 기타 20.4","주요 원유 수출국(하루 백만 배럴) — 사우디아라비아 7.3 · 러시아 5.3 · 캐나다 4.0","(이어서) 이라크 3.8 · 미국 3.5 · 아랍 에미리트 3.5","사진 — 독일이 수출하는 백신 · 일본이 수출하는 로봇 · 미국에서 수입한 온라인 동영상 서비스"],"numbered":false,"title":"『사회』 103쪽 — 세계 여러 나라의 무역 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L11_challenge#5','soc',6,2,'u2','L11','tb_g6_2_soc_u2_L11_challenge','lesson_challenge','SO6-2-u2-C10',3,'sa','auto','103쪽 자료에서 원유를 하루 5.3백만 배럴 수출하는 나라는 어디인가요?','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u2-C10","difficulty":3,"kind":"sa","stem":"103쪽 자료에서 원유를 하루 5.3백만 배럴 수출하는 나라는 어디인가요?","answer":["러시아"],"explanation":["5.3을 찾아요.","사우디아라비아 다음이에요.","러시아예요."],"asset":{"type":"passage","lines":["주요 쌀 수출국(%) — 인도 40.5 · 타이 15.3 · 베트남 13.5","(이어서) 파키스탄 6.5 · 미국 3.8 · 기타 20.4","주요 원유 수출국(하루 백만 배럴) — 사우디아라비아 7.3 · 러시아 5.3 · 캐나다 4.0","(이어서) 이라크 3.8 · 미국 3.5 · 아랍 에미리트 3.5","사진 — 독일이 수출하는 백신 · 일본이 수출하는 로봇 · 미국에서 수입한 온라인 동영상 서비스"],"numbered":false,"title":"『사회』 103쪽 — 세계 여러 나라의 무역 모습"},"mis":"SO6-2-u2-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L11_challenge#6','soc',6,2,'u2','L11','tb_g6_2_soc_u2_L11_challenge','lesson_challenge','SO6-2-u2-C10',3,'ox','auto','농산물이나 공산품을 직접 생산하지 않아도 무역이 이루어질 수 있어요.',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C10","difficulty":3,"kind":"ox","stem":"농산물이나 공산품을 직접 생산하지 않아도 무역이 이루어질 수 있어요.","answer":"O","reason_options":[{"t":"싱가포르처럼 다른 나라에서 생산한 상품을 모아 필요한 나라에 다시 팔기도 하기 때문에","correct":true},{"t":"무역은 자기 나라에서 만든 물건만 팔 수 있기 때문에","mis":"SO6-2-u2-X19"}],"mis":"SO6-2-u2-X19","explanation":["104쪽 싱가포르예요.","모아서 다시 팔아요.","그래서 O예요."],"asset":{"type":"passage","lines":["싱가포르는 서울보다 약간 넓은 나라로, 유럽과 아시아를 잇는 항로에 자리 잡고 있어요.","정부는 이곳을 지나는 선박이 머물 수 있도록 큰 항구를 만들었어요.","여러 나라에서 생산한 상품이 모였고, 이를 필요한 나라에 다시 파는 무역이 발달했어요.","무역과 관련한 여러 은행과 기업이 활동하며 더욱 무역하기 좋은 나라가 됐어요."],"title":"『사회』 104쪽 스스로 활동 — 싱가포르"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L11_challenge#7','soc',6,2,'u2','L11','tb_g6_2_soc_u2_L11_challenge','lesson_challenge','SO6-2-u2-C10',3,'mc','auto','활동지 기사 ①에서 우리나라 화장품 수출이 늘어난 까닭은 무엇인가요?',ARRAY['SO6-2-u2-X19','SO6-2-u2-X18']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C10","difficulty":3,"kind":"mc","stem":"활동지 기사 ①에서 우리나라 화장품 수출이 늘어난 까닭은 무엇인가요?","options":[{"t":"한류와 함께 K-뷰티에 관한 관심과 인기가 높아져서","correct":true},{"t":"화장품 원료인 원유가 우리나라에 풍부해서","mis":"SO6-2-u2-X19"},{"t":"다른 나라에서는 화장품을 만들 수 없어서","mis":"SO6-2-u2-X18"}],"explanation":["기사 ①을 봐요.","문화가 퍼졌어요.","한류와 K-뷰티 인기 때문이에요."],"asset":{"type":"passage","lines":["기사 ① 상반기 화장품 수출이 48억 2천만 달러로 사상 최대를 기록했다.","기사 ① 한류와 함께 K-뷰티에 관한 관심과 인기가 높아졌기 때문이다.","기사 ② 인도네시아는 가뭄으로 설탕이 부족해지자 브라질산 설탕을 수입하기로 했다.","기사 ② 주로 수입하던 가까운 인도와 타이도 날씨 탓에 생산량이 줄었기 때문이다."],"title":"활동지 — 두 신문 기사(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L11_challenge#8','soc',6,2,'u2','L11','tb_g6_2_soc_u2_L11_challenge','lesson_challenge','SO6-2-u2-C10',4,'essay','teacher','활동지 기사 ②에서 인도네시아가 브라질에서 설탕을 수입하기로 한 까닭을 쓰고, 이 기사로 새롭게 알게 된 무역의 모습을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u2-C10","difficulty":4,"kind":"essay","stem":"활동지 기사 ②에서 인도네시아가 브라질에서 설탕을 수입하기로 한 까닭을 쓰고, 이 기사로 새롭게 알게 된 무역의 모습을 쓰세요.","answer_guide":{"answer":"예: 가뭄으로 설탕이 부족한데 늘 수입하던 인도와 타이도 생산량이 줄었기 때문이에요. 기후변화 때문에 수입하는 나라를 가까운 나라에서 먼 나라로 바꾸기도 해요.","scoring_points":["수입하는 까닭을 썼는가","기존 수입국의 상황을 썼는가","알게 된 무역의 모습을 썼는가"]},"explanation":["왜 부족했나요?","원래 어디서 샀나요?","무엇을 알게 됐나요?"],"asset":{"type":"passage","lines":["기사 ① 상반기 화장품 수출이 48억 2천만 달러로 사상 최대를 기록했다.","기사 ① 한류와 함께 K-뷰티에 관한 관심과 인기가 높아졌기 때문이다.","기사 ② 인도네시아는 가뭄으로 설탕이 부족해지자 브라질산 설탕을 수입하기로 했다.","기사 ② 주로 수입하던 가까운 인도와 타이도 날씨 탓에 생산량이 줄었기 때문이다."],"title":"활동지 — 두 신문 기사(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L11_challenge#9','soc',6,2,'u2','L11','tb_g6_2_soc_u2_L11_challenge','lesson_challenge','SO6-2-u2-C10',4,'essay','teacher','103~104쪽에서 무역이 이루어지는 모습 가운데 두 가지를 골라, 그런 무역을 하는 나라와 그 나라의 특징을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u2-C10","difficulty":4,"kind":"essay","stem":"103~104쪽에서 무역이 이루어지는 모습 가운데 두 가지를 골라, 그런 무역을 하는 나라와 그 나라의 특징을 쓰세요.","answer_guide":{"answer":"예: 인도는 쌀을 많이 수출해요 — 쌀을 재배할 넓은 땅이 있어요. 싱가포르는 다른 나라 상품을 모아 다시 팔아요 — 유럽과 아시아를 잇는 항로에 있어요.","scoring_points":["무역 모습 두 가지를 골랐는가","나라를 바르게 들었는가","그 나라의 특징과 이었는가"]},"explanation":["두 갈래를 골라요.","나라를 찾아요.","특징과 이어요."],"asset":{"type":"passage","lines":["주요 쌀 수출국(%) — 인도 40.5 · 타이 15.3 · 베트남 13.5","(이어서) 파키스탄 6.5 · 미국 3.8 · 기타 20.4","주요 원유 수출국(하루 백만 배럴) — 사우디아라비아 7.3 · 러시아 5.3 · 캐나다 4.0","(이어서) 이라크 3.8 · 미국 3.5 · 아랍 에미리트 3.5","사진 — 독일이 수출하는 백신 · 일본이 수출하는 로봇 · 미국에서 수입한 온라인 동영상 서비스"],"numbered":false,"title":"『사회』 103쪽 — 세계 여러 나라의 무역 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L11_challenge#10','soc',6,2,'u2','L11','tb_g6_2_soc_u2_L11_challenge','lesson_challenge','SO6-2-u2-C10',4,'mc','auto','나라의 조건과 무역 모습이 알맞게 짝지어진 것은 무엇인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C10","difficulty":4,"kind":"mc","stem":"나라의 조건과 무역 모습이 알맞게 짝지어진 것은 무엇인가요?","options":[{"t":"넓은 땅과 알맞은 기후 — 쌀 같은 농산물을 수출해요","correct":true},{"t":"천연자원이 부족함 — 원유를 수출해요","mis":"SO6-2-u2-X19"},{"t":"항로의 길목 — 백신을 개발해 수출해요","mis":"SO6-2-u2-X19"},{"t":"뛰어난 로봇 기술 — 쌀을 수출해요","mis":"SO6-2-u2-X19"}],"explanation":["조건에 맞는 무역을 찾아요.","넓은 땅은 농산물이에요.","그 짝이 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L12_basic#1','soc',6,2,'u2','L12','tb_g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C11',1,'mc','auto','다른 나라에서 수입하는 상품에 부과하는 세금을 무엇이라고 하나요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C11","difficulty":1,"kind":"mc","stem":"다른 나라에서 수입하는 상품에 부과하는 세금을 무엇이라고 하나요?","options":[{"t":"관세","correct":true},{"t":"소득","mis":"SO6-2-u2-X20"},{"t":"이윤","mis":"SO6-2-u2-X20"},{"t":"급여","mis":"SO6-2-u2-X20"}],"explanation":["108쪽 낱말 풀이예요.","수입품에 매겨요.","관세예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L12_basic#2','soc',6,2,'u2','L12','tb_g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C11',1,'ox','auto','수입이 늘어나서 국내 기업이 피해를 입거나 관련 산업이 성장하기 어려울 수도 있어요.',ARRAY['SO6-2-u2-X23']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C11","difficulty":1,"kind":"ox","stem":"수입이 늘어나서 국내 기업이 피해를 입거나 관련 산업이 성장하기 어려울 수도 있어요.","answer":"O","reason_options":[{"t":"값싼 수입품과 경쟁하며 국내 기업의 상품이 덜 팔릴 수 있기 때문에","correct":true},{"t":"수입이 늘면 국내 기업은 언제나 이익을 보기 때문에","mis":"SO6-2-u2-X23"}],"mis":"SO6-2-u2-X23","explanation":["꼭 기억해요 2예요.","국내 산업이 어려워질 수 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L12_basic#3','soc',6,2,'u2','L12','tb_g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C11',1,'sa','auto','꼭 기억해요: 세계 여러 나라는 물자나 서비스를 수출하여 더 많은 이익을 얻으려고 서로 (ㄱㅈ)해요. 낱말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u2-C11","difficulty":1,"kind":"sa","stem":"꼭 기억해요: 세계 여러 나라는 물자나 서비스를 수출하여 더 많은 이익을 얻으려고 서로 (ㄱㅈ)해요. 낱말을 쓰세요.","answer":["경쟁"],"explanation":["초성은 ㄱㅈ이에요.","이익을 두고 다퉈요.","경쟁이에요."],"mis":"SO6-2-u2-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L12_basic#4','soc',6,2,'u2','L12','tb_g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C11',1,'mc','auto','106쪽 기사에서 인도네시아에 매장량이 풍부한 광물은 무엇인가요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C11","difficulty":1,"kind":"mc","stem":"106쪽 기사에서 인도네시아에 매장량이 풍부한 광물은 무엇인가요?","options":[{"t":"니켈, 주석","correct":true},{"t":"흑연, 원유","mis":"SO6-2-u2-X20"},{"t":"금, 은","mis":"SO6-2-u2-X20"}],"explanation":["기사의 광물을 찾아요.","두 가지예요.","니켈과 주석이에요."],"asset":{"type":"passage","lines":["(간추림) 우리나라와 인도네시아가 핵심 광물 공동 연구 센터를 운영하기로 했다.","인도네시아는 니켈, 주석 등 광물 매장량이 풍부한 나라이다.","우리나라는 인도네시아와 협력해 더 안정적으로 자원을 확보할 수 있다.","인도네시아는 우리나라의 뛰어난 광물 탐사 기술로 자원을 효율적으로 개발할 수 있다."],"numbered":false,"title":"『사회』 106쪽 신문 기사 「한국–인도네시아 핵심 광물 연구 개발 협력 가속화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L12_basic#5','soc',6,2,'u2','L12','tb_g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C11',2,'mc','auto','106쪽 기사에서 우리나라가 인도네시아와 협력해 얻는 이익은 무엇인가요?',ARRAY['SO6-2-u2-X07','SO6-2-u2-X20']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C11","difficulty":2,"kind":"mc","stem":"106쪽 기사에서 우리나라가 인도네시아와 협력해 얻는 이익은 무엇인가요?","options":[{"t":"더 안정적으로 자원을 확보할 수 있어요","correct":true},{"t":"광물 탐사 기술을 잃게 돼요","mis":"SO6-2-u2-X07"},{"t":"인도네시아와 경쟁만 하게 돼요","mis":"SO6-2-u2-X20"}],"explanation":["우리나라 쪽 이익이에요.","자원을 얻어요.","안정적인 자원 확보예요."],"asset":{"type":"passage","lines":["(간추림) 우리나라와 인도네시아가 핵심 광물 공동 연구 센터를 운영하기로 했다.","인도네시아는 니켈, 주석 등 광물 매장량이 풍부한 나라이다.","우리나라는 인도네시아와 협력해 더 안정적으로 자원을 확보할 수 있다.","인도네시아는 우리나라의 뛰어난 광물 탐사 기술로 자원을 효율적으로 개발할 수 있다."],"numbered":false,"title":"『사회』 106쪽 신문 기사 「한국–인도네시아 핵심 광물 연구 개발 협력 가속화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L12_basic#6','soc',6,2,'u2','L12','tb_g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C11',2,'match','auto','107쪽 경쟁의 분야와 사례를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-2-u2-C11","difficulty":2,"kind":"match","stem":"107쪽 경쟁의 분야와 사례를 알맞게 이으세요.","pairs":[{"l":"첨단 기술 개발","r":"더 나은 생성형 인공지능 제품을 만들어 수출하려 해요"},{"l":"다른 나라 시설 건설","r":"우리나라 기업이 인도의 다리를 지었어요"},{"l":"더 나은 무역 환경","r":"부산항에 자동화 항만 시스템을 갖췄어요"}],"mis":"SO6-2-u2-X20","explanation":["인공지능은 첨단 기술이에요.","다리는 시설 건설이에요.","항만은 무역 환경이에요."],"asset":{"type":"passage","lines":["① 첨단 기술 개발 — 생성형 인공지능 시장: 2023년 약 37억 달러","① (전망) 2026년 약 194억 달러 · 2028년 약 363억 달러","② 다른 나라에 필요한 시설 건설 — 우리나라 기업이 건설한 인도의 다리","③ 더 나은 무역 환경 — 자동화 항만 시스템을 갖춘 부산항"],"numbered":false,"title":"『사회』 107쪽 — 무역을 통한 세계 여러 나라의 경쟁"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L12_basic#7','soc',6,2,'u2','L12','tb_g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C11',2,'mc','auto','108쪽에서 1970년대 우리나라가 수입 철강 제품에 높은 관세를 부과한 까닭은 무엇인가요?',ARRAY['SO6-2-u2-X23','SO6-2-u2-X20']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C11","difficulty":2,"kind":"mc","stem":"108쪽에서 1970년대 우리나라가 수입 철강 제품에 높은 관세를 부과한 까닭은 무엇인가요?","options":[{"t":"국내에서 만든 철강 제품이 시장에서 더 높은 경쟁력을 갖추게 하려고","correct":true},{"t":"수입 철강 제품이 더 많이 팔리게 하려고","mis":"SO6-2-u2-X23"},{"t":"철강 산업을 그만두려고","mis":"SO6-2-u2-X20"}],"explanation":["국내 산업을 보호해요.","수입품 값이 올라가요.","국산 철강의 경쟁력을 높이려고요."],"asset":{"type":"passage","lines":["1970년대 우리나라는 제철소를 짓고 자체 기술로 철강 제품을 만들려고 노력했어요.","당시 우리나라는 수입 철강 제품에 높은 관세를 부과했어요.","그 결과 국내에서 생산한 철강 제품이 수입 철강 제품보다 더 높은 경쟁력을 갖췄어요.","오늘날 우리나라는 세계적인 철강 산업 국가로 성장했어요.","철강 제품은 건축, 자동차, 가전, 선박 등 다양한 산업의 기초 소재예요."],"numbered":false,"title":"『사회』 108쪽 스스로 활동 — 철강 제품과 관세"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L12_basic#8','soc',6,2,'u2','L12','tb_g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C11',2,'mc','auto','109쪽 기사에서 외국 기업이 베트남에서 생산 시설을 운영하는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u2-X23','SO6-2-u2-X20']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C11","difficulty":2,"kind":"mc","stem":"109쪽 기사에서 외국 기업이 베트남에서 생산 시설을 운영하는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"노동력이 저렴하고 중국에 물자를 쉽게 공급할 수 있어서","correct":true},{"t":"베트남산 제품에 높은 관세를 매기는 나라가 많아서","mis":"SO6-2-u2-X23"},{"t":"베트남에서는 임금을 주지 않아도 돼서","mis":"SO6-2-u2-X20"}],"explanation":["기사의 까닭을 찾아요.","낮은 관세를 약속한 나라가 많아요.","저렴한 노동력과 중국 공급이에요."],"asset":{"type":"passage","lines":["(간추림) 베트남으로 생산 시설을 옮기는 외국 기업이 늘고 있다.","주된 이유는 저렴한 노동력이다.","중국과 국경을 맞대고 있어 생산한 물자를 중국에 쉽게 공급할 수 있다.","베트남에서 생산한 제품에 낮은 관세를 부과하기로 약속한 나라가 많다.","미국, 중국 기업을 비롯해 우리나라 기업들도 베트남에서 생산 시설을 운영한다."],"numbered":false,"title":"『사회』 109쪽 신문 기사 「베트남으로 향하는 외국 기업의 생산 시설」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L12_basic#9','soc',6,2,'u2','L12','tb_g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C12',2,'mc','auto','기업 운영 계획에서 근로자의 권리를 보호하려는 노력으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u2-X21']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C12","difficulty":2,"kind":"mc","stem":"기업 운영 계획에서 근로자의 권리를 보호하려는 노력으로 알맞은 것은 무엇인가요?","options":[{"t":"성과가 높은 근로자에게 성과급을 주고 휴가를 보장해요","correct":true},{"t":"이윤을 늘리려고 휴가를 없애요","mis":"SO6-2-u2-X21"},{"t":"근로자와 대화하는 시간을 없애요","mis":"SO6-2-u2-X21"}],"explanation":["112쪽 예시예요.","근로자를 아껴요.","성과급과 휴가 보장이에요."],"asset":{"type":"passage","lines":["대표 상품 — △△ 게임(온라인 게임)","상품의 특징 — 여러 가지 캐릭터가 등장해 다양한 과제를 해결하며 성장해 나가요.","주요 수출국 — 중국, 인도","사회적 책임 목표 — 전 세계인이 구입하는 1등 게임을 개발하여 지속가능한 성장을 해요.","근로자 권리 보호 — 성과가 높은 근로자에게 성과급·임금 인상, 휴가 보장"],"title":"『사회』 112~113쪽 생각을 펼쳐요 — 기업 운영 계획 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L12_basic#10','soc',6,2,'u2','L12','tb_g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C11',3,'essay','teacher','수출이 늘어날 때와 수입이 늘어날 때 각각 좋은 점을 쓰고, 수입이 늘 때 생길 수 있는 문제를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"essay","stem":"수출이 늘어날 때와 수입이 늘어날 때 각각 좋은 점을 쓰고, 수입이 늘 때 생길 수 있는 문제를 쓰세요.","answer_guide":{"answer":"예: 수출이 늘면 산업이 성장하고 일자리와 소득이 늘어요. 수입이 늘면 국내에서 얻기 힘든 물자를 써서 생활이 풍족해져요. 하지만 국내 기업이 피해를 입을 수 있어요.","scoring_points":["수출이 늘 때의 좋은 점을 썼는가","수입이 늘 때의 좋은 점을 썼는가","수입이 늘 때의 문제를 썼는가"]},"explanation":["수출 쪽을 써요.","수입 쪽을 써요.","문제도 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L12_challenge#1','soc',6,2,'u2','L12','tb_g6_2_soc_u2_L12_challenge','lesson_challenge','SO6-2-u2-C11',2,'error','auto','무역을 통한 상호 의존과 경쟁에 대한 설명 가운데 잘못된 것을 고르세요.',ARRAY['SO6-2-u2-X23','SO6-2-u2-X20']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C11","difficulty":2,"kind":"error","stem":"무역을 통한 상호 의존과 경쟁에 대한 설명 가운데 잘못된 것을 고르세요.","options":[{"t":"수입이 많아질수록 국내 기업은 늘 더 튼튼해져요","correct":true,"mis_target":"SO6-2-u2-X23"},{"t":"수출이 늘면 산업이 성장하고 일자리가 늘어요","mis":"SO6-2-u2-X20"},{"t":"세계 여러 나라는 수입품에 관세를 부과하기도 해요","mis":"SO6-2-u2-X23"}],"explanation":["수입이 늘면 국내 기업이 어려울 수 있어요.","그래서 관세를 매기기도 해요.","늘 튼튼해진다는 말이 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L12_challenge#2','soc',6,2,'u2','L12','tb_g6_2_soc_u2_L12_challenge','lesson_challenge','SO6-2-u2-C11',2,'sa','auto','수출입 관련 법 지식을 바탕으로 개인이나 기업을 대신해 무역 절차를 처리하고 수출입 물품을 신고하는 직업은 무엇인가요?','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u2-C11","difficulty":2,"kind":"sa","stem":"수출입 관련 법 지식을 바탕으로 개인이나 기업을 대신해 무역 절차를 처리하고 수출입 물품을 신고하는 직업은 무엇인가요?","answer":["관세사"],"explanation":["110쪽 별별 직업이에요.","관세와 관련된 일이에요.","관세사예요."],"mis":"SO6-2-u2-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L12_challenge#3','soc',6,2,'u2','L12','tb_g6_2_soc_u2_L12_challenge','lesson_challenge','SO6-2-u2-C11',3,'mc','auto','109쪽처럼 외국 기업이 베트남에서 생산하면 베트남에 있는 그 기업에서 일하는 사람들이 얻는 좋은 점은 무엇인가요?',ARRAY['SO6-2-u2-X20']::text[],true,'{"seq":3,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"mc","stem":"109쪽처럼 외국 기업이 베트남에서 생산하면 베트남에 있는 그 기업에서 일하는 사람들이 얻는 좋은 점은 무엇인가요?","options":[{"t":"일을 하며 필요한 소득을 얻을 수 있어요","correct":true},{"t":"아무 이익도 없어요","mis":"SO6-2-u2-X20"},{"t":"모든 제품을 공짜로 받아요","mis":"SO6-2-u2-X20"}],"explanation":["일자리가 생겨요.","일한 대가를 받아요.","소득을 얻어요."],"asset":{"type":"passage","lines":["(간추림) 베트남으로 생산 시설을 옮기는 외국 기업이 늘고 있다.","주된 이유는 저렴한 노동력이다.","중국과 국경을 맞대고 있어 생산한 물자를 중국에 쉽게 공급할 수 있다.","베트남에서 생산한 제품에 낮은 관세를 부과하기로 약속한 나라가 많다.","미국, 중국 기업을 비롯해 우리나라 기업들도 베트남에서 생산 시설을 운영한다."],"numbered":false,"title":"『사회』 109쪽 신문 기사 「베트남으로 향하는 외국 기업의 생산 시설」"},"variant_rule":{"alt":[{"stem":"109쪽처럼 베트남에서 생산한 제품을 사는 전 세계 사람들이 얻는 좋은 점은 무엇인가요?","options":[{"t":"기존보다 저렴한 가격으로 제품을 살 수 있어요","correct":true},{"t":"제품 값이 반드시 비싸져요","mis":"SO6-2-u2-X20"},{"t":"아무 영향이 없어요","mis":"SO6-2-u2-X20"}],"explanation":["노동력이 저렴해요.","생산 비용이 줄어요.","더 싸게 살 수 있어요."],"asset":{"type":"passage","lines":["(간추림) 베트남으로 생산 시설을 옮기는 외국 기업이 늘고 있다.","주된 이유는 저렴한 노동력이다.","중국과 국경을 맞대고 있어 생산한 물자를 중국에 쉽게 공급할 수 있다.","베트남에서 생산한 제품에 낮은 관세를 부과하기로 약속한 나라가 많다.","미국, 중국 기업을 비롯해 우리나라 기업들도 베트남에서 생산 시설을 운영한다."],"numbered":false,"title":"『사회』 109쪽 신문 기사 「베트남으로 향하는 외국 기업의 생산 시설」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L12_challenge#4','soc',6,2,'u2','L12','tb_g6_2_soc_u2_L12_challenge','lesson_challenge','SO6-2-u2-C11',3,'mc','auto','한 기업이 여러 나라에서 생산 시설을 운영할 때 생길 수 있는 문제점은 무엇인가요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"mc","stem":"한 기업이 여러 나라에서 생산 시설을 운영할 때 생길 수 있는 문제점은 무엇인가요?","options":[{"t":"근로자가 정당한 임금을 받지 못하거나 환경 오염이 생기기도 해요","correct":true},{"t":"언제나 모두에게 좋은 일만 생겨요","mis":"SO6-2-u2-X20"},{"t":"현지 기업은 늘 이익만 봐요","mis":"SO6-2-u2-X20"}],"explanation":["109쪽 말풍선이에요.","임금과 환경을 살펴요.","그런 문제가 생기기도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L12_challenge#5','soc',6,2,'u2','L12','tb_g6_2_soc_u2_L12_challenge','lesson_challenge','SO6-2-u2-C11',3,'ox','auto','여러 나라에서 만든 부품을 모아 스마트폰을 만드는 것은 무역을 통한 상호 의존의 모습이에요.',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"ox","stem":"여러 나라에서 만든 부품을 모아 스마트폰을 만드는 것은 무역을 통한 상호 의존의 모습이에요.","answer":"O","reason_options":[{"t":"여러 나라의 우수한 물자를 한데 모아 새로운 제품을 만들기 때문에","correct":true},{"t":"여러 나라가 서로 먼저 차지하려고 다투는 모습이기 때문에","mis":"SO6-2-u2-X20"}],"mis":"SO6-2-u2-X20","explanation":["106쪽이에요.","함께 만들어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L12_challenge#6','soc',6,2,'u2','L12','tb_g6_2_soc_u2_L12_challenge','lesson_challenge','SO6-2-u2-C11',3,'mc','auto','다음 가운데 무역을 통한 경쟁에 해당하는 것은 무엇인가요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"mc","stem":"다음 가운데 무역을 통한 경쟁에 해당하는 것은 무엇인가요?","options":[{"t":"철도, 도로, 발전소 같은 다른 나라의 주요 시설을 서로 지으려고 노력해요","correct":true},{"t":"여러 나라의 우수한 물자를 한데 모아 새로운 제품을 만들어요","mis":"SO6-2-u2-X20"},{"t":"여러 나라가 각자 잘하는 분야를 중심으로 함께 사업을 진행해요","mis":"SO6-2-u2-X20"}],"explanation":["함께 만들기는 의존이에요.","서로 차지하려는 것은 경쟁이에요.","시설 건설 경쟁이에요."],"asset":{"type":"passage","lines":["① 첨단 기술 개발 — 생성형 인공지능 시장: 2023년 약 37억 달러","① (전망) 2026년 약 194억 달러 · 2028년 약 363억 달러","② 다른 나라에 필요한 시설 건설 — 우리나라 기업이 건설한 인도의 다리","③ 더 나은 무역 환경 — 자동화 항만 시스템을 갖춘 부산항"],"numbered":false,"title":"『사회』 107쪽 — 무역을 통한 세계 여러 나라의 경쟁"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L12_challenge#7','soc',6,2,'u2','L12','tb_g6_2_soc_u2_L12_challenge','lesson_challenge','SO6-2-u2-C12',3,'mc','auto','기업 운영 계획에 대표 상품과 특징, 사회적 책임 목표, 근로자의 권리 보호 노력을 썼어요. 더 써야 할 것은 무엇인가요?',ARRAY['SO6-2-u2-X21']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C12","difficulty":3,"kind":"mc","stem":"기업 운영 계획에 대표 상품과 특징, 사회적 책임 목표, 근로자의 권리 보호 노력을 썼어요. 더 써야 할 것은 무엇인가요?","options":[{"t":"주요 수출국","correct":true},{"t":"다른 기업과 함께 올릴 가격","mis":"SO6-2-u2-X21"},{"t":"경쟁 기업을 방해할 방법","mis":"SO6-2-u2-X21"}],"explanation":["112쪽 표를 떠올려요.","상품이 필요할 나라를 조사해요.","주요 수출국이에요."],"asset":{"type":"passage","lines":["대표 상품 — △△ 게임(온라인 게임)","상품의 특징 — 여러 가지 캐릭터가 등장해 다양한 과제를 해결하며 성장해 나가요.","주요 수출국 — 중국, 인도","사회적 책임 목표 — 전 세계인이 구입하는 1등 게임을 개발하여 지속가능한 성장을 해요.","근로자 권리 보호 — 성과가 높은 근로자에게 성과급·임금 인상, 휴가 보장"],"title":"『사회』 112~113쪽 생각을 펼쳐요 — 기업 운영 계획 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L12_challenge#8','soc',6,2,'u2','L12','tb_g6_2_soc_u2_L12_challenge','lesson_challenge','SO6-2-u2-C12',4,'essay','teacher','생각을 펼쳐요처럼 기업의 대표가 되어 대표 상품과 특징, 주요 수출국과 고른 까닭, 사회적 책임 목표, 근로자의 권리를 보호하는 노력을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u2-C12","difficulty":4,"kind":"essay","stem":"생각을 펼쳐요처럼 기업의 대표가 되어 대표 상품과 특징, 주요 수출국과 고른 까닭, 사회적 책임 목표, 근로자의 권리를 보호하는 노력을 쓰세요.","answer_guide":{"answer":"예: 대표 상품은 집 앞까지 필요한 물건을 빠르게 배달하는 서비스예요. 주요 수출국은 인도예요. 목표는 환경을 지키며 성장하는 기업이에요. 매주 근로자와 대화의 시간을 가져요.","scoring_points":["대표 상품과 특징을 썼는가","주요 수출국과 까닭을 썼는가","사회적 책임 목표와 근로자 노력을 썼는가"]},"explanation":["상품을 정해요.","수출국을 골라요.","책임과 근로자를 함께 써요."],"asset":{"type":"passage","lines":["대표 상품 — △△ 게임(온라인 게임)","상품의 특징 — 여러 가지 캐릭터가 등장해 다양한 과제를 해결하며 성장해 나가요.","주요 수출국 — 중국, 인도","사회적 책임 목표 — 전 세계인이 구입하는 1등 게임을 개발하여 지속가능한 성장을 해요.","근로자 권리 보호 — 성과가 높은 근로자에게 성과급·임금 인상, 휴가 보장"],"title":"『사회』 112~113쪽 생각을 펼쳐요 — 기업 운영 계획 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L12_challenge#9','soc',6,2,'u2','L12','tb_g6_2_soc_u2_L12_challenge','lesson_challenge','SO6-2-u2-C11',4,'essay','teacher','활동지 카카오 농장 이야기를 읽고, 공정 무역이 필요한 까닭을 쓰고 공정 무역 초콜릿 광고 문구를 만드세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u2-C11","difficulty":4,"kind":"essay","stem":"활동지 카카오 농장 이야기를 읽고, 공정 무역이 필요한 까닭을 쓰고 공정 무역 초콜릿 광고 문구를 만드세요.","answer_guide":{"answer":"예: 무역으로 생기는 이익을 생산자와 소비자가 공평하게 나누고, 생산자에게 정당한 임금을 주며 아동 노동을 막기 위해서예요. 문구: 카이와 우리 모두의 권리를 지키는 초콜릿!","scoring_points":["공정 무역이 필요한 까닭을 썼는가","아동 노동·정당한 임금과 이었는가","취지가 드러나는 문구를 만들었는가"]},"explanation":["카이는 어떤 일을 겪나요?","왜 공정해야 하나요?","문구로 표현해요."],"asset":{"type":"passage","lines":["코트디부아르 카카오 농장에서 일하는 카이는 아홉 살이에요.","하루 종일 10 m가 넘는 카카오나무를 오르내리며 열매를 따요.","카이 몸집만 한 바구니는 6 kg이 넘고, 농약 냄새에 어질어질해요.","전 세계 카카오의 70 %가 서아프리카에서 생산돼요.","농장주들은 초콜릿 가격을 낮추려고 낮은 임금으로 일할 아이들을 찾아요."],"title":"활동지 — 공정 무역 이야기(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_L12_challenge#10','soc',6,2,'u2','L12','tb_g6_2_soc_u2_L12_challenge','lesson_challenge','SO6-2-u2-C11',4,'mc','auto','107쪽 생성형 인공지능 시장 전망 자료로 알 수 있는 것은 무엇인가요?',ARRAY['SO6-2-u2-X20','SO6-2-u2-X18']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C11","difficulty":4,"kind":"mc","stem":"107쪽 생성형 인공지능 시장 전망 자료로 알 수 있는 것은 무엇인가요?","options":[{"t":"시장이 계속 커질 것으로 보여 여러 나라의 경쟁이 치열해져요","correct":true},{"t":"시장이 점점 작아져 경쟁이 줄어요","mis":"SO6-2-u2-X20"},{"t":"한 나라만 인공지능 제품을 만들어요","mis":"SO6-2-u2-X20"},{"t":"이 시장은 무역과 관계가 없어요","mis":"SO6-2-u2-X18"}],"explanation":["2023년 약 37억 달러예요.","2028년 약 363억 달러로 전망해요.","커지는 시장을 두고 경쟁해요."],"asset":{"type":"passage","lines":["① 첨단 기술 개발 — 생성형 인공지능 시장: 2023년 약 37억 달러","① (전망) 2026년 약 194억 달러 · 2028년 약 363억 달러","② 다른 나라에 필요한 시설 건설 — 우리나라 기업이 건설한 인도의 다리","③ 더 나은 무역 환경 — 자동화 항만 시스템을 갖춘 부산항"],"numbered":false,"title":"『사회』 107쪽 — 무역을 통한 세계 여러 나라의 경쟁"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#1','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C2',1,'sa','auto','단원 평가 1번의 ㉠에 들어갈 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u2-C2","difficulty":1,"kind":"sa","stem":"단원 평가 1번의 ㉠에 들어갈 알맞은 말을 쓰세요.","answer":["가계"],"explanation":["살림을 꾸려 가요.","생활 공동체예요.","가계예요."],"asset":{"type":"passage","lines":["시장에서 경제활동을 함께하며 살림을 꾸려 가는 생활 공동체를 ( ㉠ )(이)라고 합니다.","시장에서 이윤을 목적으로 물건이나 서비스를 생산하거나 판매하는 조직을 ( ㉡ )(이)라고 합니다."],"title":"단원 평가 1번"},"mis":"SO6-2-u2-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#2','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C5',1,'mc','auto','단원 평가 9번의 빈칸에 들어갈 말로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u2-X10','SO6-2-u2-X09','SO6-2-u2-X11']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C5","difficulty":1,"kind":"mc","stem":"단원 평가 9번의 빈칸에 들어갈 말로 알맞은 것은 무엇인가요?","options":[{"t":"경제성장","correct":true},{"t":"시장경제","mis":"SO6-2-u2-X10"},{"t":"사회적 책임","mis":"SO6-2-u2-X09"},{"t":"기업의 자유","mis":"SO6-2-u2-X10"},{"t":"한강의 기적","mis":"SO6-2-u2-X11"}],"explanation":["생산 수준과 국민 소득이 늘어요.","경제 규모가 커져요.","경제성장이에요."],"asset":{"type":"passage","lines":["오늘날 사람들은 옛날과 비교하여 물질적으로 풍요로운 삶을 누리고 있습니다.","이처럼 국가의 전체적인 생산 수준이나 국민 소득이 증가하여","경제 규모가 커지는 것을 (    )(이)라고 합니다."],"title":"단원 평가 9번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#3','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C9',1,'mc','auto','단원 도입 ①의 말로 알 수 있는 것은 무엇인가요?',ARRAY['SO6-2-u2-X18']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"mc","stem":"단원 도입 ①의 말로 알 수 있는 것은 무엇인가요?","options":[{"t":"○○ 회사의 컨테이너에는 포도주, 키위, 치즈가 없어요","correct":true},{"t":"○○ 회사의 컨테이너에 포도주가 있어요","mis":"SO6-2-u2-X18"},{"t":"○○ 회사의 컨테이너는 비어 있어요","mis":"SO6-2-u2-X18"}],"explanation":["①은 없다고 했어요.","포도주·키위·치즈예요.","그 물건은 없어요."],"asset":{"type":"passage","lines":["미션 — ○○ 회사의 컨테이너를 찾아요.","① 이 컨테이너(포도주·키위·치즈)에 있는 물건 중에 찾으시는 물건은 없어요.","② 찾으시는 컨테이너 안을 잠깐 봤는데 소고기가 실려 있는 것 같던데요.","③ 이 컨테이너(바나나·오렌지)의 과일 하나가 그 컨테이너에도 있어요.","④ 그 컨테이너 속 물건 하나(밀가루)를 제가 지금 트럭으로 운반하고 있어요."],"numbered":false,"title":"『사회』 56~57쪽 단원 도입 — 네 사람의 말(그림 속 물건은 괄호로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#4','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C1',1,'mc','auto','「시장경제와 국가 간 거래」 단원의 첫 번째 주제는 무엇인가요?',ARRAY['SO6-2-u2-X10','SO6-2-u2-X17']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C1","difficulty":1,"kind":"mc","stem":"「시장경제와 국가 간 거래」 단원의 첫 번째 주제는 무엇인가요?","options":[{"t":"우리나라 시장경제의 특징","correct":true},{"t":"경제성장과 우리 생활","mis":"SO6-2-u2-X10"},{"t":"세계 속의 무역","mis":"SO6-2-u2-X17"}],"explanation":["58쪽 주제 첫째예요.","가계와 기업을 배워요.","우리나라 시장경제의 특징이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#5','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C2',1,'ox','auto','기업은 가계의 생산 활동에 참여하고 그에 대한 대가로 소득을 얻어요.',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C2","difficulty":1,"kind":"ox","stem":"기업은 가계의 생산 활동에 참여하고 그에 대한 대가로 소득을 얻어요.","answer":"X","reason_options":[{"t":"가계가 기업의 생산 활동에 참여해 소득을 얻기 때문에","correct":true},{"t":"소득은 기업이 얻는 것이기 때문에","mis":"SO6-2-u2-X03"}],"mis":"SO6-2-u2-X03","explanation":["77쪽 틀린 가게예요.","가계와 기업이 바뀌었어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#6','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C3',1,'sa','auto','생각 그물: 근로자는 정당한 권리를 주장하며 다른 근로자들과 함께 (    )로 행동할 수 있어요. 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-2-u2-C3","difficulty":1,"kind":"sa","stem":"생각 그물: 근로자는 정당한 권리를 주장하며 다른 근로자들과 함께 (    )로 행동할 수 있어요. 빈칸에 알맞은 말을 쓰세요.","answer":["단체"],"explanation":["114쪽 생각 그물이에요.","여럿이 함께해요.","단체예요."],"mis":"SO6-2-u2-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#7','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C9',1,'mc','auto','교실 놀이 카드 가운데 거짓인 문장(스파이)은 무엇인가요?',ARRAY['SO6-2-u2-X17','SO6-2-u2-X18']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"mc","stem":"교실 놀이 카드 가운데 거짓인 문장(스파이)은 무엇인가요?","options":[{"t":"카드 ②","correct":true},{"t":"카드 ①","mis":"SO6-2-u2-X17"},{"t":"카드 ③","mis":"SO6-2-u2-X18"},{"t":"카드 ④","mis":"SO6-2-u2-X18"}],"explanation":["파는 것은 수출이에요.","카드 ②가 수입이라 했어요.","카드 ②가 스파이예요."],"asset":{"type":"passage","lines":["카드 ① 무역이란 나라 사이에 물자나 서비스를 사고파는 것입니다.","카드 ② 다른 나라에 물자나 서비스를 파는 것을 수입이라고 합니다.","카드 ③ 무역을 통해 부족한 물자나 서비스를 다른 나라로부터 구할 수 있습니다.","카드 ④ 나라마다 효율적으로 생산하는 물자나 서비스가 달라 무역이 필요합니다."],"title":"『사회』 116~117쪽 교실 놀이 「스파이를 찾아라」 — 한 모둠의 문장 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#8','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C2',1,'mc','auto','68쪽 사이버 평판 관리자가 하는 일은 무엇인가요?',ARRAY['SO6-2-u2-X04']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C2","difficulty":1,"kind":"mc","stem":"68쪽 사이버 평판 관리자가 하는 일은 무엇인가요?","options":[{"t":"온라인에서 기업에 관한 사람들의 평가와 만족감을 살펴요","correct":true},{"t":"공장에서 자동차를 조립해요","mis":"SO6-2-u2-X04"},{"t":"수입 물품을 나라에 신고해요","mis":"SO6-2-u2-X04"}],"explanation":["온라인 평판을 봐요.","나쁜 평판에 대응해요.","평판을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#9','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C1',2,'mc','auto','단원 평가 2번: 시장에서 이루어지는 자유로운 경쟁의 모습으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"mc","stem":"단원 평가 2번: 시장에서 이루어지는 자유로운 경쟁의 모습으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"모두가 행복한 사회를 만들기 위해 봉사 활동을 해요","correct":true},{"t":"일자리를 얻으려고 다른 사람들과 경쟁해요","mis":"SO6-2-u2-X03"},{"t":"원하는 물건을 사려고 다른 사람들과 경쟁해요","mis":"SO6-2-u2-X03"},{"t":"다른 기업보다 더 많은 물건을 팔려고 경쟁해요","mis":"SO6-2-u2-X03"},{"t":"다른 기업보다 더 좋은 물건을 만들려고 노력해요","mis":"SO6-2-u2-X03"}],"explanation":["경쟁하는 모습을 찾아요.","봉사 활동은 경쟁이 아니에요.","봉사 활동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#10','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C4',2,'mc','auto','단원 평가 8번: 기업이 경제활동을 하면서 발생할 수 있는 문제로 알맞지 않은 것은 무엇인가요?',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"mc","stem":"단원 평가 8번: 기업이 경제활동을 하면서 발생할 수 있는 문제로 알맞지 않은 것은 무엇인가요?","options":[{"t":"더 좋은 물건이나 서비스를 생산하려고 연구해요","correct":true},{"t":"기업 간에 사업을 방해해요","mis":"SO6-2-u2-X08"},{"t":"소비자에게 잘못된 정보를 제공해요","mis":"SO6-2-u2-X08"},{"t":"제품 생산 과정에서 환경을 오염해요","mis":"SO6-2-u2-X08"},{"t":"일부 기업끼리 약속해서 함께 가격을 올려요","mis":"SO6-2-u2-X08"}],"explanation":["문제가 아닌 것을 찾아요.","연구는 기업의 역할이에요.","연구가 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#11','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C10',2,'mc','auto','단원 평가 16번처럼 우리나라의 주요 수입품과 수출품을 보고 알 수 있는 점은 무엇인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":11,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"mc","stem":"단원 평가 16번처럼 우리나라의 주요 수입품과 수출품을 보고 알 수 있는 점은 무엇인가요?","options":[{"t":"천연자원이 부족하여 원유, 석탄 등을 수입해요","correct":true},{"t":"주요 수출품에는 원유, 천연가스 등이 있어요","mis":"SO6-2-u2-X19"},{"t":"주요 수입품에는 자동차, 석유 제품 등이 있어요","mis":"SO6-2-u2-X19"},{"t":"노동력이 많이 필요한 제품을 주로 수입해요","mis":"SO6-2-u2-X19"}],"explanation":["수입품 칸을 봐요.","천연자원이에요.","그 설명이 맞아요."],"asset":{"type":"passage","lines":["주요 수입품 — 원유 · 정밀 화학 원료 · 천연가스 · 석탄","주요 수출품 — 반도체 · 석유 제품 · 무선 통신 기기 · 자동차","원유 — 불순물을 없애지 않은 자연 상태의 석유","석유 제품 — 원유의 혼합물을 분리해 만든 휘발유, 경유 같은 연료 제품","정밀 화학 원료 — 비료, 의약품, 배터리 등을 만드는 데 필요한 기초 원료"],"title":"『사회』 100쪽 — 우리나라의 주요 수입품과 수출품"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#12','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C9',2,'mc','auto','활동지 신드바드 이야기에서 신드바드가 태양 나라에 안장을 ( ㉠ )하고, 인도로부터 향신료를 ( ㉡ )했어요. 알맞게 짝지은 것은?',ARRAY['SO6-2-u2-X17']::text[],false,'{"seq":12,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"mc","stem":"활동지 신드바드 이야기에서 신드바드가 태양 나라에 안장을 ( ㉠ )하고, 인도로부터 향신료를 ( ㉡ )했어요. 알맞게 짝지은 것은?","options":[{"t":"㉠ 수출 · ㉡ 수입","correct":true},{"t":"㉠ 수입 · ㉡ 수출","mis":"SO6-2-u2-X17"},{"t":"㉠ 수출 · ㉡ 수출","mis":"SO6-2-u2-X17"}],"explanation":["안장은 팔았어요.","향신료는 사 왔어요.","수출과 수입이에요."],"asset":{"type":"passage","lines":["바그다드 상인 신드바드는 태양 나라 사람들이 안장 없이 말을 타는 것을 봤어요.","신드바드는 안장을 만들어 왕에게 바쳤고, 사람들이 너도나도 주문했어요.","신드바드는 안장을 만들어 팔아 큰돈을 벌었어요.","그 뒤 인도에서 온갖 향신료를 사들여 돈을 벌었어요."],"title":"활동지 — 신드바드 이야기(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#13','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C5',2,'mc','auto','79쪽 자료에서 1960년부터 1980년까지 두 나라의 1인당 국민 총소득은 어떠했나요?',ARRAY['SO6-2-u2-X11']::text[],false,'{"seq":13,"concept":"SO6-2-u2-C5","difficulty":2,"kind":"mc","stem":"79쪽 자료에서 1960년부터 1980년까지 두 나라의 1인당 국민 총소득은 어떠했나요?","options":[{"t":"두 나라 모두 낮았고 차이가 크지 않았어요","correct":true},{"t":"우리나라가 처음부터 훨씬 높았어요","mis":"SO6-2-u2-X11"},{"t":"○○ 나라가 크게 앞서 차이가 계속 벌어졌어요","mis":"SO6-2-u2-X11"}],"explanation":["1960년 120과 230이에요.","1980년 1,870과 770이에요.","차이가 크지 않았어요."],"asset":{"type":"passage","lines":["연도 — 1960 · 1970 · 1980 · 1990 · 2000 · 2010 · 2023","우리나라 — 120 · 280 · 1,870 · 6,450 · 11,030 · 22,290 · 35,490","○○ 나라 — 230 · 240 · 770 · 830 · 1,180 · 2,360 · 4,230","(단위: 달러 · 꺾은선그래프를 글로 옮김)"],"numbered":false,"title":"『사회』 79쪽 — 1인당 국민 총소득 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#14','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C3',2,'mc','auto','70쪽 친구와 활동에서 나온 근로자의 권리를 보호하는 방법은 무엇인가요?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":14,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"mc","stem":"70쪽 친구와 활동에서 나온 근로자의 권리를 보호하는 방법은 무엇인가요?","options":[{"t":"근로자의 휴식을 제대로 보장하지 않는 기업에 벌금을 부과해요","correct":true},{"t":"휴게실 사용을 막아요","mis":"SO6-2-u2-X06"},{"t":"휴가를 줄여요","mis":"SO6-2-u2-X06"}],"explanation":["70쪽 예시예요.","휴식을 지키게 해요.","벌금을 부과해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#15','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C7',2,'match','auto','빠른 경제성장으로 발생한 문제와 그 원인을 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SO6-2-u2-C7","difficulty":2,"kind":"match","stem":"빠른 경제성장으로 발생한 문제와 그 원인을 알맞게 이으세요.","pairs":[{"l":"환경 문제","r":"자연의 무분별한 개발과 쓰레기 증가"},{"l":"빈부 격차","r":"사람들의 소득 차이가 커짐"},{"l":"과소비와 자원 낭비","r":"필요보다 많은 돈과 자원을 씀"},{"l":"노사 갈등","r":"임금이나 복지 혜택을 두고 다툼"}],"mis":"SO6-2-u2-X14","explanation":["개발과 쓰레기는 환경이에요.","소득 차이는 빈부 격차예요.","임금 다툼은 노사 갈등이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#16','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C5',2,'mc','auto','1인당 국민 총소득이 늘어나면 사람들의 생활은 어떻게 달라질까요?',ARRAY['SO6-2-u2-X12','SO6-2-u2-X10']::text[],false,'{"seq":16,"concept":"SO6-2-u2-C5","difficulty":2,"kind":"mc","stem":"1인당 국민 총소득이 늘어나면 사람들의 생활은 어떻게 달라질까요?","options":[{"t":"일자리가 많아지고 소득이 늘어 생활 수준이 높아져요","correct":true},{"t":"생활은 전혀 달라지지 않아요","mis":"SO6-2-u2-X12"},{"t":"물건의 품질이 나빠져요","mis":"SO6-2-u2-X10"}],"explanation":["소득이 늘어요.","살 수 있는 것이 많아져요.","생활 수준이 높아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#17','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C5',3,'essay','teacher','단원 평가 10번: 우리나라와 ○○ 나라의 1인당 국민 총소득 변화를 보고 알 수 있는 우리나라 경제성장의 특징을 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"SO6-2-u2-C5","difficulty":3,"kind":"essay","stem":"단원 평가 10번: 우리나라와 ○○ 나라의 1인당 국민 총소득 변화를 보고 알 수 있는 우리나라 경제성장의 특징을 쓰세요.","answer_guide":{"answer":"예: 1980년까지는 ○○ 나라와 큰 차이가 없었지만, 그 뒤 우리나라의 1인당 국민 총소득이 매우 빠르게 늘어 2023년에는 35,490달러로 ○○ 나라보다 훨씬 많아졌어요.","scoring_points":["1980년까지의 모습을 썼는가","그 뒤 빠르게 늘어난 모습을 썼는가","수를 근거로 들었는가"]},"explanation":["앞쪽과 뒤쪽을 나눠 봐요.","언제부터 벌어졌나요?","빠른 성장을 써요."],"asset":{"type":"passage","lines":["연도 — 1960 · 1970 · 1980 · 1990 · 2000 · 2010 · 2023","우리나라 — 120 · 280 · 1,870 · 6,450 · 11,030 · 22,290 · 35,490","○○ 나라 — 230 · 240 · 770 · 830 · 1,180 · 2,360 · 4,230","(단위: 달러 · 꺾은선그래프를 글로 옮김)"],"numbered":false,"title":"『사회』 79쪽 — 1인당 국민 총소득 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#18','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C2',3,'essay','teacher','단원 평가 3번: 가계의 역할을 두 가지 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"SO6-2-u2-C2","difficulty":3,"kind":"essay","stem":"단원 평가 3번: 가계의 역할을 두 가지 쓰세요.","answer_guide":{"answer":"기업의 생산 활동에 참여하고 그 대가로 소득을 얻어요. 소득으로 기업이 만든 물건이나 서비스를 소비해요.","scoring_points":["생산 활동 참여와 소득을 썼는가","소비를 썼는가","두 가지를 썼는가"]},"explanation":["가계가 기업에 주는 것은?","가계가 시장에서 하는 일은?","두 가지를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#19','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C8',3,'sa','auto','90쪽 평가표에서 방안 ㉯의 합계는 몇 점인가요?','{}'::text[],false,'{"seq":19,"concept":"SO6-2-u2-C8","difficulty":3,"kind":"sa","stem":"90쪽 평가표에서 방안 ㉯의 합계는 몇 점인가요?","answer":["8점","8"],"explanation":["1, 5, 1, 1을 더해요.","네 기준을 모두 더해요.","8점이에요."],"asset":{"type":"passage","lines":["방안 ㉮ 시민 단체를 만들어 무분별한 개발 감시하기","방안 ㉯ 개발할 수 있는 자원량을 법으로 정하기","방안 ㉰ 환경 문제의 심각성을 알리는 캠페인 벌이기","실천할 수 있나요? — ㉮ 1점 · ㉯ 1점 · ㉰ 5점","효과가 큰가요? — ㉮ 5점 · ㉯ 5점 · ㉰ 5점","비용이 적게 드나요? — ㉮ 3점 · ㉯ 1점 · ㉰ 5점","시간이 많이 필요하나요? — ㉮ 3점 · ㉯ 1점 · ㉰ 4점"],"title":"『사회』 90쪽 할 수 있어요 — 어느 모둠의 환경 문제 해결 방안 평가표(1~5점)"},"mis":"SO6-2-u2-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#20','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C9',3,'mc','auto','98쪽 ㉮ 나라는 쌀도 ㉯ 나라보다 많이 생산할 수 있는데 쌀을 수입하는 까닭은 무엇인가요?',ARRAY['SO6-2-u2-X18','SO6-2-u2-X22']::text[],false,'{"seq":20,"concept":"SO6-2-u2-C9","difficulty":3,"kind":"mc","stem":"98쪽 ㉮ 나라는 쌀도 ㉯ 나라보다 많이 생산할 수 있는데 쌀을 수입하는 까닭은 무엇인가요?","options":[{"t":"옷 생산에 집중하는 편이 더 큰 이익이고, 쌀은 ㉯ 나라에서 사 오면 되어서","correct":true},{"t":"㉮ 나라는 쌀을 전혀 기를 수 없어서","mis":"SO6-2-u2-X18"},{"t":"무역은 손해라서 하지 않아요","mis":"SO6-2-u2-X22"}],"explanation":["더 큰 이익을 봐요.","옷에 집중해요.","쌀은 사 와요."],"asset":{"type":"passage","lines":["㉮ 나라와 ㉯ 나라는 모두 쌀과 옷을 생산할 수 있어요.","㉮ 나라는 ㉯ 나라보다 같은 시간과 비용으로 쌀과 옷을 모두 더 많이 생산해요.","㉮ 나라는 기술 수준이 높아 쌀보다 옷을 생산해 수출할 때 더 큰 이익을 얻어요.","㉯ 나라는 기술 수준은 낮지만 쌀을 재배하기에 알맞아 쌀을 수출할 때 더 큰 이익을 얻어요."],"numbered":false,"title":"『사회』 98쪽 친구와 활동 — ㉮ 나라와 ㉯ 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#21','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C6',3,'mc','auto','82쪽 기사에서 콘텐츠 수출이 늘 때 함께 늘어난 수출 품목은 무엇인가요?',ARRAY['SO6-2-u2-X13']::text[],false,'{"seq":21,"concept":"SO6-2-u2-C6","difficulty":3,"kind":"mc","stem":"82쪽 기사에서 콘텐츠 수출이 늘 때 함께 늘어난 수출 품목은 무엇인가요?","options":[{"t":"화장품, 식품","correct":true},{"t":"원유, 석탄","mis":"SO6-2-u2-X13"},{"t":"흑연, 철광석","mis":"SO6-2-u2-X13"}],"explanation":["기사 끝부분이에요.","문화가 다른 상품도 알려요.","화장품과 식품이에요."],"asset":{"type":"passage","lines":["콘텐츠 산업 — 게임, 영화, 방송, 출판, 만화, 음악, 애니메이션, 광고, 캐릭터","2022년 수출액 132.4억 달러 — 전년보다 6.3 % 늘어 역대 최대","같은 기간 전기차, 가전제품 같은 주요 품목의 수출액보다 많았다.","콘텐츠 수출이 늘면 화장품, 식품 수출도 함께 늘었다.","수출액(억 달러) — 2006년 13.7 · 2010년 31.9 · 2014년 52.7","수출액(억 달러) — 2018년 96.2 · 2020년 119.2 · 2022년 132.4"],"numbered":false,"title":"『사회』 82쪽 신문 기사 「콘텐츠 산업 수출액 역대 최대」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#22','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C4',3,'mc','auto','73쪽 ③을 보고 우리 기업이 1위 기업을 따라잡으려고 내릴 수 있는 결정은 무엇인가요?',ARRAY['SO6-2-u2-X05']::text[],false,'{"seq":22,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"mc","stem":"73쪽 ③을 보고 우리 기업이 1위 기업을 따라잡으려고 내릴 수 있는 결정은 무엇인가요?","options":[{"t":"온라인 광고의 비중을 더 높여요","correct":true},{"t":"광고를 모두 없애요","mis":"SO6-2-u2-X05"},{"t":"현장 광고만 해요","mis":"SO6-2-u2-X05"}],"explanation":["1위 기업은 온라인 46 %예요.","소비자가 있는 곳에 광고해요.","온라인 광고를 늘려요."],"asset":{"type":"passage","lines":["① 제품 선호도 — 10대: □□ 가장 높음, △△ 중간, ○○ 낮음","① 제품 선호도 — 20대: ○○ 가장 높음, □□ 비슷하게 높음, △△ 낮음","② 상품 가격 — ㉮ 기업 2,200원 · 우리 기업 2,300원 · ㉯ 기업 2,400원","② 생산 비용 — 세 기업 모두 1,500원","③ 1위 ㉰ 기업 광고비 지출 비율 — 온라인 46 % · 방송 27 %","③ (이어서) 기타 12 % · 지면 10 % · 현장 5 %"],"numbered":false,"title":"『사회』 73쪽 — 기업이 내려야 할 결정(그래프·표를 글로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#23','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C6',4,'essay','teacher','경제성장이 우리 생활에 준 좋은 영향 두 가지와 빠른 경제성장으로 생긴 문제 한 가지를 쓰고, 그 문제를 풀 방법을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO6-2-u2-C6","difficulty":4,"kind":"essay","stem":"경제성장이 우리 생활에 준 좋은 영향 두 가지와 빠른 경제성장으로 생긴 문제 한 가지를 쓰고, 그 문제를 풀 방법을 쓰세요.","answer_guide":{"answer":"예: 첨단 기술로 생활이 편리해졌고, 의료 혜택으로 기대 수명이 늘었어요. 하지만 일회용품 쓰레기 같은 환경 문제가 생겼어요. 분리배출을 꼼꼼히 하고 일회용품을 줄여요.","scoring_points":["좋은 영향 두 가지를 썼는가","문제 한 가지를 썼는가","알맞은 해결 방법을 썼는가"]},"explanation":["좋은 점을 찾아요.","문제도 찾아요.","푸는 방법을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#24','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C11',4,'essay','teacher','무역을 통한 상호 의존 사례와 경쟁 사례를 하나씩 쓰고, 두 관계가 함께 나타나는 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u2-C11","difficulty":4,"kind":"essay","stem":"무역을 통한 상호 의존 사례와 경쟁 사례를 하나씩 쓰고, 두 관계가 함께 나타나는 까닭을 쓰세요.","answer_guide":{"answer":"예: 여러 나라의 부품을 모아 스마트폰을 만드는 것은 상호 의존이에요. 부산항이 자동화 항만을 갖추는 것은 경쟁이에요. 서로 필요한 것을 주고받으면서도 더 많은 이익을 얻으려 하기 때문이에요.","scoring_points":["상호 의존 사례를 썼는가","경쟁 사례를 썼는가","함께 나타나는 까닭을 썼는가"]},"explanation":["함께 만드는 사례를 찾아요.","앞서려는 사례를 찾아요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_a#25','soc',6,2,'u2','','tb_g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C12',4,'essay','teacher','「이달의 기업」 잡지 표지에 넣을 우리 기업 소개 문구를 대표 상품, 사회적 책임, 근로자를 위한 노력이 드러나게 만드세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u2-C12","difficulty":4,"kind":"essay","stem":"「이달의 기업」 잡지 표지에 넣을 우리 기업 소개 문구를 대표 상품, 사회적 책임, 근로자를 위한 노력이 드러나게 만드세요.","answer_guide":{"answer":"예: 매주 근로자와 대화의 시간을 갖는 ○○ 기업! 전 세계인이 즐기는 △△ 게임으로 지속가능한 성장을 해요.","scoring_points":["대표 상품이 드러나는가","사회적 책임이 드러나는가","근로자를 위한 노력이 드러나는가"]},"explanation":["상품을 넣어요.","책임을 넣어요.","근로자도 넣어요."],"asset":{"type":"passage","lines":["대표 상품 — △△ 게임(온라인 게임)","상품의 특징 — 여러 가지 캐릭터가 등장해 다양한 과제를 해결하며 성장해 나가요.","주요 수출국 — 중국, 인도","사회적 책임 목표 — 전 세계인이 구입하는 1등 게임을 개발하여 지속가능한 성장을 해요.","근로자 권리 보호 — 성과가 높은 근로자에게 성과급·임금 인상, 휴가 보장"],"title":"『사회』 112~113쪽 생각을 펼쳐요 — 기업 운영 계획 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#1','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C2',1,'sa','auto','단원 평가 1번의 ㉡에 들어갈 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u2-C2","difficulty":1,"kind":"sa","stem":"단원 평가 1번의 ㉡에 들어갈 알맞은 말을 쓰세요.","answer":["기업"],"explanation":["이윤을 목적으로 해요.","생산하고 판매해요.","기업이에요."],"asset":{"type":"passage","lines":["시장에서 경제활동을 함께하며 살림을 꾸려 가는 생활 공동체를 ( ㉠ )(이)라고 합니다.","시장에서 이윤을 목적으로 물건이나 서비스를 생산하거나 판매하는 조직을 ( ㉡ )(이)라고 합니다."],"title":"단원 평가 1번"},"mis":"SO6-2-u2-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#2','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C9',1,'mc','auto','단원 평가 14번의 ㉠, ㉡, ㉢에 들어갈 말을 차례대로 알맞게 짝지은 것은 무엇인가요?',ARRAY['SO6-2-u2-X17','SO6-2-u2-X18']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"mc","stem":"단원 평가 14번의 ㉠, ㉡, ㉢에 들어갈 말을 차례대로 알맞게 짝지은 것은 무엇인가요?","options":[{"t":"무역 — 수입 — 수출","correct":true},{"t":"수입 — 무역 — 수출","mis":"SO6-2-u2-X17"},{"t":"무역 — 수출 — 수입","mis":"SO6-2-u2-X17"},{"t":"물물 교환 — 판매 — 구입","mis":"SO6-2-u2-X18"},{"t":"물물 교환 — 생산 — 소비","mis":"SO6-2-u2-X18"}],"explanation":["㉠은 나라 사이의 거래예요.","사 오면 수입, 팔면 수출이에요.","무역 — 수입 — 수출이에요."],"asset":{"type":"speech","turns":[{"who":"세연","text":"나라와 나라 사이에 물자나 서비스를 사고팔거나 교환하는 활동을 ( ㉠ )(이)라고 해."},{"who":"진수","text":"다른 나라에서 물자나 서비스를 사 오는 것을 ( ㉡ ), 다른 나라에 파는 것을 ( ㉢ )(이)라고 해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#3','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C9',1,'mc','auto','단원 도입 ②의 말로 알 수 있는 ○○ 회사 컨테이너 속 물건은 무엇인가요?',ARRAY['SO6-2-u2-X18']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"mc","stem":"단원 도입 ②의 말로 알 수 있는 ○○ 회사 컨테이너 속 물건은 무엇인가요?","options":[{"t":"소고기","correct":true},{"t":"치즈","mis":"SO6-2-u2-X18"},{"t":"키위","mis":"SO6-2-u2-X18"}],"explanation":["②를 봐요.","안을 잠깐 봤대요.","소고기예요."],"asset":{"type":"passage","lines":["미션 — ○○ 회사의 컨테이너를 찾아요.","① 이 컨테이너(포도주·키위·치즈)에 있는 물건 중에 찾으시는 물건은 없어요.","② 찾으시는 컨테이너 안을 잠깐 봤는데 소고기가 실려 있는 것 같던데요.","③ 이 컨테이너(바나나·오렌지)의 과일 하나가 그 컨테이너에도 있어요.","④ 그 컨테이너 속 물건 하나(밀가루)를 제가 지금 트럭으로 운반하고 있어요."],"numbered":false,"title":"『사회』 56~57쪽 단원 도입 — 네 사람의 말(그림 속 물건은 괄호로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#4','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C5',1,'mc','auto','「시장경제와 국가 간 거래」 단원의 두 번째 주제는 무엇인가요?',ARRAY['SO6-2-u2-X01','SO6-2-u2-X17']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C5","difficulty":1,"kind":"mc","stem":"「시장경제와 국가 간 거래」 단원의 두 번째 주제는 무엇인가요?","options":[{"t":"경제성장과 우리 생활","correct":true},{"t":"우리나라 시장경제의 특징","mis":"SO6-2-u2-X01"},{"t":"세계 속의 무역","mis":"SO6-2-u2-X17"}],"explanation":["58쪽 주제 둘째예요.","경제성장을 배워요.","경제성장과 우리 생활이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#5','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C9',1,'ox','auto','각 나라의 자연환경, 자원, 자본, 기술 등이 비슷해서 무역이 발생해요.',ARRAY['SO6-2-u2-X18']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"ox","stem":"각 나라의 자연환경, 자원, 자본, 기술 등이 비슷해서 무역이 발생해요.","answer":"X","reason_options":[{"t":"조건이 서로 달라 잘 만드는 것이 다르기 때문에","correct":true},{"t":"같은 것을 만들수록 무역이 더 필요하기 때문에","mis":"SO6-2-u2-X18"}],"mis":"SO6-2-u2-X18","explanation":["111쪽 틀린 설명이에요.","조건이 달라서예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#6','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C8',1,'blank','auto','생각 그물: (    )은 빠른 경제성장으로 발생한 문제를 풀려고 다양한 제도와 정책을 만들어요. 빈칸에 알맞은 말은?',ARRAY['SO6-2-u2-X15']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C8","difficulty":1,"kind":"blank","stem":"생각 그물: (    )은 빠른 경제성장으로 발생한 문제를 풀려고 다양한 제도와 정책을 만들어요. 빈칸에 알맞은 말은?","options":[{"t":"정부","correct":true},{"t":"가계","mis":"SO6-2-u2-X15"},{"t":"시장","mis":"SO6-2-u2-X15"}],"explanation":["제도와 정책을 만들어요.","나라 살림을 맡아요.","정부예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#7','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C9',1,'ox','auto','무역을 통해 부족한 물자나 서비스를 다른 나라로부터 구할 수 있어요.',ARRAY['SO6-2-u2-X18']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"ox","stem":"무역을 통해 부족한 물자나 서비스를 다른 나라로부터 구할 수 있어요.","answer":"O","reason_options":[{"t":"다른 나라에서 사 오는 수입으로 부족한 것을 채우기 때문에","correct":true},{"t":"무역은 남는 물건을 버리는 일이기 때문에","mis":"SO6-2-u2-X18"}],"mis":"SO6-2-u2-X18","explanation":["스파이 놀이 카드예요.","사실인 문장이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#8','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C6',1,'mc','auto','84쪽 빅데이터 전문가가 데이터를 분석해 도입한 「올빼미 버스」는 어떤 버스인가요?',ARRAY['SO6-2-u2-X13']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C6","difficulty":1,"kind":"mc","stem":"84쪽 빅데이터 전문가가 데이터를 분석해 도입한 「올빼미 버스」는 어떤 버스인가요?","options":[{"t":"늦은 시간 통신 데이터가 많은 지역에 자정부터 오전 5시까지 다니는 버스","correct":true},{"t":"아침 출근 시간에만 다니는 버스","mis":"SO6-2-u2-X13"},{"t":"데이터 없이 아무 길이나 다니는 버스","mis":"SO6-2-u2-X13"}],"explanation":["늦은 밤 버스예요.","데이터로 노선을 찾았어요.","그 버스예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#9','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C2',2,'mc','auto','단원 평가 4번: 가계와 기업의 역할에 관한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u2-X03','SO6-2-u2-X05']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"mc","stem":"단원 평가 4번: 가계와 기업의 역할에 관한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"기업은 가계에 일자리를 제공해요","correct":true},{"t":"가계는 근로자에게 급여를 지급해요","mis":"SO6-2-u2-X03"},{"t":"기업은 가계의 생산 활동에 참여해요","mis":"SO6-2-u2-X03"},{"t":"가계는 물건을 생산해 판매하거나 서비스를 제공해요","mis":"SO6-2-u2-X03"},{"t":"가계는 가장 많은 비용으로 가장 큰 만족을 얻으려 해요","mis":"SO6-2-u2-X05"}],"explanation":["기업이 하는 일을 봐요.","일자리를 줘요.","그 설명이 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#10','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C3',2,'mc','auto','단원 평가 6번: 「근무 시간을 개인별 상황에 맞게 조정할 수 있으면 좋겠습니다.」와 관련 있는 근로자의 권리는 무엇인가요?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"mc","stem":"단원 평가 6번: 「근무 시간을 개인별 상황에 맞게 조정할 수 있으면 좋겠습니다.」와 관련 있는 근로자의 권리는 무엇인가요?","options":[{"t":"근로 조건이나 근로 환경 등을 기업과 협의할 수 있어요","correct":true},{"t":"근로자는 단체로 행동할 수 없어요","mis":"SO6-2-u2-X06"},{"t":"근로 조건은 기업이 혼자 정해요","mis":"SO6-2-u2-X06"}],"explanation":["71쪽 그림 ②예요.","기업과 이야기해요.","협의할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#11','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C10',2,'mc','auto','단원 평가 17번: 사진과 관련 있는 무역이 이루어지는 모습은 무엇인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":11,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"mc","stem":"단원 평가 17번: 사진과 관련 있는 무역이 이루어지는 모습은 무엇인가요?","options":[{"t":"뛰어난 기술을 바탕으로 생산한 물자를 수출해요","correct":true},{"t":"풍부한 노동력을 수출해요","mis":"SO6-2-u2-X19"},{"t":"풍부한 천연자원을 수출해요","mis":"SO6-2-u2-X19"},{"t":"다양한 문화 상품을 수출해요","mis":"SO6-2-u2-X19"},{"t":"넓은 땅에서 많은 농산물을 생산해 수출해요","mis":"SO6-2-u2-X19"}],"explanation":["백신은 기술이 필요해요.","103쪽 독일 사례예요.","기술로 만든 물자 수출이에요."],"asset":{"type":"passage","lines":["사진 — 한 연구소에서 수출할 백신을 연구하는 모습"],"title":"단원 평가 17번(사진을 글로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#12','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C9',2,'mc','auto','97쪽처럼 한 나라가 비행기를 만드는 기술이 없다면 어떤 문제가 생길까요?',ARRAY['SO6-2-u2-X18','SO6-2-u2-X22']::text[],false,'{"seq":12,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"mc","stem":"97쪽처럼 한 나라가 비행기를 만드는 기술이 없다면 어떤 문제가 생길까요?","options":[{"t":"비행기를 이용할 수 없어 여행이나 교류가 불편해져요","correct":true},{"t":"난방을 전혀 할 수 없어요","mis":"SO6-2-u2-X18"},{"t":"아무 문제도 생기지 않아요","mis":"SO6-2-u2-X22"}],"explanation":["비행기는 일부 나라만 만들어요.","없으면 이동이 어려워요.","여행과 교류가 불편해져요."],"asset":{"type":"passage","lines":["비행기를 만드는 데는 수준 높은 기술이 필요해 일부 국가에서만 만들 수 있어요.","천연가스는 난방이나 차량 연료로 쓰이는데, 매장된 곳이 많지 않아 일부 국가에서만 생산해요."],"title":"『사회』 97쪽 스스로 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#13','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C6',2,'mc','auto','82쪽 기사에서 콘텐츠 산업에 포함되지 않는 것은 무엇인가요?',ARRAY['SO6-2-u2-X13']::text[],false,'{"seq":13,"concept":"SO6-2-u2-C6","difficulty":2,"kind":"mc","stem":"82쪽 기사에서 콘텐츠 산업에 포함되지 않는 것은 무엇인가요?","options":[{"t":"반도체","correct":true},{"t":"게임","mis":"SO6-2-u2-X13"},{"t":"애니메이션","mis":"SO6-2-u2-X13"},{"t":"캐릭터","mis":"SO6-2-u2-X13"}],"explanation":["콘텐츠 부문을 봐요.","반도체는 첨단 제품이에요.","반도체예요."],"asset":{"type":"passage","lines":["콘텐츠 산업 — 게임, 영화, 방송, 출판, 만화, 음악, 애니메이션, 광고, 캐릭터","2022년 수출액 132.4억 달러 — 전년보다 6.3 % 늘어 역대 최대","같은 기간 전기차, 가전제품 같은 주요 품목의 수출액보다 많았다.","콘텐츠 수출이 늘면 화장품, 식품 수출도 함께 늘었다.","수출액(억 달러) — 2006년 13.7 · 2010년 31.9 · 2014년 52.7","수출액(억 달러) — 2018년 96.2 · 2020년 119.2 · 2022년 132.4"],"numbered":false,"title":"『사회』 82쪽 신문 기사 「콘텐츠 산업 수출액 역대 최대」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#14','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C4',2,'mc','auto','기업이 사회적 책임을 다해야 하는 까닭은 무엇인가요?',ARRAY['SO6-2-u2-X25','SO6-2-u2-X08']::text[],false,'{"seq":14,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"mc","stem":"기업이 사회적 책임을 다해야 하는 까닭은 무엇인가요?","options":[{"t":"기업의 경제활동은 사회에 큰 영향을 미치기 때문이에요","correct":true},{"t":"기업은 이윤을 얻으면 안 되기 때문이에요","mis":"SO6-2-u2-X25"},{"t":"기업의 자유를 없애기 위해서예요","mis":"SO6-2-u2-X08"}],"explanation":["75쪽이에요.","사회에 영향이 커요.","그래서 책임이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#15','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C9',2,'match','auto','무역과 관련된 낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"match","stem":"무역과 관련된 낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"무역","r":"나라 사이에 물자나 서비스를 사고팔거나 교환하는 일"},{"l":"수입","r":"다른 나라에서 물자나 서비스를 사 오는 것"},{"l":"수출","r":"다른 나라에 물자나 서비스를 파는 것"}],"mis":"SO6-2-u2-X17","explanation":["나라 사이의 거래는 무역이에요.","사 오면 수입이에요.","팔면 수출이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#16','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C9',2,'mc','auto','99쪽에서 흑연이 원료로 쓰이는 것은 무엇인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":16,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"mc","stem":"99쪽에서 흑연이 원료로 쓰이는 것은 무엇인가요?","options":[{"t":"연필, 스마트폰, 배터리","correct":true},{"t":"쌀과 옷","mis":"SO6-2-u2-X19"},{"t":"백신과 로봇","mis":"SO6-2-u2-X19"}],"explanation":["99쪽 사진 설명이에요.","연필심이 흑연이에요.","연필, 스마트폰, 배터리예요."],"asset":{"type":"passage","lines":["흑연은 연필뿐만 아니라 스마트폰, 배터리의 원료로 쓰이는 자원이에요.","과거 우리나라는 세계적인 흑연 생산국이었어요.","다른 나라에서 저렴한 흑연을 수입하면서 우리나라에서는 거의 생산하지 않게 됐어요.","우리나라는 수입한 흑연으로 전기차 배터리를 만들어 수출해요.","흑연을 생산하는 나라는 이 배터리를 단 전기차를 수입하기도 해요."],"title":"『사회』 99쪽 — 흑연과 전기차 배터리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#17','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C5',3,'mc','auto','79쪽 자료에서 1990년부터 2000년까지 우리나라의 1인당 국민 총소득은 몇 달러 늘었나요?',ARRAY['SO6-2-u2-X10']::text[],false,'{"seq":17,"concept":"SO6-2-u2-C5","difficulty":3,"kind":"mc","stem":"79쪽 자료에서 1990년부터 2000년까지 우리나라의 1인당 국민 총소득은 몇 달러 늘었나요?","options":[{"t":"4,580달러","correct":true},{"t":"5,580달러","mis":"SO6-2-u2-X10"},{"t":"17,480달러","mis":"SO6-2-u2-X10"}],"explanation":["11,030에서 6,450을 빼요.","받아내림에 주의해요.","4,580달러예요."],"asset":{"type":"passage","lines":["연도 — 1960 · 1970 · 1980 · 1990 · 2000 · 2010 · 2023","우리나라 — 120 · 280 · 1,870 · 6,450 · 11,030 · 22,290 · 35,490","○○ 나라 — 230 · 240 · 770 · 830 · 1,180 · 2,360 · 4,230","(단위: 달러 · 꺾은선그래프를 글로 옮김)"],"numbered":false,"title":"『사회』 79쪽 — 1인당 국민 총소득 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#18','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C9',3,'essay','teacher','단원 평가 15번: 나라 간에 무역이 이루어지는 까닭을 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"SO6-2-u2-C9","difficulty":3,"kind":"essay","stem":"단원 평가 15번: 나라 간에 무역이 이루어지는 까닭을 쓰세요.","answer_guide":{"answer":"나라마다 자연환경, 자원, 자본, 기술 등에 차이가 있어 효율적으로 생산할 수 있는 물자나 서비스가 다르기 때문이에요.","scoring_points":["나라마다 조건이 다름을 썼는가","조건의 예를 들었는가","효율적으로 생산하는 것이 다름을 썼는가"]},"explanation":["나라마다 무엇이 다른가요?","그래서 무엇이 달라지나요?","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#19','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C8',3,'mc','auto','92쪽에서 말한 공유지의 비극이 전 세계에 일어난 사례는 무엇인가요?',ARRAY['SO6-2-u2-X16']::text[],false,'{"seq":19,"concept":"SO6-2-u2-C8","difficulty":3,"kind":"mc","stem":"92쪽에서 말한 공유지의 비극이 전 세계에 일어난 사례는 무엇인가요?","options":[{"t":"지하자원, 공기, 땅, 물을 함부로 써서 환경 오염과 지하자원 부족 문제가 생겼어요","correct":true},{"t":"모두가 규칙을 지켜 물고기가 계속 남았어요","mis":"SO6-2-u2-X16"},{"t":"자원을 아껴 써서 공동의 이익이 늘었어요","mis":"SO6-2-u2-X16"}],"explanation":["함께 쓰는 자원이에요.","함부로 썼어요.","그런 문제가 생겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#20','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C9',3,'mc','auto','우리나라가 타이에 김을 판 일을 타이 쪽에서 보면 무엇인가요?',ARRAY['SO6-2-u2-X17','SO6-2-u2-X18']::text[],false,'{"seq":20,"concept":"SO6-2-u2-C9","difficulty":3,"kind":"mc","stem":"우리나라가 타이에 김을 판 일을 타이 쪽에서 보면 무엇인가요?","options":[{"t":"수입","correct":true},{"t":"수출","mis":"SO6-2-u2-X17"},{"t":"무역이 아니에요","mis":"SO6-2-u2-X18"}],"explanation":["우리나라 쪽에서는 수출이에요.","타이는 사 온 쪽이에요.","타이에게는 수입이에요."],"asset":{"type":"passage","lines":["뉴스 제목 — K-김 수출 1위 시장은 ‘김 과자 큰손’인 이 나라","우리나라 김 수출액이 2023년 약 4,086억 원으로 역대 최고치를 기록했다.","우리나라 김이 가장 많이 수출된 나라는 타이이다.","타이에서 김 과자가 인기를 끌면서 김 수출량도 늘고 있다."],"title":"『사회』 102쪽 디지털+ 할 수 있어요 — 조사한 뉴스 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#21','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C7',3,'mc','auto','빈부 격차가 커지면 어떤 문제가 생길까요?',ARRAY['SO6-2-u2-X26','SO6-2-u2-X12']::text[],false,'{"seq":21,"concept":"SO6-2-u2-C7","difficulty":3,"kind":"mc","stem":"빈부 격차가 커지면 어떤 문제가 생길까요?","options":[{"t":"국민 사이의 갈등이 커지고 사회가 불안정해져 경제성장이 어려워져요","correct":true},{"t":"모든 사람의 소득이 똑같이 늘어요","mis":"SO6-2-u2-X26"},{"t":"경제성장에는 아무 영향이 없어요","mis":"SO6-2-u2-X12"}],"explanation":["86쪽 정보 활용이에요.","갈등이 커져요.","성장도 어려워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#22','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C1',3,'mc','auto','사과 가격이 오를 수 있는 경우는 언제인가요?',ARRAY['SO6-2-u2-X02','SO6-2-u2-X01']::text[],false,'{"seq":22,"concept":"SO6-2-u2-C1","difficulty":3,"kind":"mc","stem":"사과 가격이 오를 수 있는 경우는 언제인가요?","options":[{"t":"사려는 사람이 많아졌는데 시장에 나온 사과는 그대로일 때","correct":true},{"t":"시장에 나온 사과가 크게 늘었을 때","mis":"SO6-2-u2-X02"},{"t":"사과 가게 건물이 바뀌었을 때","mis":"SO6-2-u2-X01"}],"explanation":["사려는 양이 늘었어요.","나온 양은 그대로예요.","그러면 가격이 올라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#23','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C9',4,'essay','teacher','94쪽 교실 물건과 재료의 생산지가 다양한 까닭을 무역의 뜻과 함께 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO6-2-u2-C9","difficulty":4,"kind":"essay","stem":"94쪽 교실 물건과 재료의 생산지가 다양한 까닭을 무역의 뜻과 함께 쓰세요.","answer_guide":{"answer":"예: 무역은 나라와 나라 사이에 물자나 서비스를 사고팔거나 교환하는 일이에요. 우리나라에 없거나 부족한 물자와 재료를 여러 나라에서 수입했기 때문에 생산지가 다양해요.","scoring_points":["무역의 뜻을 썼는가","수입과 이었는가","물건 예를 들었는가"]},"explanation":["무역의 뜻을 써요.","왜 다른 나라 것일까요?","예를 들어요."],"asset":{"type":"passage","lines":["인도네시아에서 자란 나무로 만든 출입문","중국에서 만든 연필","사우디아라비아에서 생산한 원유로 만든 플라스틱 책꽂이","미국에서 만든 프로그램을 사용하는 태블릿","오스트레일리아에서 캐낸 철로 만든 의자","베트남에서 만든 옷"],"title":"『사회』 94쪽 생각을 열어요 — 교실 속 물건과 재료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#24','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C8',4,'essay','teacher','빠른 경제성장으로 발생한 문제 가운데 하나를 골라 실천 계획을 세우세요(무엇을 만들지, 누구에게 소개할지, 모둠의 역할).','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u2-C8","difficulty":4,"kind":"essay","stem":"빠른 경제성장으로 발생한 문제 가운데 하나를 골라 실천 계획을 세우세요(무엇을 만들지, 누구에게 소개할지, 모둠의 역할).","answer_guide":{"answer":"예: 환경 문제의 심각성을 알리는 캠페인 자료를 만들어요. 환경 보호 단체에서 일하시는 분들과 학교 친구들에게 소개해요. 자료 조사, 내용 정리, 발표 자료 만들기로 역할을 나눠요.","scoring_points":["결과물을 정했는가","청중을 정했는가","역할을 나눴는가"]},"explanation":["무엇을 만들까요?","누구에게 보일까요?","역할을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_b#25','soc',6,2,'u2','','tb_g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C7',4,'essay','teacher','86쪽 자료에서 대한민국의 상대적 빈곤율이 몇 %인지 쓰고, 세계 10위의 경제 대국인데도 빈부 격차 문제를 풀어야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u2-C7","difficulty":4,"kind":"essay","stem":"86쪽 자료에서 대한민국의 상대적 빈곤율이 몇 %인지 쓰고, 세계 10위의 경제 대국인데도 빈부 격차 문제를 풀어야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 14.9 %예요. 경제가 성장해도 소득 분배가 고르지 않으면 갈등이 커지고 사회가 불안정해져, 나라가 계속 발전하려면 빈부 격차를 줄여야 하기 때문이에요.","scoring_points":["14.9 %를 바르게 읽었는가","성장과 분배를 나누어 썼는가","풀어야 하는 까닭을 썼는가"]},"explanation":["대한민국 값을 찾아요.","성장했는데 왜 문제일까요?","까닭을 써요."],"asset":{"type":"passage","lines":["(간추림) 1950년대 우리나라는 세계에서 손꼽히게 가난한 나라였다.","빠른 경제성장으로 세계 10위의 경제 대국이 되었고, 2021년 선진국으로 인정받았다.","하지만 OECD 국가 중 상대적 빈곤율이 높은 편이다.","상대적 빈곤율 = 전체 인구 중 빈곤 위험에 처한 인구 비율","2022년(%) 코스타리카 21.2 · 미국 18.1 · 이스라엘 16.8 · 대한민국 14.9","(이어서) 뉴질랜드 14.3 · 에스파냐 13.7 · 캐나다 11.9 · 영국 11.8","(이어서) 프랑스 8.3 · 노르웨이 8.0"],"numbered":false,"title":"『사회』 86쪽 신문 기사 「상대적 빈곤율 OECD 국가 중 높아 … 빈부 격차 심각」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#1','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C1',1,'mc','auto','시장은 어떤 곳인가요?',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C1","difficulty":1,"kind":"mc","stem":"시장은 어떤 곳인가요?","options":[{"t":"물건이나 서비스의 거래가 이루어지는 곳","correct":true},{"t":"살림을 꾸려 가는 생활 공동체","mis":"SO6-2-u2-X03"},{"t":"이윤을 목적으로 생산하는 조직","mis":"SO6-2-u2-X03"}],"explanation":["거래하는 곳이에요.","장소는 상관없어요.","물건이나 서비스의 거래가 이루어지는 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#2','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C11',1,'sa','auto','다른 나라에서 들여오는 상품에 매기는 세금을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u2-C11","difficulty":1,"kind":"sa","stem":"다른 나라에서 들여오는 상품에 매기는 세금을 두 글자로 쓰세요.","answer":["관세"],"explanation":["108쪽이에요.","수입품에 매겨요.","관세예요."],"mis":"SO6-2-u2-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#3','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C9',1,'mc','auto','단원 도입 ④의 말로 알 수 있는 ○○ 회사 컨테이너 속 물건은 무엇인가요?',ARRAY['SO6-2-u2-X18']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"mc","stem":"단원 도입 ④의 말로 알 수 있는 ○○ 회사 컨테이너 속 물건은 무엇인가요?","options":[{"t":"밀가루","correct":true},{"t":"바나나","mis":"SO6-2-u2-X18"},{"t":"포도주","mis":"SO6-2-u2-X18"}],"explanation":["④를 봐요.","트럭으로 옮기는 물건이에요.","밀가루예요."],"asset":{"type":"passage","lines":["미션 — ○○ 회사의 컨테이너를 찾아요.","① 이 컨테이너(포도주·키위·치즈)에 있는 물건 중에 찾으시는 물건은 없어요.","② 찾으시는 컨테이너 안을 잠깐 봤는데 소고기가 실려 있는 것 같던데요.","③ 이 컨테이너(바나나·오렌지)의 과일 하나가 그 컨테이너에도 있어요.","④ 그 컨테이너 속 물건 하나(밀가루)를 제가 지금 트럭으로 운반하고 있어요."],"numbered":false,"title":"『사회』 56~57쪽 단원 도입 — 네 사람의 말(그림 속 물건은 괄호로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#4','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C9',1,'mc','auto','「시장경제와 국가 간 거래」 단원의 세 번째 주제는 무엇인가요?',ARRAY['SO6-2-u2-X10','SO6-2-u2-X01']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"mc","stem":"「시장경제와 국가 간 거래」 단원의 세 번째 주제는 무엇인가요?","options":[{"t":"세계 속의 무역","correct":true},{"t":"경제성장과 우리 생활","mis":"SO6-2-u2-X10"},{"t":"우리나라 시장경제의 특징","mis":"SO6-2-u2-X01"}],"explanation":["58쪽 주제 셋째예요.","무역을 배워요.","세계 속의 무역이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#5','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C11',1,'ox','auto','자유롭게 무역을 하면 모든 나라의 경제가 나빠져요.',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C11","difficulty":1,"kind":"ox","stem":"자유롭게 무역을 하면 모든 나라의 경제가 나빠져요.","answer":"X","reason_options":[{"t":"각 나라가 잘하는 것을 사고팔아 서로 이익을 얻을 수 있기 때문에","correct":true},{"t":"무역은 한 나라만 이익을 보기 때문에","mis":"SO6-2-u2-X20"}],"mis":"SO6-2-u2-X20","explanation":["111쪽 틀린 설명이에요.","서로 이익을 얻어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#6','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C11',1,'blank','auto','생각 그물: 세계 여러 나라는 첨단 기술을 (    )하기 위해 경쟁해요. 빈칸에 알맞은 말은?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C11","difficulty":1,"kind":"blank","stem":"생각 그물: 세계 여러 나라는 첨단 기술을 (    )하기 위해 경쟁해요. 빈칸에 알맞은 말은?","options":[{"t":"개발","correct":true},{"t":"수입","mis":"SO6-2-u2-X20"},{"t":"금지","mis":"SO6-2-u2-X20"}],"explanation":["경쟁 셋 가운데 하나예요.","새 기술을 만들어요.","개발이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#7','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C4',1,'mc','auto','77쪽 「재미있게 확인해요」에서 옳은 설명을 한 가게의 말은 무엇인가요?',ARRAY['SO6-2-u2-X03','SO6-2-u2-X08']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C4","difficulty":1,"kind":"mc","stem":"77쪽 「재미있게 확인해요」에서 옳은 설명을 한 가게의 말은 무엇인가요?","options":[{"t":"우리나라에서는 가계와 기업이 시장에서 자유롭게 경쟁하면서 경제활동을 할 수 있어요","correct":true},{"t":"기업은 가계의 생산 활동에 참여해 소득을 얻어요","mis":"SO6-2-u2-X03"},{"t":"기업은 어떤 상품을 얼마나 생산할지 자유롭게 정할 수 없어요","mis":"SO6-2-u2-X08"}],"explanation":["기업의 자유를 떠올려요.","자유로운 경쟁이 맞아요.","그 가게예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#8','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C11',1,'mc','auto','110쪽 관세사가 하는 일은 무엇인가요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C11","difficulty":1,"kind":"mc","stem":"110쪽 관세사가 하는 일은 무엇인가요?","options":[{"t":"개인이나 기업을 대신해 법에 정해진 절차에 따라 수출입 업무를 처리해요","correct":true},{"t":"공장에서 철강을 만들어요","mis":"SO6-2-u2-X20"},{"t":"기업의 광고를 만들어요","mis":"SO6-2-u2-X20"}],"explanation":["관세와 관련된 일이에요.","수출입 법 지식이 필요해요.","수출입 업무를 처리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#9','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C2',2,'mc','auto','단원 평가 5번: ㉠, ㉡에 들어갈 말을 알맞게 짝지은 것은 무엇인가요?',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"mc","stem":"단원 평가 5번: ㉠, ㉡에 들어갈 말을 알맞게 짝지은 것은 무엇인가요?","options":[{"t":"㉠ 물건이나 서비스 · ㉡ 노동력","correct":true},{"t":"㉠ 이윤 · ㉡ 물건이나 서비스","mis":"SO6-2-u2-X03"},{"t":"㉠ 소득 · ㉡ 물건이나 서비스","mis":"SO6-2-u2-X03"},{"t":"㉠ 지출 · ㉡ 물건이나 서비스","mis":"SO6-2-u2-X03"},{"t":"㉠ 노동력 · ㉡ 이윤","mis":"SO6-2-u2-X03"}],"explanation":["㉡은 가계가 기업에 줘요.","가계는 노동력을 줘요.","㉠ 물건이나 서비스 · ㉡ 노동력이에요."],"asset":{"type":"passage","lines":["그림 — 가계와 기업이 가운데의 시장을 사이에 두고 마주 있어요.","㉠ 위쪽 화살표: 기업 → 가계","㉡ 아래쪽 화살표: 가계 → 기업"],"numbered":false,"title":"단원 평가 5번(그림을 글로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#10','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C6',2,'mc','auto','단원 평가 11번처럼 경제성장이 우리 생활에 미치는 영향으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u2-X12','SO6-2-u2-X13']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C6","difficulty":2,"kind":"mc","stem":"단원 평가 11번처럼 경제성장이 우리 생활에 미치는 영향으로 알맞은 것은 무엇인가요?","options":[{"t":"교육의 질이 높아지고 디지털 기기를 활용한 수업이 늘었어요","correct":true},{"t":"새로운 일자리가 줄어 국민의 소득이 감소했어요","mis":"SO6-2-u2-X12"},{"t":"수준 높은 의료 혜택으로 기대 수명이 줄어들었어요","mis":"SO6-2-u2-X13"},{"t":"문화 산업이 경제성장에 미치는 영향이 줄었어요","mis":"SO6-2-u2-X13"}],"explanation":["83쪽이에요.","교육의 질이 높아졌어요.","그 설명이 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#11','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C11',2,'mc','auto','단원 평가 19번: 무역을 통한 세계 여러 나라의 경쟁 관계를 보기에서 골라 알맞게 짝지은 것은 무엇인가요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":11,"concept":"SO6-2-u2-C11","difficulty":2,"kind":"mc","stem":"단원 평가 19번: 무역을 통한 세계 여러 나라의 경쟁 관계를 보기에서 골라 알맞게 짝지은 것은 무엇인가요?","options":[{"t":"㉢, ㉣","correct":true},{"t":"㉠, ㉡","mis":"SO6-2-u2-X20"},{"t":"㉠, ㉢","mis":"SO6-2-u2-X20"},{"t":"㉡, ㉢","mis":"SO6-2-u2-X20"},{"t":"㉡, ㉣","mis":"SO6-2-u2-X20"}],"explanation":["㉠·㉡은 상호 의존이에요.","㉢·㉣은 서로 앞서려 해요.","㉢, ㉣이에요."],"asset":{"type":"passage","lines":["㉠ 여러 나라의 우수한 물자를 한데 모아서 새로운 제품을 생산하기도 합니다.","㉡ 여러 나라가 각자 잘하는 분야를 중심으로 함께 사업을 진행하기도 합니다.","㉢ 더 나은 품질의 생성형 인공지능 제품을 개발해서 수출하려 노력합니다.","㉣ 철도, 도로, 발전소 등 다른 나라의 주요 시설을 서로 건설하려고 노력합니다."],"numbered":false,"title":"단원 평가 19번 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#12','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C10',2,'mc','auto','104쪽 싱가포르에서 발달한 무역의 모습은 무엇인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":12,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"mc","stem":"104쪽 싱가포르에서 발달한 무역의 모습은 무엇인가요?","options":[{"t":"여러 나라에서 생산한 상품을 모아 필요한 나라에 다시 파는 무역","correct":true},{"t":"원유를 캐서 파는 무역","mis":"SO6-2-u2-X19"},{"t":"쌀을 재배해 파는 무역","mis":"SO6-2-u2-X19"}],"explanation":["큰 항구에 상품이 모여요.","다시 팔아요.","그 무역이에요."],"asset":{"type":"passage","lines":["싱가포르는 서울보다 약간 넓은 나라로, 유럽과 아시아를 잇는 항로에 자리 잡고 있어요.","정부는 이곳을 지나는 선박이 머물 수 있도록 큰 항구를 만들었어요.","여러 나라에서 생산한 상품이 모였고, 이를 필요한 나라에 다시 파는 무역이 발달했어요.","무역과 관련한 여러 은행과 기업이 활동하며 더욱 무역하기 좋은 나라가 됐어요."],"title":"『사회』 104쪽 스스로 활동 — 싱가포르"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#13','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C7',2,'mc','auto','87쪽처럼 저임금과 노사 갈등이 생기는 까닭은 무엇인가요?',ARRAY['SO6-2-u2-X07','SO6-2-u2-X14']::text[],false,'{"seq":13,"concept":"SO6-2-u2-C7","difficulty":2,"kind":"mc","stem":"87쪽처럼 저임금과 노사 갈등이 생기는 까닭은 무엇인가요?","options":[{"t":"근로자는 노력에 비해 임금이 낮다고 여기고, 기업은 임금이 늘면 비용이 늘어서","correct":true},{"t":"근로자와 기업은 서로 아무 관계가 없어서","mis":"SO6-2-u2-X07"},{"t":"임금은 언제나 나라가 정해서","mis":"SO6-2-u2-X14"}],"explanation":["두 쪽의 처지를 봐요.","임금과 비용이 부딪혀요.","그래서 갈등이 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#14','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C1',2,'mc','auto','중고 물품 온라인 쇼핑몰이나 주식 거래소도 시장이라고 할 수 있는 까닭은 무엇인가요?',ARRAY['SO6-2-u2-X01','SO6-2-u2-X02']::text[],false,'{"seq":14,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"mc","stem":"중고 물품 온라인 쇼핑몰이나 주식 거래소도 시장이라고 할 수 있는 까닭은 무엇인가요?","options":[{"t":"물건이나 서비스의 거래가 이루어지기 때문이에요","correct":true},{"t":"건물이 크기 때문이에요","mis":"SO6-2-u2-X01"},{"t":"나라가 가격을 정해 주기 때문이에요","mis":"SO6-2-u2-X02"}],"explanation":["장소와 상관없어요.","거래가 이루어져요.","그래서 시장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#15','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C11',2,'match','auto','사례와 그 사례가 보여 주는 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SO6-2-u2-C11","difficulty":2,"kind":"match","stem":"사례와 그 사례가 보여 주는 모습을 알맞게 이으세요.","pairs":[{"l":"상호 의존","r":"한국과 인도네시아의 핵심 광물 공동 연구"},{"l":"경쟁","r":"자동화 항만 시스템을 갖춘 부산항"},{"l":"국내 산업 보호","r":"1970년대 수입 철강 제품에 높은 관세 부과"}],"mis":"SO6-2-u2-X20","explanation":["함께 연구는 의존이에요.","항만은 경쟁이에요.","관세는 국내 산업 보호예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#16','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C12',2,'mc','auto','112~113쪽 예시 기업의 △△ 게임 주요 수출국은 어디인가요?',ARRAY['SO6-2-u2-X21']::text[],false,'{"seq":16,"concept":"SO6-2-u2-C12","difficulty":2,"kind":"mc","stem":"112~113쪽 예시 기업의 △△ 게임 주요 수출국은 어디인가요?","options":[{"t":"중국, 인도","correct":true},{"t":"독일, 일본","mis":"SO6-2-u2-X21"},{"t":"수출하지 않고 우리나라에서만 팔아요","mis":"SO6-2-u2-X21"}],"explanation":["예시 표를 봐요.","두 나라예요.","중국, 인도예요."],"asset":{"type":"passage","lines":["대표 상품 — △△ 게임(온라인 게임)","상품의 특징 — 여러 가지 캐릭터가 등장해 다양한 과제를 해결하며 성장해 나가요.","주요 수출국 — 중국, 인도","사회적 책임 목표 — 전 세계인이 구입하는 1등 게임을 개발하여 지속가능한 성장을 해요.","근로자 권리 보호 — 성과가 높은 근로자에게 성과급·임금 인상, 휴가 보장"],"title":"『사회』 112~113쪽 생각을 펼쳐요 — 기업 운영 계획 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#17','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C5',3,'sa','auto','79쪽 자료의 연도 가운데 우리나라의 1인당 국민 총소득이 처음으로 1만 달러를 넘은 해는 언제인가요?','{}'::text[],false,'{"seq":17,"concept":"SO6-2-u2-C5","difficulty":3,"kind":"sa","stem":"79쪽 자료의 연도 가운데 우리나라의 1인당 국민 총소득이 처음으로 1만 달러를 넘은 해는 언제인가요?","answer":["2000년","2000"],"explanation":["1만은 10,000이에요.","1990년은 6,450이에요.","2000년이에요."],"asset":{"type":"passage","lines":["연도 — 1960 · 1970 · 1980 · 1990 · 2000 · 2010 · 2023","우리나라 — 120 · 280 · 1,870 · 6,450 · 11,030 · 22,290 · 35,490","○○ 나라 — 230 · 240 · 770 · 830 · 1,180 · 2,360 · 4,230","(단위: 달러 · 꺾은선그래프를 글로 옮김)"],"numbered":false,"title":"『사회』 79쪽 — 1인당 국민 총소득 변화"},"mis":"SO6-2-u2-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#18','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C4',3,'essay','teacher','기업이 계속해서 사회적 책임을 다한다면 우리 사회에 어떤 변화가 있을지 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"essay","stem":"기업이 계속해서 사회적 책임을 다한다면 우리 사회에 어떤 변화가 있을지 쓰세요.","answer_guide":{"answer":"예: 기업이 지역과 함께 성장하고 발전해 경제가 성장하고 사회가 발전하며, 더 살기 좋은 사회가 될 거예요.","scoring_points":["경제 성장을 썼는가","사회 발전을 썼는가","책임과 변화를 이었는가"]},"explanation":["75쪽 정보 활용이에요.","경제와 사회를 함께 봐요.","변화를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#19','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C8',3,'ox','auto','공유지의 비극을 막으려면 규칙만 있으면 되고 사람들의 태도는 필요 없어요.',ARRAY['SO6-2-u2-X16']::text[],false,'{"seq":19,"concept":"SO6-2-u2-C8","difficulty":3,"kind":"ox","stem":"공유지의 비극을 막으려면 규칙만 있으면 되고 사람들의 태도는 필요 없어요.","answer":"X","reason_options":[{"t":"자원을 소중히 여기고 공동의 이익을 추구하는 태도와 노력이 뒷받침돼야 하기 때문에","correct":true},{"t":"규칙이 있으면 모두 저절로 지키기 때문에","mis":"SO6-2-u2-X16"}],"mis":"SO6-2-u2-X16","explanation":["92쪽 마지막 문장이에요.","태도도 필요해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#20','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C10',3,'mc','auto','활동지 기사 ②에서 인도네시아가 설탕을 사 오는 나라를 바꾼 까닭은 무엇인가요?',ARRAY['SO6-2-u2-X19','SO6-2-u2-X18']::text[],false,'{"seq":20,"concept":"SO6-2-u2-C10","difficulty":3,"kind":"mc","stem":"활동지 기사 ②에서 인도네시아가 설탕을 사 오는 나라를 바꾼 까닭은 무엇인가요?","options":[{"t":"기후변화로 가까운 나라들의 설탕 생산량이 줄어서","correct":true},{"t":"브라질이 가장 가까운 나라라서","mis":"SO6-2-u2-X19"},{"t":"설탕을 더 이상 쓰지 않아서","mis":"SO6-2-u2-X18"}],"explanation":["가뭄이 있었어요.","인도·타이도 줄었어요.","그래서 브라질로 바꿨어요."],"asset":{"type":"passage","lines":["기사 ① 상반기 화장품 수출이 48억 2천만 달러로 사상 최대를 기록했다.","기사 ① 한류와 함께 K-뷰티에 관한 관심과 인기가 높아졌기 때문이다.","기사 ② 인도네시아는 가뭄으로 설탕이 부족해지자 브라질산 설탕을 수입하기로 했다.","기사 ② 주로 수입하던 가까운 인도와 타이도 날씨 탓에 생산량이 줄었기 때문이다."],"title":"활동지 — 두 신문 기사(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#21','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C5',3,'mc','auto','연설문 (가)에서 1962년 우리나라 수출품의 대부분은 무엇이었나요?',ARRAY['SO6-2-u2-X11']::text[],false,'{"seq":21,"concept":"SO6-2-u2-C5","difficulty":3,"kind":"mc","stem":"연설문 (가)에서 1962년 우리나라 수출품의 대부분은 무엇이었나요?","options":[{"t":"농산물과 광산물","correct":true},{"t":"반도체","mis":"SO6-2-u2-X11"},{"t":"웹툰과 게임","mis":"SO6-2-u2-X11"}],"explanation":["1962년이에요.","5천여만 달러였어요.","농산물과 광산물이에요."],"asset":{"type":"passage","lines":["(가) 드디어 우리는 수출 100억 달러를 돌파했습니다.","(가) 1962년만 해도 수출 실적은 겨우 5천여만 달러, 대부분 농산물·광산물이었습니다.","(가) 중화학 공업은 선진국 수준으로 발전해 가고 있습니다.","(나) 올해 대한민국의 수출은 6,300억 달러를 돌파하여 사상 최대입니다.","(나) 메모리 반도체는 세계 1위, 조선·석유 화학도 크게 늘었습니다.","(나) 문화 콘텐츠 수출이 3년 연속 100억 달러를 넘었습니다."],"numbered":false,"title":"활동지 — 대통령 연설문 두 편(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#22','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C3',3,'mc','auto','우리나라가 근로자의 권리를 보호하려고 법과 제도를 만든 까닭은 무엇인가요?',ARRAY['SO6-2-u2-X06','SO6-2-u2-X07']::text[],false,'{"seq":22,"concept":"SO6-2-u2-C3","difficulty":3,"kind":"mc","stem":"우리나라가 근로자의 권리를 보호하려고 법과 제도를 만든 까닭은 무엇인가요?","options":[{"t":"근로자가 권리를 보호받으면 성실히 일하고 기업도 목표를 이룰 수 있어서","correct":true},{"t":"기업이 알아서 지켜 주니 필요 없어서","mis":"SO6-2-u2-X06"},{"t":"근로자만 혜택을 보게 하려고","mis":"SO6-2-u2-X07"}],"explanation":["71쪽이에요.","근로자와 기업 모두에게 좋아요.","그래서 만들었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#23','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C4',4,'essay','teacher','76쪽처럼 기업이 「환경」, 「사회」, 「투명 경영」을 중요한 가치로 삼는 까닭을 쓰고, 각 가치를 실천하는 모습을 하나씩 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO6-2-u2-C4","difficulty":4,"kind":"essay","stem":"76쪽처럼 기업이 「환경」, 「사회」, 「투명 경영」을 중요한 가치로 삼는 까닭을 쓰고, 각 가치를 실천하는 모습을 하나씩 쓰세요.","answer_guide":{"answer":"예: 경제가 성장하며 기업이 사회에 미치는 영향이 커졌기 때문이에요. 환경 — 태양광 패널 설치, 사회 — 지역 벽화 가꾸기, 투명 경영 — 근로자와 소통하기.","scoring_points":["까닭을 썼는가","세 가치의 모습을 썼는가","모습과 가치를 바르게 짝지었는가"]},"explanation":["왜 커졌나요?","세 가치를 나눠요.","모습을 하나씩 써요."],"asset":{"type":"passage","lines":["사진 ① 공장 지붕에 태양광 패널을 설치해 친환경 에너지 사용을 늘립니다.","사진 ② 기업을 투명하게 운영하려고 기업과 근로자가 함께 힘을 모읍니다.","사진 ③ 기업 직원들이 벽화 작업을 하며 지역을 아름답게 가꿉니다."],"title":"『사회』 76쪽 — 기업의 사회적 책임이 커졌어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#24','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C1',4,'essay','teacher','시장경제에서 가계, 기업, 시장의 관계를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u2-C1","difficulty":4,"kind":"essay","stem":"시장경제에서 가계, 기업, 시장의 관계를 쓰세요.","answer_guide":{"answer":"예: 시장은 가계와 기업이 만나 필요한 것을 주고받게 해 줘요. 가계는 노동력을 제공하고 소득을 얻어 물건을 사고, 기업은 물건을 팔아 이윤을 얻어요. 셋은 밀접한 관계를 맺고 도움을 주고받아요.","scoring_points":["시장의 역할을 썼는가","가계와 기업이 주고받는 것을 썼는가","밀접한 관계임을 밝혔는가"]},"explanation":["시장은 무엇을 하나요?","가계와 기업은 무엇을 주고받나요?","관계로 정리해요."],"asset":{"type":"passage","lines":["가계 → 기업 : (  ㉠  )","기업 → 가계 : 소득","기업 → 시장 : 물건이나 서비스","시장 → 기업 : (  ㉡  )","시장 → 가계 : 물건이나 서비스"],"title":"『사회』 67쪽 — 가계, 기업, 시장의 관계(붙임딱지 두 칸 비움)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_c#25','soc',6,2,'u2','','tb_g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C9',4,'essay','teacher','「스파이를 찾아라」 놀이처럼 「무역이 이루어지는 까닭」 카드에 쓸 사실인 문장 둘과 거짓인 문장 하나를 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u2-C9","difficulty":4,"kind":"essay","stem":"「스파이를 찾아라」 놀이처럼 「무역이 이루어지는 까닭」 카드에 쓸 사실인 문장 둘과 거짓인 문장 하나를 쓰세요.","answer_guide":{"answer":"예: 사실 — 나라마다 자연환경과 자원이 달라 잘 만드는 것이 달라요. 사실 — 나라 안에서 구할 수 있어도 더 값싸면 수입하기도 해요. 거짓 — 모든 것을 잘 만드는 나라는 무역하지 않아요.","scoring_points":["사실인 문장 둘을 바르게 썼는가","거짓인 문장 하나를 썼는가","교과서 내용에 근거했는가"]},"explanation":["배운 사실을 떠올려요.","거짓은 흔한 잘못 생각으로요.","세 문장을 써요."],"asset":{"type":"passage","lines":["카드 ① 무역이란 나라 사이에 물자나 서비스를 사고파는 것입니다.","카드 ② 다른 나라에 물자나 서비스를 파는 것을 수입이라고 합니다.","카드 ③ 무역을 통해 부족한 물자나 서비스를 다른 나라로부터 구할 수 있습니다.","카드 ④ 나라마다 효율적으로 생산하는 물자나 서비스가 달라 무역이 필요합니다."],"title":"『사회』 116~117쪽 교실 놀이 「스파이를 찾아라」 — 한 모둠의 문장 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#1','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C2',1,'mc','auto','가계가 기업에 제공하고 그 대가로 소득을 얻는 것은 무엇인가요?',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C2","difficulty":1,"kind":"mc","stem":"가계가 기업에 제공하고 그 대가로 소득을 얻는 것은 무엇인가요?","options":[{"t":"노동력","correct":true},{"t":"이윤","mis":"SO6-2-u2-X03"},{"t":"세금","mis":"SO6-2-u2-X03"}],"explanation":["일하는 힘이에요.","기업은 그 대가로 소득을 줘요.","노동력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#2','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C10',1,'sa','auto','단원 평가 18번: 무역에 유리한 (    ) 위치를 이용해서 무역이 발달한 나라도 있어요. 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u2-C10","difficulty":1,"kind":"sa","stem":"단원 평가 18번: 무역에 유리한 (    ) 위치를 이용해서 무역이 발달한 나라도 있어요. 빈칸에 알맞은 말을 쓰세요.","answer":["지리적"],"explanation":["위치와 관계있어요.","싱가포르를 떠올려요.","지리적이에요."],"mis":"SO6-2-u2-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#3','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C9',1,'mc','auto','네 사람의 말을 모두 따지면 ○○ 회사의 컨테이너에 든 물건은 무엇인가요?',ARRAY['SO6-2-u2-X18']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"mc","stem":"네 사람의 말을 모두 따지면 ○○ 회사의 컨테이너에 든 물건은 무엇인가요?","options":[{"t":"소고기, 오렌지, 밀가루","correct":true},{"t":"포도주, 키위, 치즈","mis":"SO6-2-u2-X18"},{"t":"소고기, 키위, 밀가루","mis":"SO6-2-u2-X18"}],"explanation":["키위는 ①에서 빠져요.","소고기·밀가루는 ②·④예요.","소고기, 오렌지, 밀가루예요."],"asset":{"type":"passage","lines":["미션 — ○○ 회사의 컨테이너를 찾아요.","① 이 컨테이너(포도주·키위·치즈)에 있는 물건 중에 찾으시는 물건은 없어요.","② 찾으시는 컨테이너 안을 잠깐 봤는데 소고기가 실려 있는 것 같던데요.","③ 이 컨테이너(바나나·오렌지)의 과일 하나가 그 컨테이너에도 있어요.","④ 그 컨테이너 속 물건 하나(밀가루)를 제가 지금 트럭으로 운반하고 있어요."],"numbered":false,"title":"『사회』 56~57쪽 단원 도입 — 네 사람의 말(그림 속 물건은 괄호로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#4','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C9',1,'mc','auto','54~55쪽 항구의 두 사람은 운반할 물건이 많아진 까닭을 무엇이라고 했나요?',ARRAY['SO6-2-u2-X18']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"mc","stem":"54~55쪽 항구의 두 사람은 운반할 물건이 많아진 까닭을 무엇이라고 했나요?","options":[{"t":"경제활동이 활발해지면서 다른 나라와 교류가 더 활발해져서","correct":true},{"t":"다른 나라와 교류가 끊겨서","mis":"SO6-2-u2-X18"},{"t":"컨테이너가 모두 사라져서","mis":"SO6-2-u2-X18"}],"explanation":["항구 직원의 말이에요.","교류가 활발해졌어요.","그래서 물건이 늘었어요."],"asset":{"type":"speech","turns":[{"who":"항구 직원","text":"운반해야 하는 물건이 많이 늘어나서 힘드시죠? 요즘 경제활동이 활발해지면서 다른 나라와 교류가 더 활발해졌어요."},{"who":"트럭 운전자","text":"어쩐지 요즘 운반해야 할 물건이 많더라고요. 운반해야 할 컨테이너는 어디에 있을까요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#5','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C10',1,'ox','auto','우리나라는 원료를 수입한 후 상품을 생산하여 수출하는 무역이 발달했어요.',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C10","difficulty":1,"kind":"ox","stem":"우리나라는 원료를 수입한 후 상품을 생산하여 수출하는 무역이 발달했어요.","answer":"O","reason_options":[{"t":"천연자원은 부족하지만 기술이 발달했기 때문에","correct":true},{"t":"우리나라는 천연자원이 풍부하기 때문에","mis":"SO6-2-u2-X19"}],"mis":"SO6-2-u2-X19","explanation":["111쪽 옳은 설명이에요.","수입 → 생산 → 수출이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#6','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C9',1,'blank','auto','생각 그물: 나라마다 (    ), 자원, 자본, 기술 등에 차이가 있어 무역이 이루어져요. 빈칸에 알맞은 말은?',ARRAY['SO6-2-u2-X18']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"blank","stem":"생각 그물: 나라마다 (    ), 자원, 자본, 기술 등에 차이가 있어 무역이 이루어져요. 빈칸에 알맞은 말은?","options":[{"t":"자연환경","correct":true},{"t":"언어","mis":"SO6-2-u2-X18"},{"t":"국경일","mis":"SO6-2-u2-X18"}],"explanation":["무역의 까닭이에요.","땅과 기후 같은 것이에요.","자연환경이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#7','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C11',1,'mc','auto','111쪽 「재미있게 확인해요」에서 옳은 설명은 무엇인가요?',ARRAY['SO6-2-u2-X22','SO6-2-u2-X20']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C11","difficulty":1,"kind":"mc","stem":"111쪽 「재미있게 확인해요」에서 옳은 설명은 무엇인가요?","options":[{"t":"세계 여러 나라는 무역을 통해 상호 의존과 경쟁을 하고 있어요","correct":true},{"t":"한 나라 안에서 구할 수 있는 물자는 수입하지 않아요","mis":"SO6-2-u2-X22"},{"t":"자유롭게 무역을 하면 모든 나라 경제가 나빠져요","mis":"SO6-2-u2-X20"}],"explanation":["의존과 경쟁을 배웠어요.","나머지는 틀린 설명이에요.","그 설명이 옳아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#8','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C10',1,'mc','auto','105쪽에서 대한민국 서울에서 열리는 박람회는 무엇인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C10","difficulty":1,"kind":"mc","stem":"105쪽에서 대한민국 서울에서 열리는 박람회는 무엇인가요?","options":[{"t":"세계 문구 박람회","correct":true},{"t":"세계 가전 박람회","mis":"SO6-2-u2-X19"},{"t":"세계 완구 박람회","mis":"SO6-2-u2-X19"}],"explanation":["서울을 찾아요.","문구가 주제예요.","세계 문구 박람회예요."],"asset":{"type":"passage","lines":["박람회 — 일정한 기간과 장소를 정해 놓고 다양한 물품을 전시하는 행사","판매자가 홍보관을 운영하고, 판매자와 소비자가 직접 묻고 답해요.","세계 가전 박람회 — 미국 라스베이거스","세계 문구 박람회 — 대한민국 서울","세계 완구 박람회 — 독일 뉘른베르크"],"title":"『사회』 105쪽 풍덩! 사회 속으로 — 박람회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#9','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C4',2,'mc','auto','단원 평가 7번: 기업의 자유로운 경제활동에 관한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"mc","stem":"단원 평가 7번: 기업의 자유로운 경제활동에 관한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"기업의 경제활동이 활발해지면 국가 전체의 경제 발전에 도움이 돼요","correct":true},{"t":"큰 비용으로 적은 이윤을 얻도록 노력해요","mis":"SO6-2-u2-X08"},{"t":"어떤 상품을 생산할지 국가의 결정에 따라요","mis":"SO6-2-u2-X08"},{"t":"우리나라는 기업의 자유에 관한 법이 없어요","mis":"SO6-2-u2-X08"},{"t":"우리나라에서는 기업이 다른 기업과 자유롭게 경쟁할 수 없어요","mis":"SO6-2-u2-X08"}],"explanation":["72쪽이에요.","경제 발전에 도움이 돼요.","그 설명이 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#10','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C8',2,'mc','auto','단원 평가 13번: 빠른 경제성장으로 발생한 문제를 해결하기 위한 노력으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO6-2-u2-X15']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C8","difficulty":2,"kind":"mc","stem":"단원 평가 13번: 빠른 경제성장으로 발생한 문제를 해결하기 위한 노력으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"경제적으로 부유한 사람들을 지원하는 정책 마련하기","correct":true},{"t":"환경 보호 캠페인 벌이기","mis":"SO6-2-u2-X15"},{"t":"에너지 절약 운동 실천하기","mis":"SO6-2-u2-X15"},{"t":"오염 물질 배출 금지 관련 법 만들기","mis":"SO6-2-u2-X15"},{"t":"근로자와 기업이 서로 소통하는 기회 마련하기","mis":"SO6-2-u2-X15"}],"explanation":["빈부 격차를 떠올려요.","부유한 사람만 도우면 격차가 커져요.","그것이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#11','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C11',2,'mc','auto','단원 평가 20번: 무역을 통한 상호 의존과 경쟁 관계에 관한 설명으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO6-2-u2-X20','SO6-2-u2-X23']::text[],false,'{"seq":11,"concept":"SO6-2-u2-C11","difficulty":2,"kind":"mc","stem":"단원 평가 20번: 무역을 통한 상호 의존과 경쟁 관계에 관한 설명으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"수입이 늘어나면 국내 관련 산업이 피해를 입는 일이 줄어들어요","correct":true},{"t":"무역이 활발해지면서 세계 여러 나라는 물자와 서비스를 자유롭게 거래해요","mis":"SO6-2-u2-X20"},{"t":"수출이 늘어나면 더 많이 생산해야 하므로 산업이 성장해요","mis":"SO6-2-u2-X20"},{"t":"기업들은 물자를 생산하는 데 유리한 환경을 갖춘 나라에서 경제활동을 하기도 해요","mis":"SO6-2-u2-X20"},{"t":"세계 여러 나라는 국내 산업을 보호하려고 수입품에 관세를 부과하기도 해요","mis":"SO6-2-u2-X23"}],"explanation":["수입이 늘면 어떻게 되나요?","국내 산업이 피해를 입을 수 있어요.","줄어든다는 말이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#12','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C10',2,'mc','auto','세계적인 무역항을 갖춘 도시 가운데 대한민국에 있는 것은 무엇인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":12,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"mc","stem":"세계적인 무역항을 갖춘 도시 가운데 대한민국에 있는 것은 무엇인가요?","options":[{"t":"부산항","correct":true},{"t":"상하이","mis":"SO6-2-u2-X19"},{"t":"로테르담","mis":"SO6-2-u2-X19"},{"t":"로스앤젤레스","mis":"SO6-2-u2-X19"}],"explanation":["104쪽 말풍선이에요.","대한민국의 항구예요.","부산항이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#13','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C8',2,'mc','auto','91쪽에서 시민 단체와 개인이 하는 노력은 무엇인가요?',ARRAY['SO6-2-u2-X15']::text[],false,'{"seq":13,"concept":"SO6-2-u2-C8","difficulty":2,"kind":"mc","stem":"91쪽에서 시민 단체와 개인이 하는 노력은 무엇인가요?","options":[{"t":"해변의 쓰레기를 주워 환경을 보호해요","correct":true},{"t":"다양한 제도와 정책을 만들어요","mis":"SO6-2-u2-X15"},{"t":"기업과 임금을 협의해요","mis":"SO6-2-u2-X15"}],"explanation":["시민 단체와 개인이에요.","생활 속 실천이에요.","쓰레기를 주워요."],"asset":{"type":"passage","lines":["정부 — 다양한 제도와 정책을 만들어요(더 나은 일자리를 제공하려는 노력).","기업과 근로자 — 서로 소통하며 더 나은 근로 환경을 만들어요(노사 갈등을 풀려는 노력).","시민 단체와 개인 — 해변의 쓰레기를 주워 환경을 보호하고, 에너지를 절약해요."],"title":"『사회』 91쪽 — 빠른 경제성장으로 발생한 문제를 해결하려는 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#14','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C2',2,'mc','auto','기업이 더 많은 이윤을 얻으려고 기울이는 노력은 나라 경제에 어떤 영향을 줄까요?',ARRAY['SO6-2-u2-X04']::text[],false,'{"seq":14,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"mc","stem":"기업이 더 많은 이윤을 얻으려고 기울이는 노력은 나라 경제에 어떤 영향을 줄까요?","options":[{"t":"기술이 발전해 상품 경쟁력이 좋아지고 판매량이 늘어 나라 경제 발전에 도움이 돼요","correct":true},{"t":"나라 경제와는 상관없어요","mis":"SO6-2-u2-X04"},{"t":"가계의 일자리가 줄기만 해요","mis":"SO6-2-u2-X04"}],"explanation":["66쪽이에요.","경쟁력과 판매량이 늘어요.","나라 경제에 도움이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#15','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C2',2,'match','auto','63쪽 가족의 일과와 경제활동을 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"match","stem":"63쪽 가족의 일과와 경제활동을 알맞게 이으세요.","pairs":[{"l":"오전 10시","r":"일터에서 일하며 생산 활동에 참여해요"},{"l":"오후 5시","r":"자동차 판매점에서 살 물건을 살펴봐요"},{"l":"오후 10시","r":"저축에 관해 의논해요"}],"mis":"SO6-2-u2-X04","explanation":["오전엔 일해요.","오후 5시엔 물건을 봐요.","밤엔 저축을 의논해요."],"asset":{"type":"passage","lines":["오전 10시 — 부모님이 각자 일터에서 일해요.","오후 5시 — 자동차 판매점에서 가족에게 필요한 차를 살펴봐요.","오후 7시 — 가족이 모여 함께 저녁을 먹어요.","오후 10시 — 부모님이 저축에 관해 의논해요.","(말풍선) 은행에 저축을 해서 이자를 받아 소득을 얻을 수도 있어요."],"numbered":false,"title":"『사회』 63쪽 — 어느 가족의 일과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#16','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C8',2,'mc','auto','해결 방안을 고를 때 세우는 평가 기준으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u2-X15']::text[],false,'{"seq":16,"concept":"SO6-2-u2-C8","difficulty":2,"kind":"mc","stem":"해결 방안을 고를 때 세우는 평가 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"비용이 적게 드나요?","correct":true},{"t":"먼저 말한 친구의 방안인가요?","mis":"SO6-2-u2-X15"},{"t":"가장 긴 방안인가요?","mis":"SO6-2-u2-X15"}],"explanation":["90쪽 평가표예요.","실천·효과·비용·시간을 봐요.","비용 기준이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#17','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C5',3,'mc','auto','79쪽 자료에서 2023년 우리나라의 1인당 국민 총소득은 ○○ 나라의 몇 배쯤인가요?',ARRAY['SO6-2-u2-X10']::text[],false,'{"seq":17,"concept":"SO6-2-u2-C5","difficulty":3,"kind":"mc","stem":"79쪽 자료에서 2023년 우리나라의 1인당 국민 총소득은 ○○ 나라의 몇 배쯤인가요?","options":[{"t":"8배가 넘어요","correct":true},{"t":"2배쯤이에요","mis":"SO6-2-u2-X10"},{"t":"20배가 넘어요","mis":"SO6-2-u2-X10"}],"explanation":["4,230의 8배는 33,840이에요.","35,490은 그보다 커요.","8배가 넘어요."],"asset":{"type":"passage","lines":["연도 — 1960 · 1970 · 1980 · 1990 · 2000 · 2010 · 2023","우리나라 — 120 · 280 · 1,870 · 6,450 · 11,030 · 22,290 · 35,490","○○ 나라 — 230 · 240 · 770 · 830 · 1,180 · 2,360 · 4,230","(단위: 달러 · 꺾은선그래프를 글로 옮김)"],"numbered":false,"title":"『사회』 79쪽 — 1인당 국민 총소득 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#18','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C11',3,'essay','teacher','108쪽처럼 나라가 수입품에 높은 관세를 부과하는 까닭을 철강 제품의 예를 들어 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"essay","stem":"108쪽처럼 나라가 수입품에 높은 관세를 부과하는 까닭을 철강 제품의 예를 들어 쓰세요.","answer_guide":{"answer":"예: 수입품 값이 올라 국내 상품이 경쟁력을 갖추게 해 국내 산업을 보호하고 성장시키려고요. 우리나라는 1970년대 수입 철강에 높은 관세를 부과해 세계적인 철강 산업 국가가 됐어요.","scoring_points":["국내 산업 보호를 썼는가","철강 예를 바르게 들었는가","관세와 경쟁력을 이었는가"]},"explanation":["관세는 수입품에 매겨요.","국내 상품은 어떻게 되나요?","철강 예를 들어요."],"asset":{"type":"passage","lines":["1970년대 우리나라는 제철소를 짓고 자체 기술로 철강 제품을 만들려고 노력했어요.","당시 우리나라는 수입 철강 제품에 높은 관세를 부과했어요.","그 결과 국내에서 생산한 철강 제품이 수입 철강 제품보다 더 높은 경쟁력을 갖췄어요.","오늘날 우리나라는 세계적인 철강 산업 국가로 성장했어요.","철강 제품은 건축, 자동차, 가전, 선박 등 다양한 산업의 기초 소재예요."],"numbered":false,"title":"『사회』 108쪽 스스로 활동 — 철강 제품과 관세"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#19','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C7',3,'mc','auto','86쪽 자료에서 상대적 빈곤율이 대한민국보다 높은 나라는 몇 개인가요?',ARRAY['SO6-2-u2-X14']::text[],false,'{"seq":19,"concept":"SO6-2-u2-C7","difficulty":3,"kind":"mc","stem":"86쪽 자료에서 상대적 빈곤율이 대한민국보다 높은 나라는 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"6개","mis":"SO6-2-u2-X14"},{"t":"1개","mis":"SO6-2-u2-X14"}],"explanation":["14.9보다 큰 값을 세요.","코스타리카·미국·이스라엘이에요.","3개예요."],"asset":{"type":"passage","lines":["(간추림) 1950년대 우리나라는 세계에서 손꼽히게 가난한 나라였다.","빠른 경제성장으로 세계 10위의 경제 대국이 되었고, 2021년 선진국으로 인정받았다.","하지만 OECD 국가 중 상대적 빈곤율이 높은 편이다.","상대적 빈곤율 = 전체 인구 중 빈곤 위험에 처한 인구 비율","2022년(%) 코스타리카 21.2 · 미국 18.1 · 이스라엘 16.8 · 대한민국 14.9","(이어서) 뉴질랜드 14.3 · 에스파냐 13.7 · 캐나다 11.9 · 영국 11.8","(이어서) 프랑스 8.3 · 노르웨이 8.0"],"numbered":false,"title":"『사회』 86쪽 신문 기사 「상대적 빈곤율 OECD 국가 중 높아 … 빈부 격차 심각」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#20','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C11',3,'mc','auto','활동지 이야기에서 서아프리카 카카오 농장주들이 어린이들을 일하게 하는 까닭은 무엇인가요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":20,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"mc","stem":"활동지 이야기에서 서아프리카 카카오 농장주들이 어린이들을 일하게 하는 까닭은 무엇인가요?","options":[{"t":"초콜릿 가격을 낮추려고 낮은 임금으로 일을 시키려고","correct":true},{"t":"어린이들의 기술이 가장 뛰어나서","mis":"SO6-2-u2-X20"},{"t":"어린이 노동이 무역에 꼭 필요해서","mis":"SO6-2-u2-X20"}],"explanation":["가격을 낮추려 해요.","임금을 적게 주려 해요.","그래서 어린이를 찾아요."],"asset":{"type":"passage","lines":["코트디부아르 카카오 농장에서 일하는 카이는 아홉 살이에요.","하루 종일 10 m가 넘는 카카오나무를 오르내리며 열매를 따요.","카이 몸집만 한 바구니는 6 kg이 넘고, 농약 냄새에 어질어질해요.","전 세계 카카오의 70 %가 서아프리카에서 생산돼요.","농장주들은 초콜릿 가격을 낮추려고 낮은 임금으로 일할 아이들을 찾아요."],"title":"활동지 — 공정 무역 이야기(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#21','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C6',3,'ox','auto','경제가 빠르게 성장하면 좋은 점만 생기고 문제는 생기지 않아요.',ARRAY['SO6-2-u2-X12']::text[],false,'{"seq":21,"concept":"SO6-2-u2-C6","difficulty":3,"kind":"ox","stem":"경제가 빠르게 성장하면 좋은 점만 생기고 문제는 생기지 않아요.","answer":"X","reason_options":[{"t":"환경 문제, 빈부 격차, 과소비, 노사 갈등 같은 문제도 함께 생겼기 때문에","correct":true},{"t":"성장은 늘 모든 것을 좋게 하기 때문에","mis":"SO6-2-u2-X12"}],"mis":"SO6-2-u2-X12","explanation":["85~87쪽이에요.","문제도 생겼어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#22','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C2',3,'mc','auto','64쪽에서 자동차 ②를 고른 가족이 들 수 있는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO6-2-u2-X05']::text[],false,'{"seq":22,"concept":"SO6-2-u2-C2","difficulty":3,"kind":"mc","stem":"64쪽에서 자동차 ②를 고른 가족이 들 수 있는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"중고차지만 가격이 가장 저렴하고 승차감이 편안해서","correct":true},{"t":"9인승이라 가장 넓어서","mis":"SO6-2-u2-X05"},{"t":"연비가 가장 좋아서","mis":"SO6-2-u2-X05"}],"explanation":["②는 2천만 원이에요.","중고차, 승차감이 편안해요.","그 까닭이 맞아요."],"asset":{"type":"passage","lines":["모아 둔 돈 — 5천만 원","자동차 ① — 7인승 · 3천만 원 · 품질 보증 5년 · 1 L로 15 km","①의 그 밖의 특징 — 시야가 높아 운전하기 편함 · 스마트폰으로 제어","자동차 ② — 5인승 · 2천만 원 · 품질 보증 3년 · 1 L로 10 km","②의 그 밖의 특징 — 인공지능 시스템 · 중고차이나 승차감이 편안함","자동차 ③ — 9인승 · 4천만 원 · 품질 보증 5년 · 1 L로 9 km","③의 그 밖의 특징 — 인공지능 시스템 · 실내 공기 청정기"],"numbered":false,"title":"『사회』 64쪽 할 수 있어요 — 우리 가족이 살 자동차"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#23','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C3',4,'essay','teacher','근로자의 권리를 보호하는 캠페인 포스터를 만든다면 제작 의도, 넣고 싶은 문구, 그림으로 나타낼 내용을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO6-2-u2-C3","difficulty":4,"kind":"essay","stem":"근로자의 권리를 보호하는 캠페인 포스터를 만든다면 제작 의도, 넣고 싶은 문구, 그림으로 나타낼 내용을 쓰세요.","answer_guide":{"answer":"예: 의도 — 근로자가 행복하게 일하면 나라가 더 발전한다는 것을 알리려고요. 문구 — 근로자가 행복하게 일할 수 있는 문화, 우리 모두 함께해요. 그림 — 근로자와 기업 대표가 악수하는 모습.","scoring_points":["제작 의도를 썼는가","권리를 담은 문구를 썼는가","그림 내용을 썼는가"]},"explanation":["왜 만드나요?","무엇을 전하나요?","어떻게 그릴까요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#24','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C10',4,'essay','teacher','102쪽처럼 우리나라 무역 뉴스를 조사했다면 정리할 내용을 쓰세요(수출하는 나라, 물자나 서비스, 수입하는 나라, 알게 된 점).','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u2-C10","difficulty":4,"kind":"essay","stem":"102쪽처럼 우리나라 무역 뉴스를 조사했다면 정리할 내용을 쓰세요(수출하는 나라, 물자나 서비스, 수입하는 나라, 알게 된 점).","answer_guide":{"answer":"예: 수출하는 나라 — 우리나라, 물자 — 김, 수입하는 나라 — 타이. 타이에서 김 과자가 인기라 김 수출액이 역대 최고를 기록했다는 것을 알게 됐어요.","scoring_points":["수출국과 수입국을 썼는가","물자나 서비스를 썼는가","알게 된 점을 썼는가"]},"explanation":["누가 누구에게 파나요?","무엇을 파나요?","알게 된 점을 써요."],"asset":{"type":"passage","lines":["뉴스 제목 — K-김 수출 1위 시장은 ‘김 과자 큰손’인 이 나라","우리나라 김 수출액이 2023년 약 4,086억 원으로 역대 최고치를 기록했다.","우리나라 김이 가장 많이 수출된 나라는 타이이다.","타이에서 김 과자가 인기를 끌면서 김 수출량도 늘고 있다."],"title":"『사회』 102쪽 디지털+ 할 수 있어요 — 조사한 뉴스 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u2_review_d#25','soc',6,2,'u2','','tb_g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C11',4,'essay','teacher','기업이 베트남처럼 노동력이 저렴한 나라에서 생산할 때 좋은 점과 함께 지켜야 할 점을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u2-C11","difficulty":4,"kind":"essay","stem":"기업이 베트남처럼 노동력이 저렴한 나라에서 생산할 때 좋은 점과 함께 지켜야 할 점을 쓰세요.","answer_guide":{"answer":"예: 일하는 사람은 소득을 얻고 소비자는 더 싸게 살 수 있어요. 하지만 근로자에게 정당한 임금을 주고 환경을 오염하지 않아야 해요.","scoring_points":["좋은 점을 썼는가","정당한 임금을 썼는가","환경 등 지킬 점을 썼는가"]},"explanation":["누가 좋아지나요?","무엇을 지켜야 하나요?","분배를 생각해요."],"asset":{"type":"passage","lines":["(간추림) 베트남으로 생산 시설을 옮기는 외국 기업이 늘고 있다.","주된 이유는 저렴한 노동력이다.","중국과 국경을 맞대고 있어 생산한 물자를 중국에 쉽게 공급할 수 있다.","베트남에서 생산한 제품에 낮은 관세를 부과하기로 약속한 나라가 많다.","미국, 중국 기업을 비롯해 우리나라 기업들도 베트남에서 생산 시설을 운영한다."],"numbered":false,"title":"『사회』 109쪽 신문 기사 「베트남으로 향하는 외국 기업의 생산 시설」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
